import React, { useCallback, useEffect, useRef, useState } from "react";
import { Button, Divider, Image, Modal, Space, Typography } from "antd";
import * as htmlToImage from "html-to-image";
import { useDispatch, useSelector } from "react-redux";
import baseAPI from "../../../api/baseAPI";
import moment from "moment/moment";
import "moment/locale/th";
import { currencyFormatTH } from "../../../utils/numberFormat";
import { useNavigate } from "react-router-dom";
import header from "../../../assets/images/logo-receipt-128.png";
import qrcode from "../../../assets/images/qr-line-128.jpg";

const { Text } = Typography;

export default function Receipt() {
  const navigate = useNavigate();
  const order = useSelector((state) => state.toijeeOrder);
  // const [data, setData] = useState({ products: [] });

  console.log("RECEIPT ORDER", order);

  // console.log("RECEIPT", order);
  const ref = useRef();

  const takeScreenShot = async (node) => {
    const dataURI = await htmlToImage.toPng(node);
    return dataURI;
  };

  const download = (image, { name = "img", extension = "png" } = {}) => {
    const a = document.createElement("a");
    a.href = image;
    a.download = "receipt";
    // a.download = createFileName(extension, name);
    a.click();
  };

  const getImage = () => {
    console.log(ref.current);
    takeScreenShot(ref.current).then(download);
  };

  const onButtonClick = useCallback(() => {
    if (ref.current === null) {
      return;
    }

    htmlToImage
      .toPng(ref.current, { quality: 0.95 })
      .then((dataUrl) => {
        const link = document.createElement("a");
        link.download = "receipt";
        link.href = dataUrl;
        link.click();
      })
      .catch((err) => {
        console.log(err);
      });
  }, [ref]);

  const RenderCustomerDetail = ({ title1, content1, title2, content2 }) => (
    <div
      style={{
        flexDirection: "row",
        display: "flex",
        width: "100%",
      }}
    >
      <div style={{ width: "65%", display: "flex" }}>
        <Text style={{ fontSize: 9, width: "20%" }}>{title1}</Text>

        <Text strong style={{ fontSize: 9 }}>
          {content1}
        </Text>
      </div>
      <div style={{ width: "35%", display: "flex" }}>
        <Text style={{ fontSize: 9, width: "30%" }}>{title2}</Text>

        <Text strong style={{ fontSize: 9 }}>
          {content2}
        </Text>
      </div>
    </div>
  );
  if (!order) {
    return null;
  }

  return (
    <>
      <Space style={{ margin: 16 }}>
        <Button type="primary" onClick={getImage}>
          ดาวน์โหลดใบเสร็จ
        </Button>
      </Space>

      <div
        ref={ref}
        style={{
          // height: "500px",
          width: "291px",
          // paddingTop: 10,
          // paddingLeft: 5,
          // paddingRight: 5,
          // paddingฺBottom: 10,
          paddingInline: 5,
          backgroundColor: "white",
        }}
      >
        <div
          style={{
            flexDirection: "column",
            justifyContent: "center",
            display: "flex",
            alignItems: "center",
            marginBottom: 10,
          }}
        >
          {/* <img src={header} alt="shrine" width={80} height={80} /> */}
          <Image src={header} width={90} />
          <Text strong style={{ fontSize: 10, marginTop: 8 }}>
            คณะกรรมการจัดงานศาลเจ้าปึงเถ่ากง-ม่า ขอนแก่น ประจำปี 2567
          </Text>
          <Text style={{ fontSize: 7 }}>
            51/14 หมู่ที่ 1 ถนนรอบบึง ต.ในเมือง อ.เมือง จ.ขอนแก่น 40000
            (โทรศัพท์ 043-223437)
          </Text>
          <Text strong style={{ fontSize: 12, marginTop: 4 }}>
            ใบรับเงิน
          </Text>
        </div>

        {/* <div style={{ flexDirection: "column", display: "flex" }}>
          <Space>
            <Text style={{ fontSize: 8 }}>ผู้บริจาค</Text>
            <Text strong style={{ fontSize: 8 }}>
              {order.fullname}
            </Text>
            <Text style={{ fontSize: 8 }}>ผู้บริจาค</Text>
            <Text strong style={{ fontSize: 8 }}>
              {order.fullname}
            </Text>
          </Space>
        </div> */}

        <RenderCustomerDetail
          title1="ผู้บริจาค"
          content1={order.customer_name}
          title2="ถนน"
          content2={order.customer_road}
        />

        <RenderCustomerDetail
          title1="ร้านค้า"
          content1={order.customer_storename}
          title2="วันที่"
          content2={moment(order.payment_date).format("DD/MM/YYYY")}
        />

        <RenderCustomerDetail
          title1="โทรศัพท์"
          content1={order.customer_phone}
          title2="เลขที่"
          content2={order.id}
        />

        {order.phone !== null && order.phone !== "" ? (
          <RenderCustomerDetail
            title1="สำรอง"
            content1={order.phone}
            title2=""
            content2={""}
          />
        ) : null}

        <div style={{ width: "100%", display: "flex" }}>
          <Text style={{ fontSize: 8, width: "13%" }}>ที่อยู่</Text>

          <Text strong style={{ fontSize: 8 }}>
            {order.customer_address}
          </Text>
        </div>
        <div style={{ width: "100%", display: "flex" }}>
          <Text style={{ fontSize: 8, width: "13%" }}>กรรมการ</Text>

          <Text strong style={{ fontSize: 8 }}>
            {order.user_firstname} {order.user_lastname}
          </Text>
        </div>

        <table
          style={{
            width: "100%",
            fontSize: 10,
            // height: "160px",
            // border: "1px solid black",
            borderCollapse: "collapse",
            marginTop: "10px",
          }}
        >
          <thead>
            <tr
              style={{
                height: "10px",
                textAlign: "center",
                border: "1px solid black",
                borderStyle: "dotted ",
                borderCollapse: "collapse",
              }}
            >
              <th>ลำดับ</th>
              <th>รายละเอียดสินค้า</th>
              <th>ราคา/หน่วย</th>
              <th>จำนวน</th>
              <th>รวมเป็นเงิน</th>
            </tr>
          </thead>
          <tbody>
            {order.donate !== 0 && (
              <tr
                key={0}
                style={{
                  height: "10px",
                  textAlign: "center",
                  // border: "1px solid black",
                  // borderCollapse: "collapse",
                }}
              >
                <td style={{ textAlign: "center" }}>1</td>
                <td style={{ textAlign: "left", fontSize: 8 }}>ยอดบริจาค</td>
                <td style={{ textAlign: "center" }}></td>
                <td style={{ textAlign: "center" }}></td>
                <td style={{ textAlign: "center", fontSize: 8 }}>
                  {currencyFormatTH(order.donate)}
                </td>
              </tr>
            )}
          </tbody>
          <tfoot>
            <tr
              style={
                {
                  // fontSize: "10px",
                  // border: "1px solid black",
                  // borderCollapse: "collapse",
                  // borderStyle: "dotted",
                }
              }
            >
              <th
                colSpan="4"
                style={{
                  textAlign: "center",
                }}
              >
                ยอดรวม เป็นเงิน
              </th>
              <th
                style={{
                  textAlign: "center",
                }}
              >
                {currencyFormatTH(order.donate)}
              </th>
            </tr>

            <tr>
              <td
                colSpan="5"
                style={{
                  textAlign: "center",
                  // fontSize: "10px",
                  paddingTop: "10px",
                }}
              >
                ** ชำระโดย: {order.payment} **
              </td>
            </tr>
            {order.mark !== "" && order.mark !== null && (
              <tr>
                <td
                  colSpan="5"
                  style={{
                    textAlign: "center",
                    fontSize: "8px",
                    // paddingTop: "10px",
                  }}
                >
                  หมายเหตุ: {order.mark}
                </td>
              </tr>
            )}
          </tfoot>
        </table>
        <Divider />
        <div
          style={{
            flexDirection: "column",
            display: "flex",
            alignItems: "center",

            // bottom: 0,
            // position: "absolute",
          }}
        >
          <Text style={{ fontSize: 10 }}>** ขอขอบพระคุณ **</Text>
          <Text style={{ fontSize: 10 }}>
            ขอให้ท่านมีแต่ความสุข สุขภาพแข็งแรง และเจริญรุ่งเรืองยิ่งๆขึ้นไป
          </Text>
          <div style={{ marginTop: 10, marginBottom: 20 }}>
            {/* <img src={qrcode} alt="qrcode" width={60} height={60} /> */}
            <Image src={qrcode} width={60} />
          </div>
        </div>
      </div>
    </>
  );
}
