import React, { useEffect, useState } from "react";
import {
  Form,
  Modal,
  Select,
  InputNumber,
  Button,
  DatePicker,
  Radio,
  Space,
  Divider,
  Input,
  Typography,
} from "antd";
import { PlusOutlined, UsergroupAddOutlined } from "@ant-design/icons";

import { useDispatch, useSelector } from "react-redux";
import baseAPI from "../../../api/baseAPI";
import { addOrder, addToiJeeOrder, addToken } from "../../../redux/reduxSlice";
import { Link } from "react-router-dom";
import AddCustomerModal from "../customer/AddCustomerModal";
import moment from "moment";
import dayjs from "dayjs";
import ConfirmOrderModal from "./ConfirmOrderModal";
import { useNavigate } from "react-router-dom";

const { TextArea } = Input;
const { Text } = Typography;

export default function Main() {
  const user = useSelector((state) => state.token);
  const navigate = useNavigate();
  const dispatch = useDispatch();
  const [form] = Form.useForm();
  const [customerList, setCustomerList] = useState([]);
  // const [year, setYear] = useState();
  const [dateSelected, setDateSelected] = useState(
    moment().format("YYYY-MM-DD")
  );
  const [loading, setLoading] = useState(false);
  const [openCustomerModal, setOpenCustomerModal] = useState(false);
  const [selectPrivilege, setSelectPrivilege] = useState(1);
  const [selectPayment, setSelectPayment] = useState(1);
  const [openModalConfirm, setOpenModalConfirm] = useState(false);
  const [customer, setCustomer] = useState(null);

  const [order, setOrder] = useState({});

  useEffect(() => {
    const date = new Date();
    let month = date.getMonth() + 1;
    // let year = date.getFullYear();
    if (month >= 10) {
      // year += 1;
      setDateSelected(moment().add(1, "years").format("YYYY-MM-DD"));
    } else {
      setDateSelected(moment().format("YYYY-MM-DD"));
    }
  }, []);

  //   const [orderList, setOrderList] = useState({});

  const handleClickAddCustomer = (e) => {
    setOpenCustomerModal(true);
    // console.log("AddDonate", e);
  };

  useEffect(() => {
    // setYear(years);
    // console.log("DATE", dateSelected);
    fetchAllCustomers();
  }, [dateSelected]);

  const fetchAllCustomers = async () => {
    setLoading(true);
    await baseAPI
      .get("/city_pillar_shrine/customers", {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        setCustomerList(response.data);
        setLoading(false);
      })
      .catch((err) => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
  };

  const handleSubmitAddCustomer = async (data) => {
    // console.log("SUBMIT ADDCUSTOMER", data);
    setLoading(true);
    await baseAPI
      .post(`/city_pillar_shrine/customers`, data, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        // console.log(response);
        setCustomerList((pre) => [...pre, { ...data, id: response.data.id }]);
        // setCustomersHolder((pre) => [
        //   ...pre,
        //   { ...data, id: response.data.id },
        // ]);
        form.setFieldsValue({ customer_id: response.data.id });
        Modal.success({
          centered: true,
          content: "เพิ่มร้านค้าสำเร็จ",
        });
        setLoading(false);
      })
      .catch((error) => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
    setOpenCustomerModal(false);
  };

  const handleSelectCustomer = (data) => {
    // console.log("DATA SELECTED", data);
    setOpenCustomerModal(false);
  };

  const filterOption = (input, option) =>
    (option?.label ?? "").toLowerCase().includes(input.toLowerCase());

  const onFinish = (values) => {
    const result = {
      customer_id: values.customer_id,
      donate: values.donate,
      mark: values.mark,
      phone: values.phone,
      years: moment(dateSelected).format("YYYY"),
      privilege: selectPrivilege,
      payment_by_id: selectPayment,
    };
    // console.log("SUBMIT", result);
    setOrder(result);
    setOpenModalConfirm(true);
  };

  const onFinishFailed = (values) => {
    console.log("on Failed", values);
  };

  const handleDateChange = (date, dateString) => {
    setDateSelected(dateString);
    // form.setFieldsValue({ years: dateString });
  };

  // const handleDateChange = (date, dateString) => {
  //   if (date) {
  //     // Convert the selected year to Buddhist year
  //     const buddhistYear = date.year() + 543;
  //     const result = moment(buddhistYear).format("YYYY-MM-DD");
  //     setDateSelected(result);
  //   } else {
  //     setDateSelected(null);
  //   }
  // };

  const handleChangePrivilege = (e) => {
    setSelectPrivilege(e.target.value);
  };

  const fetchDataForReceipt = async (id) => {
    setLoading(true);
    await baseAPI
      .get("/city_pillar_shrine/toi-jee/" + id, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        console.log("DATA RECEIPT", response.data[0]);
        setLoading(false);
        dispatch(addToiJeeOrder(response.data[0]));
      })
      .catch((err) => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
  };

  const handleSubmitConfirm = async (data) => {
    // console.log("Submit", data);
    setLoading(true);
    await baseAPI
      .post(`/city_pillar_shrine/toi-jee`, data, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        // setOrderList((pre) => [...pre, { ...data, id: response.data.id }]);
        // console.log("RESPOND", response.data);
        fetchDataForReceipt(response.data.id);
        Modal.success({
          centered: true,
          content: "เพิ่มรายการสำเร็จ",
          onOk: () => {
            Modal.confirm({
              centered: true,
              title: "พิมพ์ใบเสร็จ",
              content: "ต้องการพิมพ์ใบเสร็จหรือไม่?",
              onOk: () => {
                navigate("/toi-jee-list/receipt");
              },
            });
          },
        });

        // navigate("/toi-jee-list");

        setLoading(false);
        setOpenModalConfirm(false);
      })
      .catch((error) => {
        // dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: error.message,
          centered: true,
        });
        setLoading(false);
        setOpenModalConfirm(false);
      });
  };

  const handleChangeCustomer = (e, v) => {
    console.log(e, v);
    setCustomer(v.item);
  };

  // const formatDateToThaiYear = (date) => {
  //   return moment(date).format("DD/MM") + "/" + (moment(date).year() + 543);
  // };

  return (
    <div>
      <Form
        id="form"
        onFinish={onFinish}
        onFinishFailed={onFinishFailed}
        // layout={"vertical"}
        form={form}
        labelCol={{
          span: 8,
        }}
        wrapperCol={{
          span: 16,
        }}
        style={{
          maxWidth: 600,
        }}
      >
        <Form.Item
          name="years"
          label="งานประจำปี"
          initialValue={dayjs(dateSelected, "YYYY")}
          rules={[
            {
              required: true,
              message: "ต้องไม่เว้นว่าง",
            },
          ]}
        >
          <DatePicker
            picker="year"
            onChange={handleDateChange}
            // format="YYYY"
            style={{ width: "100%" }}
          />
        </Form.Item>
        <Form.Item label="ปีที่เลือก พ.ศ.">
          <Text strong>
            {moment(dateSelected).add(543, "years").format("YYYY")}
          </Text>
        </Form.Item>

        <Form.Item
          label="ร้านค้าในระบบ"
          name="customer_id"
          rules={[
            {
              required: true,
              message: "ต้องไม่เว้นว่าง",
            },
          ]}
        >
          <Select
            showSearch
            placeholder="เลือกร้านค้า"
            optionFilterProp="children"
            style={{ width: "100%" }}
            onChange={(e, v) => handleChangeCustomer(e, v)}
            // onSearch={onSearch}
            filterOption={filterOption}
            options={customerList.map((item) => ({
              value: item.id,
              label: item.storename,
              item,
            }))}
          />
        </Form.Item>
        {customer?.address && (
          <Form.Item label="ที่อยู่">
            <TextArea value={customer?.address} />
          </Form.Item>
        )}
        {customer?.phone && (
          <Form.Item label="โทรศัพท์">
            <Input value={customer?.phone} />
          </Form.Item>
        )}
        <Form.Item label="เพิ่มเบอร์กำกับในบิล (ถ้ามี)" name="phone">
          <Input placeholder="ถ้ามี" />
        </Form.Item>
        <Form.Item label="กรณีไม่มีร้านค้าในระบบ">
          <Link
            onClick={handleClickAddCustomer}
            // icon={<PlusOutlined />}
          >
            เพิ่มร้านค้าเอง
          </Link>
        </Form.Item>
        <Form.Item
          label="ยอดบริจาค"
          name="donate"
          rules={[
            {
              required: true,
              message: "ต้องไม่เว้นว่าง",
            },
          ]}
        >
          <InputNumber
            formatter={(value) =>
              `${value}`.replace(/\B(?=(\d{3})+(?!\d))/g, ",")
            }
            //   onChange={handleChangeInput}
            style={{ width: "100%" }}
          />
        </Form.Item>
        <Form.Item label="หมายเหตุ" name="mark">
          <Input placeholder="ถ้ามี" />
        </Form.Item>
        <Radio.Group
          style={{ marginBottom: 16 }}
          onChange={handleChangePrivilege}
          value={selectPrivilege}
        >
          <Space direction="vertical">
            <Radio value={1}>ร่วมเสี่ยงทาย</Radio>
            <Radio value={0}>ไม่ร่วมเสี่ยงทาย</Radio>
          </Space>
        </Radio.Group>
        {/* <Divider /> */}
        <h4>ช่องทางชำระ</h4>
        <Radio.Group
          onChange={(e) => setSelectPayment(e.target.value)}
          value={selectPayment}
        >
          <Space direction="vertical">
            {/* <div
                style={{
                  flexDirection: "row",
                  alignItems: "center",
                  display: "flex",
                  justifyContent: "space-between",
                }}
              > */}
            <Radio value={1}>เงินสด</Radio>
            {/* <InputNumber
                  style={{ width: 150 }}
                  placeholder="ใส่จำนวนเงินรับ"
                  formatter={(value) =>
                    `${value}`.replace(/\B(?=(\d{3})+(?!\d))/g, ",")
                  }
                  onChange={handleChangeAmount}
                /> */}
            {/* </div> */}

            <Radio value={2}>โอนเข้าบัญชี</Radio>
            {/* <Radio value={3}>ชำระภายหลัง</Radio> */}
          </Space>
        </Radio.Group>
        <Divider />
        <Form.Item>
          <Button type="primary" htmlType="submit">
            ยืนยันรายการ
          </Button>
        </Form.Item>
      </Form>

      <Divider />

      <AddCustomerModal
        customers={customerList}
        open={openCustomerModal}
        onClose={setOpenCustomerModal}
        onSubmit={handleSubmitAddCustomer}
        onSelect={handleSelectCustomer}
      />

      <ConfirmOrderModal
        open={openModalConfirm}
        data={order}
        // orderTypeSelect={orderType.filter(
        //   (item) => item.id === orderCreate.order_type_id
        // )}
        onSubmit={handleSubmitConfirm}
        onClose={setOpenModalConfirm}
      />
    </div>
  );
}
