import React, { useEffect, useState } from "react";
import { Modal, Button, Typography, Divider } from "antd";
import dayjs from "dayjs";
import customParseFormat from "dayjs/plugin/customParseFormat";
import moment from "moment";
import { useDispatch, useSelector } from "react-redux";
dayjs.extend(customParseFormat);
const { Text } = Typography;

export default function LotteryDetailModal({ open, data, onCancel, onClose }) {
  const user = useSelector((state) => state.token);

  useEffect(() => {
    // console.log("DATA", data);
  }, [data]);

  const handleClose = () => {
    onClose(false);
  };

  const handleCancel = () => {
    onCancel({ ...data, product_productCancel: true });
  };

  return (
    <Modal
      title="สลากออมสิน"
      centered={true}
      open={open}
      onOk={handleCancel}
      closeIcon={false}
      footer={[
        // <Button key="receipt" onClick={handleDownloadReceipt}>
        //   พิมพ์ใบเสร็จ
        // </Button>,
        <Button key="cancel" danger onClick={handleCancel}>
          ยกเลิกล็อตเตอรี่
        </Button>,
        <Button key="close" onClick={handleClose}>
          ปิด
        </Button>,
      ]}
    >
      <Divider />
      <div
        style={{
          flexDirection: "row",
          justifyContent: "space-between",
          display: "flex",
        }}
      >
        <Text strong>รายการ</Text>
        <Text strong>จำนวน</Text>
      </div>
      <div
        //   key={index}
        style={{
          flexDirection: "row",
          justifyContent: "space-between",
          display: "flex",
        }}
      >
        <Text>{data.product_productName}</Text>
        <Text>{data.product_productAmount}</Text>
      </div>

      <Divider />
    </Modal>
  );
}
