import { Divider, Card, Typography } from "antd";
import React, { useState } from "react";
import { Link } from "react-router-dom";
import AuctionListDetailModal from "./AuctionListDetailModal";

const { Text } = Typography;

export default function AuctionList({ data }) {
  const [openDetailListModal, setOpenDetailListModal] = useState(false);

  const handleClickDetail = () => {
    setOpenDetailListModal(true);
  };
  return (
    <>
      {/* <Divider /> */}
      <Card size="small" style={{ marginTop: 8 }}>
        <Divider orientation="left">รายการบิล เลขที่ {data.bill_no}</Divider>
        <div style={{ flexDirection: "column", display: "flex" }}>
          <Text strong>ชื่อลูกค้า {data.data.customer}</Text>
          <Text>หัวข้อประมูล {data.data.product_name}</Text>
          <Text type="secondary">จำนวน {data.data.price} บาท</Text>
        </div>
        <div style={{ justifyContent: "center", display: "flex" }}>
          <Link onClick={handleClickDetail}>รายการ</Link>
        </div>
      </Card>

      <AuctionListDetailModal
        open={openDetailListModal}
        onClose={setOpenDetailListModal}
        data={data.products}
      />
    </>
  );
}
