import React, { useCallback, useEffect, useRef, useState } from "react";
import { Button, Divider, Image, Modal, Space, Typography } from "antd";
import * as htmlToImage from "html-to-image";
import { useDispatch, useSelector } from "react-redux";
import baseAPI from "../../../api/baseAPI";
import moment from "moment/moment";
import "moment/locale/th";
import { currencyFormatTH } from "../../../utils/numberFormat";
import { useNavigate } from "react-router-dom";

const { Text } = Typography;

export default function ShippingAddress() {
  const navigate = useNavigate();
  const order = useSelector((state) => state.shippingOrder);
  // const [data, setData] = useState({ products: [] });

  console.log("RECEIPT ORDER", order);

  // console.log("RECEIPT", order);
  const ref = useRef();

  const takeScreenShot = async (node) => {
    const dataURI = await htmlToImage.toPng(node);
    return dataURI;
  };

  const download = (image, { name = "img", extension = "png" } = {}) => {
    const a = document.createElement("a");
    a.href = image;
    a.download = "receipt";
    // a.download = createFileName(extension, name);
    a.click();
  };

  const getImage = () => {
    console.log(ref.current);
    takeScreenShot(ref.current).then(download);
  };

  const onButtonClick = useCallback(() => {
    if (ref.current === null) {
      return;
    }

    htmlToImage
      .toPng(ref.current, { quality: 0.95 })
      .then((dataUrl) => {
        const link = document.createElement("a");
        link.download = "receipt";
        link.href = dataUrl;
        link.click();
      })
      .catch((err) => {
        console.log(err);
      });
  }, [ref]);

  if (!order) {
    return null;
  }

  return (
    <>
      <Space style={{ margin: 16 }}>
        <Button type="primary" onClick={getImage}>
          ดาวน์โหลดใบปะหน้า
        </Button>
      </Space>

      <div
        ref={ref}
        style={{
          // height: "500px",
          width: "291px",
          // paddingTop: 10,
          // paddingLeft: 5,
          // paddingRight: 5,
          // paddingฺBottom: 10,
          paddingInline: 5,
          backgroundColor: "white",
        }}
      >
        <div
          style={{
            flexDirection: "column",
            justifyContent: "center",
            display: "flex",
            marginBottom: 10,
          }}
        >
          <Text strong style={{ fontSize: 14, marginTop: 8 }}>
            ผู้ส่ง
          </Text>

          <Text style={{ fontSize: 12, marginTop: 8 }}>
            ศาลเจ้าปึงเถ่ากง-ม่า
          </Text>
          <Text style={{ fontSize: 12 }}>
            51/14 หมู่ที่ 1 ถนนรอบบึง ต.ในเมือง อ.เมือง จ.ขอนแก่น 40000
          </Text>
          <Text style={{ fontSize: 12 }}>โทรศัพท์ 043-223437</Text>
        </div>

        {/* <Divider /> */}
        <div
          style={{
            flexDirection: "column",
            justifyContent: "center",
            display: "flex",
            border: "1px solid black",
            marginBottom: 10,
            padding: "8px",
          }}
        >
          <div
            style={{
              flexDirection: "row",
              justifyContent: "space-between",
              display: "flex",
            }}
          >
            {" "}
            <Text strong style={{ fontSize: 14, marginTop: 8 }}>
              ผู้รับ
            </Text>
            <Text style={{ fontSize: 10 }}>
              รหัสสินค้า {order.order_number}
            </Text>
          </div>

          <Text style={{ fontSize: 12, marginTop: 8 }}>{order.storename}</Text>
          <Text style={{ fontSize: 12 }}>{order.address}</Text>
          <Text style={{ fontSize: 12 }}>ถนน {order.road}</Text>
          <Text style={{ fontSize: 12 }}>โทรศัพท์ {order.phone}</Text>
        </div>
      </div>
    </>
  );
}
