import React, { useEffect, useState } from "react";

import { Typography, Space, Radio, DatePicker, Modal, Select } from "antd";
import UserListSelect from "../UserListSelect";
import baseAPI from "../../../api/baseAPI";
import { useSelector, useDispatch } from "react-redux";
import { addToken } from "../../../redux/reduxSlice";
import dayjs from "dayjs";
import moment from "moment";
import "moment/locale/th";

const { RangePicker } = DatePicker;
const { Text } = Typography;

export default function HistorySearch({ onSearch, searchType, onChangeYear }) {
  //   console.log("TYPE", searchType);
  const user = useSelector((state) => state.token);
  //   const dispatch = useDispatch();
  const [dateSelect, setDateSelect] = useState("");
  const [year, setYear] = useState("");
  const [radioSelected, setRadioSelected] = useState(1);
  const [customerList, setCustomerList] = useState([]);
  const [road, setRoad] = useState([]);

  const onChangeType = (event) => {
    setRadioSelected(event.target.value);
  };

  const onSelectedYear = (date, dateString) => {
    console.log("onChangeYear", dateString);
    if (user.role !== "admin") {
      const arrYear = JSON.parse(user.role_year);
      const yearSelect = arrYear[arrYear.length - 1];
      const includesValue = arrYear.includes(parseInt(dateString));

      if (includesValue) {
        setYear(dateString);
        getLastItem(dateString);
        setDateSelect(moment(dateString.toString()).format("YYYY-MM-DD"));
      } else {
        Modal.warning({
          title: "จำกัดสิทธิ์เข้าถึงข้อมูล",
          content: "ขออภัยคุณไม่มีสิทธิ์เข้าถึงข้อมูลปี " + dateString,
          centered: true,
        });
        setYear(yearSelect);
        getLastItem(dateString);
        setDateSelect(moment(yearSelect.toString()).format("YYYY-MM-DD"));
      }
    } else {
      setYear(year);
      getLastItem(dateString);
      // setDateSelect(moment(`${year}-01-01`, "YYYY-MM-DD").format("YYYY-MM-DD"));
      setDateSelect(moment(year.toString()).format("YYYY-MM-DD"));
    }
  };

  useEffect(() => {
    console.log(user);
    const date = new Date();
    let month = date.getMonth() + 1;
    let year = date.getFullYear();

    if (user.role !== "admin") {
      const arrYear = JSON.parse(user.role_year);
      const yearSelect = arrYear[arrYear.length - 1];
      // console.log("Year Array: ", arrYear);

      if (month >= 11) {
        const includesValue = arrYear.includes(year + 1);
        if (includesValue) {
          setYear(year + 1);
          setDateSelect(moment().add(1, "years").format("YYYY-MM-DD"));
        } else {
          Modal.warning({
            title: "จำกัดสิทธิ์เข้าถึงข้อมูล",
            content: "ขออภัยคุณไม่มีสิทธิ์เข้าถึงข้อมูลปี " + (year + 1),
            centered: true,
          });
          setYear(yearSelect);
          setDateSelect(moment(yearSelect.toString()).format("YYYY-MM-DD"));
        }
      } else {
        const includesValue = arrYear.includes(year);
        if (includesValue) {
          setYear(year);
          setDateSelect(moment(year.toString()).format("YYYY-MM-DD"));
        } else {
          Modal.warning({
            title: "จำกัดสิทธิ์เข้าถึงข้อมูล",
            content: "ขออภัยคุณไม่มีสิทธิ์เข้าถึงข้อมูลปี " + year,
            centered: true,
          });
          setYear(yearSelect);
          setDateSelect(moment(yearSelect.toString()).format("YYYY-MM-DD"));
        }
      }
    } else {
      if (month >= 11) {
        setYear(year + 1);
        setDateSelect(moment().add(1, "years").format("YYYY-MM-DD"));
      } else {
        setYear(year);
        setDateSelect(moment().format("YYYY-MM-DD"));
      }
    }

    fetchAllCustomers();
    fetchAllRoad();
    // fetchAllProducts();
  }, []);

  const fetchAllCustomers = async () => {
    await baseAPI
      .get("/city_pillar_shrine/customers", {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        setCustomerList(response.data);
      })
      .catch((err) => {
        Modal.error({
          title: "ไม่สามารถโหลดข้อมูลได้",
          content: err.message,
          centered: true,
        });
      });
  };

  const fetchAllRoad = async () => {
    await baseAPI
      .get("/city_pillar_shrine/road", {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        setRoad(response.data);
      })
      .catch((err) => {
        Modal.error({
          title: "ไม่สามารถโหลดข้อมูลได้",
          content: err.message,
          centered: true,
        });
      });
  };

  // useEffect(() => {
  //   getLastItem(year);
  //   // setRadioSelected(1);
  // }, [year]);

  useEffect(() => {
    if (radioSelected === 1) {
      getLastItem(year);
    }
  }, [radioSelected, year]);

  const getLastItem = async (year) => {
    let url = "";
    if (searchType === "orders") {
      url = `/city_pillar_shrine/last-orders`;
    } else if (searchType === "maintenance") {
      if (user.role === "admin" || user.role === "editor") {
        url = `/city_pillar_shrine/maintenance`;
      } else url = `/city_pillar_shrine/maintenance/user/${user.id}`;
    } else {
      url = `/city_pillar_shrine/delivery`;
    }
    console.log(url);
    await baseAPI
      .get(url, {
        params: { year },
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((res) => {
        console.log("LAST ITEM", res.data);
        onSearch(res.data);
        if (searchType === "delivery") {
          onChangeYear(year);
        }
      })
      .catch((err) => {
        Modal.error({
          title: "ไม่สามารถโหลดข้อมูลได้",
          content: err.message,
          centered: true,
        });
      });
  };

  const handleChangeDate = async (date, dateString) => {
    // console.log(date, dateString);
    let params = {
      dateStart: dateString[0],
      dateEnd: dateString[1],
      year,
    };

    let url = "";
    if (searchType === "orders") {
      url = `/city_pillar_shrine/orders`;
    } else if (searchType === "maintenance") {
      url = `/city_pillar_shrine/maintenance/date`;
    } else {
      url = `/city_pillar_shrine/delivery/date`;
    }
    await baseAPI
      .get(url, {
        params,
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((res) => {
        console.log(res.data);
        onSearch(res.data);
        if (searchType === "delivery") {
          onChangeYear(year);
        }

        // setLoading(false);
      })
      .catch((err) => {
        Modal.error({
          title: "ไม่สามารถโหลดข้อมูลได้",
          content: err.message,
          centered: true,
        });
      });
  };

  const handleSelectedUser = async (data) => {
    console.log(data);
    let url = "";
    if (searchType === "orders") {
      url = `/city_pillar_shrine/orders/user/${data.id}`;
    } else if (searchType === "maintenance") {
      url = `/city_pillar_shrine/maintenance/user/${data.id}`;
    } else {
    }
    await baseAPI
      .get(url, {
        params: { year },
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((res) => {
        onSearch(res.data);
      })
      .catch((err) => {
        Modal.error({
          title: "ไม่สามารถโหลดข้อมูลได้",
          content: err.message,
          centered: true,
        });
      });
  };

  const handleChangeCustomer = async (e, v) => {
    // console.log(e, v);
    let url = "";
    if (searchType === "orders") {
      url = `/city_pillar_shrine/orders/customer/${e}`;
    } else if (searchType === "maintenance") {
      url = `/city_pillar_shrine/maintenance/customer/${e}`;
    } else {
      url = `/city_pillar_shrine/delivery/customer/${e}`;
    }

    await baseAPI
      .get(url, {
        params: { year },
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((res) => {
        console.log(res.data);
        onSearch(res.data);
        if (searchType === "delivery") {
          onChangeYear(year);
        }
      })
      .catch((err) => {
        Modal.error({
          title: "ไม่สามารถโหลดข้อมูลได้",
          content: err.message,
          centered: true,
        });
      });
  };

  const handleChangeRoad = async (e) => {
    console.log(e);
    const params = {
      road: e,
      year,
    };

    let url = "";
    if (searchType === "delivery") {
      url = `/city_pillar_shrine/delivery/road`;
    } else if (searchType === "maintenance") {
      url = `/city_pillar_shrine/maintenance/road`;
    }

    await baseAPI
      .get(url, {
        params,
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((res) => {
        onSearch(res.data);
        if (searchType === "delivery") {
          onChangeYear(year);
        }

        // setLoading(false);
      })
      .catch((err) => {
        Modal.error({
          title: "ไม่สามารถโหลดข้อมูลได้",
          content: err.message,
          centered: true,
        });
      });
  };

  const filterOption = (input, option) =>
    (option?.label ?? "").toLowerCase().includes(input.toLowerCase());

  if (dateSelect) {
    return (
      <div>
        <div
          style={{
            marginBottom: "24px",
            width: "100%",
            justifyContent: "center",
            display: "flex",
          }}
        >
          <Space>
            <h3>ประจำปี</h3>
            <DatePicker
              onChange={onSelectedYear}
              defaultValue={dayjs(dateSelect, "YYYY")}
              // value={dayjs(dateSelect, "YYYY")}
              picker="year"
            />
          </Space>
        </div>
        <Space direction="vertical">
          <Text strong>ค้นหาจาก</Text>
          <Radio.Group onChange={onChangeType} value={radioSelected}>
            <Space direction="vertical">
              <Radio value={1}>
                {searchType === "orders" ? "วันนี้" : "ล่าสุด"}
              </Radio>
              <Radio value={2}>จากวันที่...ถึงวันที่</Radio>
              {
                searchType !== "delivery" && searchType !== "shrine-event" ? (
                  <Radio value={3}>
                    {searchType === "orders" ? "ชื่อสมาชิก" : "ชื่อผู้ติดตั้ง"}
                  </Radio>
                ) : null
                // <Radio value={6}>ชื่อรายการสินค้า</Radio>
              }

              <Radio value={4}>ชื่อร้านค้า</Radio>
              {searchType !== "orders" && <Radio value={5}>ชื่อถนน</Radio>}
            </Space>
          </Radio.Group>
        </Space>
        <div style={{ width: "100%" }}>
          {radioSelected === 2 && (
            <RangePicker
              style={{ width: "100%", marginTop: "16px" }}
              onChange={handleChangeDate}
            />
          )}
          {radioSelected === 3 && searchType !== "delivery" && (
            <UserListSelect onSelected={handleSelectedUser} />
          )}
          {radioSelected === 4 && (
            <Select
              showSearch
              placeholder="ค้นหาจากชื่อร้าน"
              optionFilterProp="children"
              style={{ marginTop: "16px", width: "100%" }}
              onChange={handleChangeCustomer}
              // onSearch={onSearch}
              filterOption={filterOption}
              options={customerList.map((item) => ({
                value: item.id,
                label: item.storename,
                item,
              }))}
            />
          )}
          {radioSelected === 5 && (
            <Select
              showSearch
              placeholder="ค้นหาจากชื่อถนน"
              optionFilterProp="children"
              style={{ marginTop: "16px", width: "100%" }}
              onChange={handleChangeRoad}
              // onSearch={onSearch}
              filterOption={filterOption}
              options={road.map((item) => ({
                key: item.id,
                value: item.road,
                label: item.road,
              }))}
            />
          )}
        </div>
      </div>
    );
  }
}
