import React from "react";
import OrderCancelItem from "./OrderCancelItem";
import { List } from "antd";

export default function OrderCancelList({ data, onClick }) {
  return (
    <div>
      <List
        // size="small"
        pagination={{
          onChange: (page) => {
            console.log(page);
          },
          pageSize: 10,
        }}
        dataSource={data}
        renderItem={(item, index) => (
          <OrderCancelItem data={item} index={index} onClick={onClick} />
        )}
      />
    </div>
  );
}
