import React, { useEffect, useState } from "react";
import {
  Button,
  Divider,
  InputNumber,
  Modal,
  Radio,
  Space,
  Typography,
} from "antd";
import { PlusOutlined } from "@ant-design/icons";
import { useDispatch, useSelector } from "react-redux";
import { useNavigate, useParams } from "react-router-dom";
import ProductOldList from "./ProductOldList";
import ProductNewList from "./ProductNewList";
import {
  // currencyFormat,
  currencyFormatTH,
} from "../../../../utils/numberFormat";
import baseAPI from "../../../../api/baseAPI";
import AddOrderModal from "../AddOrderModal";
import { addToken } from "../../../../redux/reduxSlice";
import ConfirmOrderModal from "./ConfirmOrderModal";
import moment from "moment";
import Loading from "../../../../utils/Loading";

const { Text } = Typography;

export default function Main() {
  const user = useSelector((state) => state.token);
  const orderOld = useSelector((state) => state.order);
  // console.log("ORDER OLD", orderOld);
  // const { id } = useParams();
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const [productList, setProductList] = useState([]);
  const [productListOld, setProductListOld] = useState([]);
  const [productListAdd, setProductListAdd] = useState([]);
  const [productListHolder, setProductListHolder] = useState([]);
  const [productListNew, setProductListNew] = useState([]);
  const [orderType, setOrderType] = useState([]);
  const [sumProductNewPrice, setSumProductNewPrice] = useState(0);
  const [openProductsModal, setOpenProductsModal] = useState(false);
  const [openConfirmOrderModal, setOpenConfirmOrderModal] = useState(false);
  const [pamentTypeSelect, setPaymentTypeSelect] = useState(1);
  const [orderTypeSelect, setOrderTypeSelect] = useState(0);
  const [orderTypeSelectName, setOrderTypeSelectName] = useState(0);
  // const [productsType, setProductsType] = useState([]);
  const [loading, setLoading] = useState(false);

  const productPrice = orderOld.products.reduce((accumulator, object) => {
    const total = object.price * object.amount;
    return accumulator + total;
  }, 0);

  const sumPriceOld = productPrice + orderOld.donate;

  useEffect(() => {
    // setOrderNew(orderOld?.products);
    setProductListOld(orderOld?.products);
    setProductListHolder(orderOld?.products);
  }, [orderOld]);

  useEffect(() => {
    getProducts();
    getOrderType();
  }, []);

  const getProducts = async () => {
    setLoading(true);
    await baseAPI
      .get(`/city_pillar_shrine/products/active`, {
        params: { year: orderOld.year },
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((res) => {
        setProductList(
          res.data.filter((product) => product.event_id === orderOld.event_id)
        );
        setLoading(false);
      })
      .catch((error) => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
  };

  const getOrderType = async () => {
    setLoading(true);
    await baseAPI
      .get(`/city_pillar_shrine/order-type`, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((res) => {
        setOrderType(res.data);
        setLoading(false);
      })
      .catch((error) => {
        // dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
  };

  useEffect(() => {
    if (orderType?.length > 0) {
      setOrderTypeSelect(orderOld.order_type_id);
      const typeName = orderType.filter(
        (item) => item.id === orderOld.order_type_id
      );
      // console.log(typeName[0].name);
      setOrderTypeSelectName(typeName[0].name);
    }
  }, [orderType]);

  useEffect(() => {
    const productPrice = productListNew.reduce((accumulator, object) => {
      const total = object.price * object.amount;
      return accumulator + total;
    }, 0);

    setSumProductNewPrice(productPrice + orderOld.donate);
    // console.log("ORDER NEW", productListNew);
  }, [productListNew]);

  useEffect(() => {
    // console.log("Product Holder", productListHolder);
  }, [productListHolder]);

  const handleSelectItem = (value, data) => {
    const updateList = productListOld?.map((item) => {
      if (item.productId === data.productId) {
        return { ...item, ...data, id: data.productId, productSelect: value };
      } else {
        return { ...item };
      }
      // return item;
    });

    // console.log("Updated:", updateList);
    setProductListOld(updateList);
    // setProductListHolder([...updateList, ...productListAdd]);
    const holder = updateList.filter((item) => item.productSelect);
    setProductListNew([...holder, ...productListAdd]);
  };

  const handleClickAddItem = () => {
    setOpenProductsModal(true); //
    // console.log("ADD");
  };

  const compareSumPrice = (oldPrice, newPrice) => {
    const sumPrice = oldPrice - newPrice;
    if (sumPrice < 0) {
      return "เพิ่มเงิน " + currencyFormatTH(-sumPrice);
    } else {
      return "คืนเงิน " + currencyFormatTH(sumPrice);
    }
  };

  const handleChangeOrderType = (e) => {
    // console.log("TYPE", e);
    setOrderTypeSelect(e.target.value);
    setOrderTypeSelectName(e.target.item.name);
  };

  const handleSubmitProducts = (data) => {
    // console.log("SUBMIT", data);
    setOpenProductsModal(false);

    const addSelect = data.map((item) => ({ ...item, productSelect: true }));
    const holder = productListOld.filter((item) => item.productSelect);
    setProductListAdd(addSelect);
    setProductListNew([...holder, ...addSelect]);
    // setProductListHolder([...holder, ...addSelect]);
  };

  const handleSubmitOrder = () => {
    setOpenConfirmOrderModal(true);
  };

  const handleSubmitConfirmOrder = (data) => {
    console.log("Old Data", orderOld);
    const orderNumber = moment().format("YYMMDDHHmmss");
    // console.log("CONFIRM", data);
    const newOrder = {
      id: orderOld.id,
      order_number: orderNumber,
      year: orderOld.year,
      donate: orderOld.donate,
      user_id: orderOld.user_id,
      customer_id: orderOld.customer_id,
      total_price: sumProductNewPrice,
      payment_by_id: pamentTypeSelect,
      order_type_id: orderTypeSelect,
      order_refer_id: orderOld.id,
      mark: orderOld.mark,
      productsOld: orderOld.products,
      order_status_id: 4,
      // event_id: orderOld.event,
      ...data,
    };

    console.log("New Order", newOrder);
    postNewOrder(newOrder);
    // setOpenConfirmOrderModal(false); //
  };

  const postNewOrder = async (data) => {
    // console.log("New Data", data);
    // setLoading(true);
    await baseAPI
      .post(`/city_pillar_shrine/orders/refer`, data, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        setLoading(false);
        navigate("/myorders");

        // setOrderCustomer({});
        // setOrderProducts([]);
        // setOrderDonate(0);
        // setDisableAddProductButton(true);
      })
      .catch((error) => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
  };

  if (loading) {
    return <Loading />;
  }

  if (productListOld) {
    return (
      <>
        <div>
          <h4>เลือกจากรายการเดิม</h4>
          <ProductOldList
            data={productListOld}
            onSelectItem={handleSelectItem}
          />
        </div>
        <hr />
        <div
          style={{
            flexDirection: "row",
            display: "flex",
            justifyContent: "space-between",
          }}
        >
          <Text strong type="secondary">
            ยอดบริจาค {currencyFormatTH(orderOld.donate)}
          </Text>
          <h4>ยอดรวม {currencyFormatTH(sumPriceOld)}</h4>
        </div>

        <Divider />

        <div>
          <div
            style={{
              justifyContent: "space-between",
              alignItems: "center",
              display: "flex",
            }}
          >
            <h4>รายการแก้ไข</h4>
            <Button onClick={handleClickAddItem} icon={<PlusOutlined />}>
              เลือกสินค้า
            </Button>
          </div>

          <ProductNewList data={productListNew} />

          {orderOld.event_id === 1 ? (
            <div
              style={{
                flexDirection: "row",
                display: "flex",
                justifyContent: "space-between",
              }}
            >
              <Text strong type="secondary">
                ยอดบริจาค {currencyFormatTH(orderOld.donate)}
              </Text>
              <h4>ยอดรวม {currencyFormatTH(sumProductNewPrice)} </h4>
            </div>
          ) : (
            <div
              style={{
                // flexDirection: "row",
                display: "flex",
                justifyContent: "end",
              }}
            >
              <h4>ยอดรวม {currencyFormatTH(sumProductNewPrice)} </h4>
            </div>
          )}
        </div>
        <Text
          strong
          // type="warning"
          style={{ display: "flex", justifyContent: "flex-end" }}
        >
          ผลต่าง {compareSumPrice(sumPriceOld, sumProductNewPrice)}
        </Text>

        <h4>ช่องทางชำระ</h4>
        <Radio.Group
          onChange={(e) => setPaymentTypeSelect(e.target.value)}
          value={pamentTypeSelect}
        >
          <Space direction="vertical">
            <Radio value={1}>เงินสด</Radio>
            <Radio value={2}>โอนเข้าบัญชี</Radio>
            {orderOld.event_id === 2 && (
              <Radio value={3}>เงินเชื่อ (ชำระภายหลัง)</Radio>
            )}
          </Space>
        </Radio.Group>

        {orderType?.length > 0 && orderOld.event_id === 1 && (
          <>
            <h4>ประเภทบิล</h4>
            <Radio.Group
              onChange={(e) => handleChangeOrderType(e)}
              value={orderTypeSelect}
            >
              <Space direction="vertical">
                {orderType?.map((item) => (
                  <Radio key={item.id} value={item.id} item={item}>
                    {item.name}
                  </Radio>
                ))}
              </Space>
            </Radio.Group>
          </>
        )}
        <Divider />
        <div style={{ justifyContent: "center", display: "flex" }}>
          <Button type="primary" onClick={handleSubmitOrder}>
            ยืนยันรายการ
          </Button>
        </div>

        <AddOrderModal
          data={productList}
          // type={productsType}
          open={openProductsModal}
          onClose={setOpenProductsModal}
          onSubmit={handleSubmitProducts}
        />

        <ConfirmOrderModal
          open={openConfirmOrderModal}
          donate={orderOld.donate}
          event={orderOld.event_id}
          products={productListNew}
          orderTypeSelect={orderTypeSelectName}
          paymentTypeSelect={pamentTypeSelect}
          totalPrice={compareSumPrice(sumPriceOld, sumProductNewPrice)}
          onSubmit={handleSubmitConfirmOrder}
          onClose={setOpenConfirmOrderModal}
        />
      </>
    );
  }
}
