import React from "react";
import { Checkbox, Select, Space, Tag, Typography } from "antd";
// import { currencyFormatTH } from "../../../utils/numberFormat";

const { Text } = Typography;
export default function ProductSelectItem({ data, onSelectItem }) {
  const handleSelectItem = (e) => {
    onSelectItem(e.target.checked, data);
  };

  return (
    <div
      style={{
        flexDirection: "row",
        display: "flex",
        justifyContent: "space-between",
      }}
    >
      <Checkbox
        // style={{ width: "100%" }}
        disabled={data.order_product_delivery_id === 3}
        defaultChecked={data.order_product_delivery_id === 3}
        onChange={handleSelectItem}
      >
        <div
          style={{
            width: "100%",
            flexDirection: "row",
            justifyContent: "space-between",
            display: "flex",
          }}
        >
          <Text>
            (x{data.amount}) {data.name}
          </Text>
        </div>
      </Checkbox>
      {data.order_product_delivery_id === 1 ? (
        <Tag color="processing">รอจัดส่ง</Tag>
      ) : (
        <Tag color="success">ส่งแล้ว</Tag>
      )}
      {/* <Select
        defaultValue="lucy"
        style={{
          width: 120,
        }}
        disabled
        options={[
          {
            value: "lucy",
            label: "Lucy",
          },
        ]}
      /> */}
    </div>
  );
}
