import { Button, Divider, Modal, Select, Space } from "antd";
import React, { useEffect, useState } from "react";
import { ShopOutlined } from "@ant-design/icons";
import CustomerList from "./CustomerList";
import baseAPI from "../../../api/baseAPI";
import AddCustomerModal from "./AddCustomerModal";
import EditCustomerModal from "./EditCutomerModal";
import CustomerDetailModal from "./CustomerDetailModal";
import { useDispatch, useSelector } from "react-redux";
import Loading from "../../../utils/Loading";
import { useNavigate } from "react-router-dom";
import { addToken } from "../../../redux/reduxSlice";
import CustomerReport from "./report/CustomerReport";
import AddRoadModal from "./AddRoadModal";
import CustomerMemberListModal from "./CustomerMemberListModal";

export default function Main() {
  const user = useSelector((state) => state.token);
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const [customers, setCustomers] = useState([]);
  const [customerMembers, setCustomerMembers] = useState([]);
  const [customersHolder, setCustomersHolder] = useState([]);
  const [customerEdit, setCustomerEdit] = useState({});
  const [customerSelect, setCustomerSelect] = useState({});
  const [openRoadModal, setOpenRoadModal] = useState(false);
  const [openCustomerModal, setOpenCustomerModal] = useState(false);
  const [openCustomerEditModal, setOpenCustomerEditModal] = useState(false);
  const [openCustomerDetailsModal, setOpenCustomerDetailsModal] =
    useState(false);
  const [openCustomerMembersModal, setOpenCustomerMembersModal] =
    useState(false);

  const [loading, setLoading] = useState(false);

  useEffect(() => {
    fetchAllCustomers();
  }, []);

  // useEffect(() => {

  // }, [customerEdit]);

  const fetchAllCustomers = async () => {
    setLoading(true);
    await baseAPI
      .get(`/city_pillar_shrine/customers`, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((res) => {
        // console.log(res.data);
        setCustomers(res.data);
        setCustomersHolder(res.data);
        setLoading(false);
      })
      .catch((err) => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
  };

  const handleEdit = (data) => {
    console.log("Before Edit", data);
    setCustomerEdit(data);
    setOpenCustomerEditModal(true);
  };

  const handleClickAddCustomer = () => {
    setOpenCustomerModal(true);
  };

  const handleSubmitAddCustomer = async (data) => {
    // console.log("Submit", data);
    setLoading(true);
    await baseAPI
      .post(`/city_pillar_shrine/customers`, data, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        // console.log(response);
        setCustomers((pre) => [...pre, { ...data, id: response.data.id }]);
        setCustomersHolder((pre) => [
          ...pre,
          { ...data, id: response.data.id },
        ]);
        Modal.success({
          centered: true,
          content: "เพิ่มร้านค้าสำเร็จ",
        });
        setLoading(false);
      })
      .catch((error) => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
    setOpenCustomerModal(false);
  };

  const handleSubmitEdit = async (data) => {
    console.log("Submit Edit", data);
    setLoading(true);
    await baseAPI
      .put(`/city_pillar_shrine/customers`, data, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then(() => {
        Modal.success({
          centered: true,
          content: "อัพเดตข้อมูลสำเร็จ",
        });
        const newState = customersHolder.map((obj) => {
          if (obj.id === data.id) {
            return { ...obj, ...data };
          }
          return obj;
        });
        setCustomers(newState);
        setCustomersHolder(newState);
        setLoading(false);
      })
      .catch((err) => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });

    setOpenCustomerEditModal(false);
  };

  const handleDeleteCutomer = async (data) => {
    setOpenCustomerEditModal(false);
    setLoading(true);
    await baseAPI
      .delete(`/city_pillar_shrine/customers/${data.id}`, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then(() => {
        Modal.success({
          centered: true,
          content: "ลบข้อมูลสำเร็จ",
        });
        setLoading(false);
      })
      .catch((err) => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
    const result = customers.filter((item) => item.id !== data.id);
    setCustomers(result);
    // console.log("Delete User", data);
  };

  const handleSubmitAddRoad = async (data) => {
    console.log("ADD ROAD", data);
    await baseAPI
      .post(`/city_pillar_shrine/khonkaen-road`, data, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        Modal.success({
          centered: true,
          content: "เพิ่มร้านค้าสำเร็จ",
        });
        setLoading(false);
      })
      .catch((error) => {
        // dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: error.message,
          centered: true,
        });
        setLoading(false);
      });
    setOpenRoadModal(false);
  };

  const handleClickAddRoad = () => {
    setOpenRoadModal(true);
  };

  const handleClickItem = (data) => {
    setCustomerSelect(data);
    setOpenCustomerDetailsModal(true);
  };

  const handleSelectCustomer = (data) => {
    setOpenCustomerModal(false);
  };

  const handleChangeCustomer = async (e, v) => {
    if (e) {
      const result = customersHolder.filter((customers) => customers.id === e);
      setCustomers(result);
    }
  };

  const handleClickMember = (data) => {
    // console.log("Member", data);
    fetchCustomerMemberByCustomerId(data.id);
  };

  const handleAddCustomerMember = (data) => {
    setOpenCustomerMembersModal(false);
    addCustomerMemberByCustomerId(data);
  };

  const handleDeleteCustomerMember = (data) => {
    console.log("Delete Member", data);
  };

  const fetchCustomerMemberByCustomerId = async (id) => {
    // setLoading(true);
    await baseAPI
      .get(`/city_pillar_shrine/customers/members/${id}`, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((res) => {
        // console.log(res.data);
        setCustomerMembers(res.data);
        setOpenCustomerMembersModal(true);
        // setCustomersHolder(res.data);
        setLoading(false);
      })
      .catch((err) => {
        // dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
  };

  const addCustomerMemberByCustomerId = async (data) => {
    console.log("ADD MEMBER", data);
    setLoading(true);
    await baseAPI
      .post(`/city_pillar_shrine/customers/members/${data.customer_id}`, data, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((res) => {
        setLoading(false);

        Modal.success({
          title: "บันทึกสำเร็จ",
          content: "เพิ่มสมาชิกร้านค้าสำเร็จ",
          centered: true,
        });
      })
      .catch((err) => {
        // dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
  };

  const filterOption = (input, option) =>
    (option?.label ?? "").toLowerCase().includes(input.toLowerCase());

  if (loading) return <Loading />;

  return (
    <div>
      <div
        style={{
          justifyContent: "end",
          display: "flex",
        }}
      >
        <Space>
          <Button onClick={handleClickAddRoad} icon={<ShopOutlined />}>
            เพิ่มถนน
          </Button>
          <Button onClick={handleClickAddCustomer} icon={<ShopOutlined />}>
            เพิ่มร้านค้า
          </Button>
        </Space>
      </div>

      <Divider />
      <CustomerReport data={customers} />
      <Select
        showSearch
        placeholder="ค้นหาจากชื่อร้าน"
        optionFilterProp="children"
        style={{ marginTop: "16px", width: "100%" }}
        onChange={handleChangeCustomer}
        // onSearch={onSearch}
        filterOption={filterOption}
        options={customersHolder.map((item) => ({
          value: item.id,
          label: item.storename,
          item,
        }))}
      />
      <CustomerList
        data={customers}
        onEdit={handleEdit}
        onClickMember={handleClickMember}
        onClickItem={handleClickItem}
      />

      <AddCustomerModal
        customers={customers}
        open={openCustomerModal}
        onClose={setOpenCustomerModal}
        onSubmit={handleSubmitAddCustomer}
        onSelect={handleSelectCustomer}
      />
      <EditCustomerModal
        data={customerEdit}
        open={openCustomerEditModal}
        onClose={setOpenCustomerEditModal}
        onSubmit={handleSubmitEdit}
        onDelete={handleDeleteCutomer}
      />

      <CustomerDetailModal
        data={customerSelect}
        open={openCustomerDetailsModal}
        onClose={setOpenCustomerDetailsModal}
      />

      <AddRoadModal
        open={openRoadModal}
        onClose={setOpenRoadModal}
        onSubmit={handleSubmitAddRoad}
      />

      <CustomerMemberListModal
        open={openCustomerMembersModal}
        members={customerMembers}
        onClose={setOpenCustomerMembersModal}
        onSubmit={handleAddCustomerMember}
        onDelete={handleDeleteCustomerMember}
      />
    </div>
  );
}
