import React, { useEffect, useState } from "react";
import { Divider, Input, Modal, Space, Typography } from "antd";
import { currencyFormatTH } from "../../../utils/numberFormat";
import { PlusOutlined, MinusOutlined } from "@ant-design/icons";
const { Text } = Typography;

export default function OrderItem({ data, dataSelectedList, onAddOrder }) {
  const [product, setProduct] = useState({ ...data, amount: 0 });

  let count = 0;
  //   count = data.amount;
  useEffect(() => {
    // const newMap = dataSelectedList.filter((item) => item.id === data.id);
    // if (newMap.length > 0) {
    // console.log(newMap[0]);
    // setProduct({ ...newMap[0] });
    // } else {
    setProduct({ ...data, amount: 0 });
    // }
  }, [data]);

  const handleClickAdd = (data) => {
    count = parseInt(product.amount) + 1;

    const checkItemType4 = dataSelectedList.filter(
      (item) => item.type_id === 4
    );

    // console.log("TYPE4", checkItemType4);
    if (data.type_id === 4) {
      if (count > 1) {
        count = 1;
      }
      if (checkItemType4.length > 0) {
        Modal.warning({
          title: "ไม่สามารถเลือกได้มากกว่า 1 ชุด",
          content:
            "1 บิลสามารถเลือกบัตรงานง่วนเซียวได้เพียง 1 ชุดเท่านั้น หากมีมากกว่า 1 ชุดให้เปิดบิลใหม่",
          centered: true,
        });
      } else {
        setProduct({ ...product, amount: count < 0 ? 0 : count });
        const result = {
          ...product,
          amount: count < 0 ? 0 : count,
        };

        onAddOrder(result);
      }
    } else {
      if (count > data.amount) {
        count = data.amount;
      }
      setProduct({ ...product, amount: count < 0 ? 0 : count });
      const result = {
        ...product,
        amount: count < 0 ? 0 : count,
      };

      onAddOrder(result);
    }
  };
  const handleRemove = () => {
    count = parseInt(product.amount) - 1;
    setProduct({ ...product, amount: count < 0 ? 0 : count });
    const result = {
      ...product,
      amount: count < 0 ? 0 : count,
    };
    onAddOrder(result);
  };

  const handleChange = (event) => {
    // console.log("OnChange", event.target.value);
    // count = product.amount + 1;
    setProduct({ ...product, amount: event.target.value });
    const result = {
      ...product,
      amount: event.target.value,
    };
    onAddOrder(result);
  };

  return (
    <div
      style={{
        borderRadius: 10,
        // padding: 8,
        backgroundColor: "white",
      }}
    >
      <div
        style={{
          flexDirection: "row",
          display: "flex",
          justifyContent: "space-between",
        }}
      >
        <div style={{ flexDirection: "column", display: "flex" }}>
          <Text strong>{data.name}</Text>
          <Text type="secondary" style={{ fontSize: 12 }}>
            {currencyFormatTH(data.price)}
          </Text>
          <Text
            style={{ fontSize: 12 }}
            type={data.amount > 10 ? "success" : "danger"}
          >
            เหลือ : {data.amount}
          </Text>
        </div>

        {data.amount > 0 ? (
          <Space>
            {/* <Space direction="vertical" align="center"> */}

            {/* </Space> */}
            <Divider type="vertical" />
            <MinusOutlined onClick={() => handleRemove(data)} />
            <Input
              size="small"
              type="number"
              style={{ width: 50, textAlign: "center" }}
              onChange={handleChange}
              value={product.amount}
            />
            {/* <CustomTextField text={product.amount} /> */}
            <PlusOutlined onClick={() => handleClickAdd(data)} />
          </Space>
        ) : (
          <Text
            style={{ alignSelf: "center", marginRight: 20, display: "flex" }}
            type="secondary"
          >
            สินค้าหมด
          </Text>
        )}
      </div>
      <div
        style={{
          width: "100%",
          borderBottom: "1px solid rgba(128,128,128,0.3)",
          borderRadius: "6px",
          marginBottom: "8px",
        }}
      ></div>
    </div>
  );
}
