import React from "react";
import { List, Tag, Typography } from "antd";
import { Link } from "react-router-dom";

const { Text } = Typography;

export default function AomsinLotItem({ data, onPrint, onClickItem }) {
  const handlePrint = () => {
    onPrint(data);
  };
  return (
    <List.Item
      onClick={() => {
        if (data.product_productCancel !== 1) {
          onClickItem(data);
        }
      }}
      actions={[
        // <Link onClick={handlePrint}>พิมพ์ใบรับของ</Link>,
        // <Link>more</Link>,
        data.product_productCancel === 1 ? (
          <Tag color="red">ยกเลิก</Tag>
        ) : (
          <Tag color="success">ปกติ</Tag>
        ),
      ]}
    >
      <List.Item.Meta
        title={<Text>เลขที่ใบรับ {data.bill_no}</Text>}
        description={
          <div style={{ display: "flex", flexDirection: "column" }}>
            <Text strong>
              {data.product_productName} จำนวน {data.product_productAmount}{" "}
              หน่วย
            </Text>
            <Text>ชื่อลูกค้า {data.customer}</Text>
            <Text type="secondary">
              ออกสลากในนาม {data.product_productLotBy}
            </Text>
            {/* <Text type="secondary">ผู้ติดต่อ {data.user}</Text> */}
          </div>
        }
      />
    </List.Item>
  );
}
