import React, { useEffect, useState } from "react";
import { Button, Modal, Form, Input, Select, Table } from "antd";
export default function AddUserModal({
  open,
  roleYears,
  groups,
  onClose,
  onSubmit,
}) {
  const [form] = Form.useForm();
  const [selectedRowKeys, setSelectedRowKeys] = useState([]);
  const [rows, setRows] = useState([]);

  useEffect(() => {
    const newRows =
      roleYears?.map((item) => ({
        key: item?.years, // Optional chaining here in case item is null or undefined
        years: item?.years, // Optional chaining here as well
      })) ?? [];
    setRows(newRows);
  }, [roleYears]);

  // useEffect(() => {
  //   if (data.role_year) {
  //     const arrayData = JSON.parse(data.role_year);
  //     setSelectedRowKeys(arrayData);
  //   } else {
  //     setSelectedRowKeys([]);
  //   }
  // }, [data]);

  const onSelectChange = (newSelectedRowKeys) => {
    console.log("selectedRowKeys changed: ", newSelectedRowKeys);
    setSelectedRowKeys(newSelectedRowKeys);
  };
  const rowSelection = {
    selectedRowKeys,
    onChange: onSelectChange,
  };

  const handleClose = () => {
    onClose(false);
  };
  const handleSubmit = (data) => {
    const jsonString = JSON.stringify(selectedRowKeys);
    console.log(jsonString);
    const newData = {
      ...data,
      role_year: jsonString,
    };
    onSubmit(newData);
  };

  const onFinishFailed = (e) => {
    console.log("Failure", e);
  };

  const role = [
    {
      value: 1,
      label: "ผู้ดูแลระบบ",
    },
    {
      value: 2,
      label: "ผู้แก้ไข",
    },
    {
      value: 3,
      label: "ผู้ขาย",
    },
    {
      value: 4,
      label: "ผู้ติดตั้ง",
    },
    {
      value: 5,
      label: "ผู้จัดส่งสินค้า",
    },
  ];

  const columns = [
    {
      title: "ปีที่มีสิทธิ์เข้าถึงข้อมูล",
      dataIndex: "years",
    },
  ];

  return (
    <Modal
      title="เพิ่ม/แก้ไข สมาชิก"
      centered={true}
      // width={1000}
      open={open}
      //   onOk={handleSubmit}
      closeIcon={false}
      onCancel={handleClose}
      footer={[
        <Button key="close" onClick={handleClose}>
          ยกเลิก
        </Button>,
        <Button
          key="submit"
          htmlType="submit"
          type="primary"
          onClick={form.submit}
        >
          บันทึก
        </Button>,
      ]}
    >
      <Form
        id="form"
        onFinish={handleSubmit}
        onFinishFailed={onFinishFailed}
        layout={"vertical"}
        form={form}
      >
        {/* <div style={{ justifyContent: "end", display: "flex" }}>
          <Button onClick={handleSearchClick}>ค้นหาร้านค้าจากระบบ</Button>
        </div> */}

        <Form.Item name="firstname" label="ชื่อ">
          <Input placeholder="ชื่อ" />
        </Form.Item>
        <Form.Item name="lastname" label="นามสกุล">
          <Input placeholder="นามสกุล" />
        </Form.Item>
        <Form.Item name="nickname" label="ชื่อเล่น">
          <Input placeholder="ชื่อเล่น" />
        </Form.Item>
        <Form.Item
          name="address"
          label="ที่อยู่"
          rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
        >
          <Input placeholder="ที่อยู่" />
        </Form.Item>

        <Form.Item
          name="phone"
          label="โทรศัพท์"
          rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
        >
          <Input placeholder="โทรศัพท์" />
        </Form.Item>
        <Form.Item name="line" label="ไลน์">
          <Input placeholder="ไลน์" />
        </Form.Item>
        <Form.Item name="email" label="อีเมล์">
          <Input placeholder="อีเมล์" />
        </Form.Item>
        <Form.Item
          name="role_id"
          label="สิทธิ์การใช้งาน"
          rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
        >
          <Select
            size="large"
            placeholder="สิทธิ์การใช้งาน"
            options={role.map((item) => ({
              value: item.value,
              label: item.label,
            }))}
          />
        </Form.Item>
        <Form.Item name="groupId" label="กลุ่ม">
          <Select
            size="large"
            placeholder="กลุ่ม"
            options={groups.map((item) => ({
              value: item.id,
              label: item.name,
            }))}
          />
        </Form.Item>
      </Form>

      <Table rowSelection={rowSelection} columns={columns} dataSource={rows} />
    </Modal>
  );
}
