import React, { useEffect, useState } from "react";
import { Button, Modal, Form, Input, Select, Radio, Space } from "antd";
import GoogleMapReact from "google-map-react";

import MarkerImg from "../../../assets/images/Marker.png";
import { GOOGLEMAP_API_KEY } from "../../../utils/googlemapkey";

const Marker = () => (
  <div>
    <img width={30} src={MarkerImg} alt="" />
    {/* <HomeFilled /> */}
  </div>
);

export default function EditCustomerModal({
  open,
  data,
  groups,
  onClose,
  onSubmit,
  onDelete,
}) {
  let lat = 0;
  let lng = 0;
  if (!isNaN(data?.latitude)) {
    lat = parseFloat(data?.latitude);
    lng = parseFloat(data?.longitude);
  }

  const [select, setSelect] = useState(1);

  const defaultProps = {
    center: {
      lat,
      lng,
    },
    zoom: 12,
  };

  const [marker, setMarker] = useState({});

  const [form] = Form.useForm();
  const handleClose = () => {
    onClose(false);
  };
  const handleSubmit = (value) => {
    const group = {
      ...data,
      ...value,
      latitude: marker.lat || lat,
      longitude: marker.lng || lng,
    };
    onSubmit(group);
  };

  useEffect(() => {
    return () => {
      setMarker({});
    };
  }, [data]);

  const onFinishFailed = (e) => {
    console.log("Failure", e);
  };

  const onMapClick = (data) => {
    console.log("MapClick", data);
    setMarker({
      lat: data.lat,
      lng: data.lng,
    });
  };

  const handleDelete = () => {
    Modal.confirm({
      title: "ลบข้อมูลร้านค้า",
      content: "ต้องการลบข้อมูลร้านค้านี้?",
      centered: true,
      onOk: () => {
        onDelete(data);
      },
      okText: "ลบ",
      cancelText: "ยกเลิก",
    });
  };

  const handleChageLatLng = (e) => {
    const result = e.target.value;
    // console.log(result);
    const arr = result.split(",");
    console.log(arr);

    setMarker({
      lat: arr[0],
      lng: arr[1],
    });
  };

  const onMapLoad = () => {
    setMarker({
      lat,
      lng,
    });
  };

  if (data.id) {
    return (
      <Modal
        destroyOnClose={true}
        title="แก้ไขข้อมูลร้านค้า"
        centered={true}
        // width={1000}
        open={open}
        //   onOk={handleSubmit}
        closeIcon={false}
        onCancel={handleClose}
        footer={[
          <Button danger key="delete" onClick={handleDelete}>
            ลบ
          </Button>,
          <Button key="close" onClick={handleClose}>
            ยกเลิก
          </Button>,
          <Button
            key="submit"
            htmlType="submit"
            type="primary"
            onClick={form.submit}
          >
            บันทึก
          </Button>,
        ]}
      >
        <Form
          id="form"
          preserve={false}
          onFinish={handleSubmit}
          onFinishFailed={onFinishFailed}
          layout={"vertical"}
          form={form}
        >
          <Form.Item
            name="storename"
            label="ชื่อร้านค้า"
            initialValue={data.storename}
          >
            <Input placeholder="ชื่อ" />
          </Form.Item>
          {/* <Form.Item
            name="fullname"
            label="ชื่อ-สกุล"
            initialValue={data.fullname}
          >
            <Input placeholder="ชื่อ" />
          </Form.Item> */}
          <Form.Item name="address" label="ที่อยู่" initialValue={data.address}>
            <Input placeholder="ที่อยู่" />
          </Form.Item>
          <Form.Item name="road" label="สาย/ถนน" initialValue={data.road}>
            <Input placeholder="ถนน" />
          </Form.Item>
          <Radio.Group
            style={{ marginBottom: 16 }}
            onChange={(e) => setSelect(e.target.value)}
            value={select}
          >
            <Space direction="vertical">
              <Radio value={1}>เลือกพิกัดเอง</Radio>
              <Radio value={2}>พิกัดจาก GoogleMap</Radio>
            </Space>
          </Radio.Group>

          {select === 1 ? (
            <>
              <div style={{ height: "350px", width: "100%", marginBottom: 16 }}>
                <GoogleMapReact
                  bootstrapURLKeys={{ key: GOOGLEMAP_API_KEY }}
                  center={defaultProps.center}
                  defaultZoom={defaultProps.zoom}
                  yesIWantToUseGoogleMapApiInternals
                  onClick={onMapClick}
                  onGoogleApiLoaded={onMapLoad}
                >
                  <Marker lat={marker.lat || lat} lng={marker.lng || lng} />
                </GoogleMapReact>
              </div>
            </>
          ) : (
            <div>
              <Form.Item label="ใส่พิกัดเป็น Lat, Lng ">
                <Input
                  // style={{ width: 150 }}
                  placeholder="เช่น 16.121565313, 102.335565354"
                  // formatter={(value) =>
                  //   `${value}`.replace(/\B(?=(\d{3})+(?!\d))/g, ",")
                  // }
                  onChange={handleChageLatLng}
                />
              </Form.Item>
            </div>
          )}
          {/* แก้ไขตำแหน่งที่อยู่
          <div style={{ height: "350px", width: "100%", marginBottom: 16 }}>
            <GoogleMapReact
              bootstrapURLKeys={{ key: GOOGLEMAP_API_KEY }}
              center={defaultProps.center}
              defaultZoom={defaultProps.zoom}
              yesIWantToUseGoogleMapApiInternals
              onClick={onMapClick}
            >
              <Marker
                lat={marker.lat || latLng.lat}
                lng={marker.lng || latLng.lng}
              />
            </GoogleMapReact>
          </div> */}
          {/* <Form.Item name="phone" label="โทรศัพท์" initialValue={data.phone}>
            <Input placeholder="โทรศัพท์" />
          </Form.Item>

          <Form.Item name="line" label="ไลน์" initialValue={data.line}>
            <Input placeholder="ไลน์" />
          </Form.Item> */}
        </Form>
      </Modal>
    );
  }
}
