import { List, Space, Tag, Typography } from "antd";
import React from "react";
import { Link } from "react-router-dom";

const { Text } = Typography;

export default function OrderTicketItem({ data, onEdit, onClick }) {
  const handleClickItem = () => {
    onClick(data);
  };

  const handleEdit = () => {
    onEdit(data);
  };

  const menuList1 = [<Link onClick={handleEdit}>เลือกโต๊ะ</Link>];

  const menuList2 = [<Link onClick={handleEdit}>แก้ไข</Link>];

  return (
    <List.Item actions={data.ticket_status_id === 1 ? menuList1 : menuList2}>
      <List.Item.Meta
        onClick={() => {
          handleClickItem(data);
        }}
        title={
          <Space>
            <Text>{data.storename}</Text>
          </Space>
        }
        description={
          data.ticket_status_id === 1 ? (
            <div style={{ flexDirection: "column", display: "flex" }}>
              <Text>{data.phone}</Text>
              <Text>{data.name}</Text>
              <Text type="secondary">หมายเหตุ: {data.mark}</Text>
            </div>
          ) : (
            <div style={{ flexDirection: "column", display: "flex" }}>
              <Text>{data.phone}</Text>
              <Text style={{ color: "#108ee9" }}>
                โต๊ะ: {data.ticket_type_id === 1 ? "ปกติ" : "VIP"}
              </Text>
              <Text style={{ color: "#108ee9" }}>
                หมายเลข{" "}
                {data.ticket_type_id === 1
                  ? data.seat_number
                  : data.seat_number_vip}
              </Text>
            </div>
          )
        }
        // description={data.phone}
      />
    </List.Item>
  );
}
