import React, { useEffect, useState } from "react";

import { DatePicker, Modal, InputNumber, Form, Button } from "antd";
import baseAPI from "../../../../api/baseAPI";
import { useSelector, useDispatch } from "react-redux";
import dayjs from "dayjs";
import moment from "moment";

export default function HistorySearch({ onSearch }) {
  //   console.log("TYPE", searchType);
  const user = useSelector((state) => state.token);
  //   const dispatch = useDispatch();
  const [dateSelect, setDateSelect] = useState("");

  useEffect(() => {
    console.log("DATE", dateSelect);
  }, [dateSelect]);

  useEffect(() => {
    const date = new Date();
    let month = date.getMonth() + 1;
    let year = date.getFullYear();
    if (month >= 10) {
      year += 1;
      setDateSelect(moment().add(1, "years").format("YYYY-MM-DD"));
    } else {
      // setYear(year);
      setDateSelect(moment().format("YYYY-MM-DD"));
    }
    fetchAllData(year);
  }, []);

  const fetchAllData = async (year) => {
    let url = "";
    if (user.role === "admin" || user.role === "editor") {
      url = "/city_pillar_shrine/toi-jee";
    } else {
      url = "/city_pillar_shrine/toi-jee/" + user.id;
    }

    await baseAPI
      .get(url, {
        headers: {
          "x-access-token": user.token,
        },
        params: { year },
      })

      .then((response) => {
        onSearch(response.data);
      })
      .catch((err) => {
        // dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: err.message,
          centered: true,
        });
      });
  };

  const getLastItem = async (params) => {
    await baseAPI
      .get(`/city_pillar_shrine//toi-jee-list/amount`, {
        params,
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((res) => {
        console.log(res.data);
        onSearch(res.data);
      })
      .catch((err) => {
        Modal.error({
          title: "ไม่สามารถโหลดข้อมูลได้",
          content: err.message,
          centered: true,
        });
      });
  };

  const onFinish = (values) => {
    let year = dayjs(values.year).format("YYYY");
    // console.log("Success:", customDate);.
    const params = {
      year,
      donateAmount: values.donateAmount,
    };
    getLastItem(params);
  };
  const onFinishFailed = (errorInfo) => {
    console.log("Failed:", errorInfo);
  };

  if (dateSelect) {
    return (
      <div>
        <div
          style={{
            marginBottom: "24px",
            width: "100%",
            justifyContent: "center",
            display: "flex",
          }}
        >
          <Form
            // name="basic"
            labelCol={{
              span: 8,
            }}
            wrapperCol={{
              span: 16,
            }}
            style={{
              maxWidth: "400px",
              width: "350px",
            }}
            initialValues={{
              remember: true,
            }}
            onFinish={onFinish}
            onFinishFailed={onFinishFailed}
            autoComplete="off"
          >
            <Form.Item
              label="ประจำปี"
              name="year"
              initialValue={dayjs(dateSelect, "YYYY")}
              rules={[
                {
                  required: true,
                  message: "ต้องไม่เว้นว่าง!",
                },
              ]}
            >
              <DatePicker
                name="year"
                style={{ width: "100%" }}
                // format="YYYY"
                // onChange={onChangeYear}
                picker="year"
              />
            </Form.Item>

            <Form.Item
              label="ยอดบริจาคขั้นต่ำ"
              name="donateAmount"
              rules={[
                {
                  required: true,
                  message: "ต้องไม่เว้นว่าง!",
                },
              ]}
            >
              <InputNumber
                // size="small"
                name="donateAmount"
                style={{ width: "100%" }}
                formatter={(value) =>
                  `${value}`.replace(/\B(?=(\d{3})+(?!\d))/g, ",")
                }
                // onChange={handleChangeAmount}
              />
            </Form.Item>
            <Form.Item
              wrapperCol={{
                offset: 8,
                span: 16,
              }}
            >
              <Button type="primary" htmlType="submit">
                ค้นหา
              </Button>
            </Form.Item>
          </Form>
        </div>
      </div>
    );
  }
}
