import React from "react";
import { List } from "antd";
import OrderEditItem from "./OrderEditItem";

export default function OrderEditList({ data, onClick }) {
  return (
    <div>
      <List
        // size="small"
        pagination={{
          onChange: (page) => {
            console.log(page);
          },
          pageSize: 10,
        }}
        dataSource={data}
        renderItem={(item, index) =>
          item.order_status_id !== 1 && (
            <OrderEditItem
              data={item}
              index={index}
              onClick={onClick}

              //   onClickStore={onClickStore}
            />
          )
        }
      />
    </div>
  );
}
