import { List } from "antd";
import React from "react";
import OrderItem from "./OrderItem";

export default function OrderList({
  data,
  onClickPrintAddress,
  onClickManageJob,
  onClickItem,
  onClickFinishJobDetail,
}) {
  return (
    <List
      pagination={{
        onChange: (page) => {
          console.log(page);
        },
        pageSize: 10,
      }}
      itemLayout="horizontal"
      dataSource={data}
      renderItem={(item, index) => (
        <OrderItem
          data={item}
          onClickManageJob={onClickManageJob}
          onClickItem={onClickItem}
          onClickFinishJobDetail={onClickFinishJobDetail}
          onClickPrintAddress={onClickPrintAddress}
        />
      )}
    />
  );
}
