import {
  Modal,
  Button,
  Typography,
  Divider,
  List,
  Image,
  Input,
  Space,
} from "antd";
import React, { useEffect, useState } from "react";
// import ProductItem from "./ProductItem";
import CustomerDetail from "../toijee/CustomerDetail";
import { useSelector } from "react-redux";
import { currencyFormat } from "../../../utils/numberFormat";

const { Text } = Typography;

export default function DonateDetailModal({
  open,
  data,
  onclose,
  // onEdit,
  onCancelOrder,
  // onConfirmCancelOrder,
  // onSubmit,
}) {
  // const [products, setProducts] = useState([]);
  const user = useSelector((state) => state.token);
  const [mark, setMark] = useState(data.mark);
  const handleClose = () => {
    onclose(false);
  };

  useEffect(() => {
    setMark(data.mark);
  }, [data]);

  // const handleClickEdit = () => {
  //   onEdit(true);
  // };

  const handleConfirmCancelOrder = () => {
    const status = {
      ...data,
      // id: data.id,
      order_status_id: 3,
      mark: mark,
    };
    Modal.confirm({
      title: "ยืนยันการยกเลิก",
      content: "ต้องการยืนยันการยกเลิกรายการ",
      centered: true,
      onOk: () => {
        onCancelOrder(status);
      },
    });
  };

  const handleCancelOrder = () => {
    const status = {
      ...data,
      // id: data.id,
      order_status_id: 2,
      mark: mark,
    };
    Modal.confirm({
      title: "ยกเลิกรายการ",
      content: "ต้องการยกเลิกรายการสั่งซื้อนี้",
      centered: true,
      onOk: () => {
        onCancelOrder(status);
      },
    });
  };

  // const handleSubmit = () => {
  //   const status = {
  //     ...data,
  //     // id: data.id,
  //     order_status_id: 1,
  //     mark: mark,
  //   };
  //   Modal.confirm({
  //     title: "บันทึกการแก้ไข",
  //     content: "ต้องการบันทึกรายการแก้ไขหมายเหตุ",
  //     centered: true,
  //     onOk: () => {
  //       onSubmit(status);
  //     },
  //   });
  // };

  useEffect(() => {
    // setProducts(data);
    console.log("ORDER DETAILS", data);
  }, [data]);

  return (
    <Modal
      title="รายละเอียด"
      centered={true}
      // width={1000}
      open={open}
      //   onOk={handleSubmit}
      closeIcon={false}
      onCancel={handleClose}
      footer={[
        // <Button
        //   // danger
        //   type="primary"
        //   // disabled={mark === ""}
        //   key="edit"
        //   onClick={handleClickEdit}
        // >
        //   แก้ไขยอด
        // </Button>,
        data.order_status_id === 1 && (
          <Button
            danger
            type="primary"
            disabled={mark === ""}
            key="remove"
            onClick={handleCancelOrder}
          >
            ยกเลิกรายการ
          </Button>
        ),
        data.order_status_id === 2 &&
        (user.role === "admin" || user.role === "editor") ? (
          <Button
            danger
            type="primary"
            // disabled={mark === ""}
            key="remove"
            onClick={handleConfirmCancelOrder}
          >
            ยืนยันการยกเลิก
          </Button>
        ) : null,
        // <Button
        //   key="download"
        //   disabled={data?.order_status_id !== 1}
        //   onClick={handlePrint}
        // >
        //   พิมพ์ใบเสร็จ
        // </Button>,
        // <Button
        //   type="primary"
        //   key="submit"
        //   disabled={mark === ""}
        //   onClick={handleSubmit}
        // >
        //   บันทึก
        // </Button>,
        <Button key="close" onClick={handleClose}>
          ปิด
        </Button>,
      ]}
    >
      <>
        <Divider />
        <CustomerDetail data={data} />
        {/* 
        <List
          itemLayout="horizontal"
          dataSource={data.products}
          renderItem={(item, index) => <ProductItem key={index} data={item} />}
        /> */}

        {data.donate !== 0 && (
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              marginTop: "16px",
              marginBottom: "16px",
            }}
          >
            <Text strong>เงินบริจาค</Text>
            <Text strong> {currencyFormat(data.donate || 0)}</Text>
          </div>
        )}
        <hr />
        <Space direction="vertical">
          <Text>ช่องทางชำระ: {data.payment}</Text>
          <Text type="secondary">หมายเหตุ: {data.mark}</Text>
        </Space>

        {data.payment_by_id === 2 && (
          <div
            style={{
              marginTop: "24px",
              justifyContent: "center",
              display: "flex",
            }}
          >
            {/* <img src={data.payment_img} alt="payment" /> */}
            <Image width={100} src={data.payment_img} />
          </div>
        )}
      </>
      <div
        style={{
          marginTop: "24px",
        }}
      >
        {data.order_status_id === 1 ? (
          <Input
            placeholder="ใส่หมายเหตุก่อนยกเลิก"
            onChange={(e) => setMark(e.target.value)}
          />
        ) : (
          <Text strong type="danger">
            หมายเหตุ: {mark}
          </Text>
        )}
      </div>
    </Modal>
  );
}
