import React from "react";
import { Tag, Typography } from "antd";
import moment from "moment/moment";
import "moment/locale/th";
import { currencyFormatTH } from "../../../utils/numberFormat";
const { Text } = Typography;

export default function OrderItem({ data, onClick }) {
  const sum = data.products.reduce((accumulator, object) => {
    const total = object.price * object.amount;
    return accumulator + total;
  }, 0);
  //   console.log(data);

  const handleClickItem = () => {
    onClick(data);
  };

  const RenderDataList = ({ title, content }) => (
    <div
      style={{
        flexDirection: "row",
        display: "flex",
        justifyContent: "space-between",
      }}
    >
      <Text style={{ fontSize: 12 }} type="secondary">
        {title}
      </Text>
      <Text style={{ fontSize: 12 }} type="secondary">
        {content}
      </Text>
    </div>
  );

  return (
    <div onClick={handleClickItem}>
      <div
        style={{
          flexDirection: "column",
          display: "flex",
          justifyContent: "space-between",
        }}
      >
        <div
          style={{
            flexDirection: "row",
            display: "flex",
            justifyContent: "space-between",
          }}
        >
          <Text strong style={{ fontSize: 12 }}>
            เลขที่ {data.order_number}
          </Text>
          {data.order_status_id === 2 ? (
            <Tag color="processing">ยกเลิก (รออนุมัติ)</Tag>
          ) : data.order_status_id === 3 ? (
            <Tag color="error">ยกเลิกแล้ว</Tag>
          ) : data.order_status_id === 4 ? (
            <Tag color="yellow">แก้ไข/เปลี่ยน</Tag>
          ) : (
            <Tag color="success">ขายแล้ว</Tag>
          )}
        </div>

        <RenderDataList
          title={"ชื่อร้านค้า : " + data.storename}
          content={moment(data.datetime).format("LL")}
        />
        <RenderDataList
          title={"ยอดสั่งซื้อสินค้า"}
          content={currencyFormatTH(sum)}
        />
        <RenderDataList
          title={"ยอดบริจาค"}
          content={currencyFormatTH(data.donate)}
        />
      </div>
      <div
        style={{
          justifyContent: "space-between",
          display: "flex",
        }}
      >
        <Text strong style={{ fontSize: 12 }}>
          {data.payment}
        </Text>
        <Text strong style={{ fontSize: 12 }}>
          รวม {currencyFormatTH(data.total_price)}
        </Text>
      </div>
      {data.order_type && (
        <Text strong style={{ fontSize: 12 }}>
          ประเภท {data.order_type}
        </Text>
      )}

      <hr />
    </div>
  );
}
