import {
  Modal,
  Button,
  Typography,
  Divider,
  List,
  Image,
  Input,
  Space,
} from "antd";
import React, { useEffect, useState } from "react";
import ProductItem from "./ProductItem";
import CustomerDetail from "../order/CustomerDetail";
import { useSelector } from "react-redux";
import { currencyFormat, currencyFormatTH } from "../../../utils/numberFormat";
import moment from "moment";

const { Text } = Typography;

export default function OrderReferDetailModal({
  open,
  data,
  dataRefer,
  onclose,
  onPrint,
  onCancel,
}) {
  const user = useSelector((state) => state.token);
  const [mark, setMark] = useState("");
  const handleClose = () => {
    onclose(false);
  };

  const handlePrint = () => {
    onPrint(dataRefer);
  };

  const handleCancel = () => {
    // console.log("Cancel", data);
    onCancel({
      ...dataRefer,
      order_status_id: 2,
      mark: mark,
      cancel_at: moment().format("YYYY-MM-DD HH:mm:ss"),
    });
  };

  const compareSumPrice = (oldPrice, newPrice) => {
    const sumPrice = oldPrice - newPrice;
    if (sumPrice < 0) {
      return "เพิ่มเงิน " + currencyFormatTH(-sumPrice);
    } else {
      return "คืนเงิน " + currencyFormatTH(sumPrice);
    }
  };

  useEffect(() => {
    // setProducts(data);
    // console.log("ORDER DETAILS", data);
  }, [data]);

  return (
    <Modal
      title="รายละเอียด"
      centered={true}
      // width={1000}
      open={open}
      //   onOk={handleSubmit}
      closeIcon={false}
      onCancel={handleClose}
      footer={[
        <Button key="cancel" danger disabled={!mark} onClick={handleCancel}>
          ยกเลิกบิล
        </Button>,
        <Button
          key="receipt"
          //   disabled={data?.order_status_id !== 1}
          onClick={handlePrint}
        >
          พิมพ์ใบเสร็จ
        </Button>,
        <Button key="close" onClick={handleClose}>
          ปิด
        </Button>,
      ]}
    >
      <>
        <Divider />
        {/* <CustomerDetail data={data} /> */}
        <Text strong>อ้างอิงจากบิลเดิม เลขที่ {data.order_number}</Text>
        <List
          itemLayout="horizontal"
          dataSource={data.products}
          renderItem={(item, index) => <ProductItem key={index} data={item} />}
        />

        {data.donate !== 0 && data.event_id === 1 && (
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              marginTop: "16px",
              marginBottom: "16px",
            }}
          >
            <Text strong>เงินบริจาค</Text>
            <Text strong> {currencyFormatTH(data.donate || 0)}</Text>
          </div>
        )}
        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            marginTop: "16px",
            marginBottom: "16px",
          }}
        >
          <Text strong>ยอดรวม</Text>
          <Text strong> {currencyFormatTH(data.total_price)}</Text>
        </div>
        {/* <hr /> */}
        <Space direction="vertical">
          <Text>ช่องทางชำระ: {data.payment}</Text>
          {data.payment_by_id !== 3 && (
            <Text color="secondary">
              วันที่ชำระ: {moment(data.payment_date).format("lll")}
            </Text>
          )}
          {data.event_id === 1 && <Text>ประเภทบิล: {data.order_type}</Text>}
        </Space>

        {data.payment_by_id === 2 && (
          <div
            style={{
              marginTop: "24px",
              justifyContent: "center",
              display: "flex",
            }}
          >
            {/* <img src={data.payment_img} alt="payment" /> */}
            <Image width={100} src={data.payment_img} />
          </div>
        )}
        <div
          style={{
            marginTop: "24px",
          }}
        >
          <Text strong type="danger">
            หมายเหตุ: {data.mark}
          </Text>
        </div>
      </>
      <>
        <Divider />
        {/* <CustomerDetail data={data} /> */}
        <Text strong>รายการใหม่ เลขที่ {dataRefer.order_number}</Text>
        <List
          itemLayout="horizontal"
          dataSource={dataRefer.products}
          renderItem={(item, index) => <ProductItem key={index} data={item} />}
        />

        {dataRefer.donate !== 0 && dataRefer.event_id === 1 && (
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              marginTop: "16px",
              marginBottom: "16px",
            }}
          >
            <Text strong>เงินบริจาค</Text>
            <Text strong> {currencyFormat(dataRefer.donate || 0)}</Text>
          </div>
        )}
        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            marginTop: "16px",
            marginBottom: "16px",
          }}
        >
          <Text strong>ยอดรวม</Text>
          <Text strong> {currencyFormatTH(dataRefer.total_price)}</Text>
        </div>
        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            marginTop: "16px",
            marginBottom: "16px",
          }}
        >
          <Text strong>ส่วนต่าง</Text>
          <Text strong>
            {compareSumPrice(data.total_price, dataRefer.total_price)}
          </Text>
        </div>
        {/* <hr /> */}
        <Space direction="vertical">
          <Text>ช่องทางชำระ: {dataRefer.payment}</Text>
          {dataRefer.payment_by_id !== 3 && (
            <Text color="secondary">
              วันที่ชำระ: {moment(dataRefer.payment_date).format("lll")}
            </Text>
          )}
          {dataRefer.event_id === 1 && (
            <Text>ประเภทบิล: {dataRefer.order_type}</Text>
          )}
          {/* <Text type="secondary">หมายเหตุ: {dataRefer.mark}</Text> */}
        </Space>

        {dataRefer.payment_by_id === 2 && (
          <div
            style={{
              marginTop: "24px",
              justifyContent: "center",
              display: "flex",
            }}
          >
            {/* <img src={data.payment_img} alt="payment" /> */}
            <Image width={100} src={dataRefer.payment_img} />
          </div>
        )}
        <div
          style={{
            marginTop: "24px",
          }}
        >
          <Text strong type="danger">
            หมายเหตุ: {dataRefer.mark}
          </Text>
        </div>
        <hr />
        <Input
          style={{
            marginTop: "24px",
          }}
          placeholder="ใส่หมายเหตุ กรณียกเลิก"
          onChange={(e) => setMark(e.target.value)}
        />
      </>
    </Modal>
  );
}
