import React from "react";
import { List } from "antd";
import AomsinLotItem from "./AomsinLotItem";

export default function AomsinLotList({ data, onPrint, onClickItem }) {
  return (
    <List
      pagination={{
        pageSize: 10,
      }}
      itemLayout="horizontal"
      dataSource={data}
      renderItem={(item) => (
        <AomsinLotItem
          data={item}
          onPrint={onPrint}
          onClickItem={onClickItem}
        />
      )}
    />
  );
}
