import React from "react";
import { Space, Tag, Typography } from "antd";
import moment from "moment/moment";
import "moment/locale/th";
import { currencyFormatTH } from "../../../utils/numberFormat";

const { Text } = Typography;
export default function OrderCancelItem({ data, onClick }) {
  const sum = data.products.reduce((accumulator, object) => {
    const total = object.price * object.amount;
    return accumulator + total;
  }, 0);
  //   console.log(data);

  const handleClick = () => {
    onClick(data);
  };

  const RenderDataList = ({ title, content }) => (
    <div
      style={{
        flexDirection: "row",
        display: "flex",
        justifyContent: "space-between",
      }}
    >
      <Text style={{ fontSize: 12 }} type="secondary">
        {title}
      </Text>
      <Text style={{ fontSize: 12 }} type="secondary">
        {content}
      </Text>
    </div>
  );

  return (
    <div onClick={handleClick}>
      <div
        style={{
          flexDirection: "column",
          display: "flex",
          justifyContent: "space-between",
        }}
      >
        <div
          style={{
            flexDirection: "row",
            display: "flex",
            justifyContent: "space-between",
          }}
        >
          <Text strong style={{ fontSize: 12 }}>
            เลขที่ {data.order_number}
          </Text>
          <Text style={{ fontSize: 12 }} type="secondary">
            {moment(data.datetime).format("ll")}
          </Text>
        </div>

        <RenderDataList
          title={"ชื่อร้านค้า : " + data.storename}
          content={""}
        />
        <RenderDataList
          title={"ยอดสั่งซื้อสินค้า"}
          content={currencyFormatTH(sum)}
        />
        <RenderDataList
          title={"ยอดบริจาค"}
          content={currencyFormatTH(data.donate)}
        />
      </div>
      <div
        style={{
          justifyContent: "space-between",
          display: "flex",
        }}
      >
        {data.order_status_id === 2 ? (
          <Tag bordered={false} color="processing">
            รออนุมัติ
          </Tag>
        ) : (
          <Space>
            <Tag bordered={false} color="error">
              ยกเลิกแล้ว
            </Tag>
            <Text type="secondary" style={{ fontSize: 12 }}>
              เมื่อ {moment(data.cancel_at).format("ll")}
            </Text>
          </Space>
        )}

        <Text strong style={{ fontSize: 12 }}>
          รวม {currencyFormatTH(data.total_price)}
        </Text>
      </div>

      <hr />
    </div>
  );
}
