import moment from "moment";
import React, { useEffect, useState } from "react";
import ReactExport from "react-export-excel";
import { Link } from "react-router-dom";

const ExcelFile = ReactExport.ExcelFile;
const ExcelSheet = ReactExport.ExcelFile.ExcelSheet;
const ExcelColumn = ReactExport.ExcelFile.ExcelColumn;

export default function CustomerReport({ data }) {
  const [dataSource, setDataSource] = useState([]);

  useEffect(() => {
    mapData();
  }, []);

  const mapData = () => {
    const arr = data.filter((item) => item.storename !== "เงินสด");
    setDataSource(arr);
  };

  //   console.log(data);
  return (
    <div style={{ width: "100%", justifyContent: "end", display: "flex" }}>
      <ExcelFile element={<Link>Download</Link>}>
        <ExcelSheet data={dataSource} name="รายชื่อร้านค้า">
          <ExcelColumn label="ชื่อร้าน" value="storename" />
          <ExcelColumn label="ชื่อ-สกุล ลูกค้า" value="fullname" />
          <ExcelColumn label="โทรศัพท์" value="phone" />
          <ExcelColumn label="ถนน" value="road" />
          <ExcelColumn label="ที่อยู่" value="address" />
        </ExcelSheet>
      </ExcelFile>
    </div>
  );
}
