import React from "react";
import { List } from "antd";
import LotteryItem from "./LotteryItem";

export default function LotteryList({ data, onClickItem }) {
  return (
    <List
      pagination={{
        pageSize: 10,
      }}
      itemLayout="horizontal"
      dataSource={data}
      renderItem={(item) => (
        <LotteryItem
          data={item}
          // onPrint={onPrint}
          onClickItem={onClickItem}
        />
      )}
    />
  );
}
