import React, { useEffect, useState } from "react";
import {
  Button,
  Divider,
  Image,
  Modal,
  Select,
  Space,
  Tabs,
  Input,
  Typography,
  Tag,
} from "antd";
import OrderTicketList from "./OrderTicketList";
import baseAPI from "../../../api/baseAPI";
import { useDispatch, useSelector } from "react-redux";
import SelectSeatNumberModal from "./SelectSeatNumberModal";
import { PlusOutlined } from "@ant-design/icons";
import AddEventModal from "./AddEventModal";
import OrderList from "./report/OrderList";
import Loading from "../../../utils/Loading";

const { Text } = Typography;

export default function Main() {
  const user = useSelector((state) => state.token);
  // const dispatch = useDispatch();
  const [ticketDetail, setTicketDetail] = useState([]);
  const [selectTicketDetail, setSelelctTicketDetail] = useState({
    id: 0,
    year: 0,
  });
  const [orders, setOrders] = useState([]);
  const [orderHolders, setOrderHolders] = useState([]);
  const [openSelectSeatModal, setOpenSelectSeatModal] = useState(false);
  const [openEventModal, setOpenEventModal] = useState(false);
  const [orderSelected, setOrderSelected] = useState({});

  const [bookingLogDeluxe, setBookingLogDeluxe] = useState([]);
  const [bookingLogVip, setBookingLogVip] = useState([]);

  const [dashboardStandard, setDashboardStandard] = useState([]);
  const [dashboardVip, setDashboardVip] = useState([]);

  // const [dashboardStandardFinished, setDashboardStandardFinished] = useState(
  //   []
  // );

  const [loading, setLoading] = useState(false);

  useEffect(() => {
    fetchTicketYear();
    // fetchAllTickets();
    // fetchAllBookingLogDeluxe();
  }, []);

  useEffect(() => {
    console.log("selectTicketDetail", selectTicketDetail);
    if (selectTicketDetail.id !== 0) {
      fetchAllBookingLogDeluxe(selectTicketDetail);
      // fetchAllBookingLogVip(selectTicketDetail);
      fetchAllTickets(selectTicketDetail);
    }
  }, [selectTicketDetail]);

  useEffect(() => {
    let dashboard = [];
    // console.log("Ticket Detail", selectTicketDetail);
    for (let i = 0; i < selectTicketDetail.table_amount; i++) {
      const value = i + 1;
      //   console.log("Booking", bookingLog);
      let map = bookingLogDeluxe.filter(
        (log) =>
          log.ticket_sale_id === selectTicketDetail.id &&
          log.seat_number === value
      );
      // console.log("MAP", map);
      if (map.length > 0) {
        dashboard.push({ ...map[0], ticket_status_id: 2 });
      } else {
        dashboard.push({
          seat_number: value,
          ticket_status_id: 1,
          ticket_sale_id: selectTicketDetail.id,
        });
      }
    }
    setDashboardStandard(dashboard);
    // setLoading(false);
  }, [bookingLogDeluxe, selectTicketDetail]);

  useEffect(() => {
    let dashboard = [];
    for (let i = 0; i < selectTicketDetail.table_vip_amount; i++) {
      const value = i + 1;
      //   console.log("Booking", bookingLog);
      let map = bookingLogVip.filter(
        (log) =>
          log.ticket_sale_id === selectTicketDetail.id &&
          log.seat_number === value
      );
      if (map.length > 0) {
        // console.log("MAP", map);
        setDashboardVip((pre) => [...pre, { ...map[0], ticket_status_id: 2 }]);
        dashboard.push({ ...map[0], ticket_status_id: 2 });
      } else {
        dashboard.push({
          seat_number: value,
          ticket_status_id: 1,
          ticket_sale_id: selectTicketDetail.id,
        });
        setDashboardVip((pre) => [
          ...pre,
          {
            seat_number: value,
            ticket_status_id: 1,
            ticket_sale_id: selectTicketDetail.id,
          },
        ]);
      }
    }
    setDashboardVip(dashboard);
  }, [bookingLogVip, selectTicketDetail]);

  // useEffect(() => {
  //   if (dashboardStandard.length > 0) {
  //     setLoading(false);
  //   }
  // }, [dashboardStandard]);

  const fetchTicketYear = async () => {
    await baseAPI
      .get("/city_pillar_shrine/tickets", {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        console.log("fetch Ticket Year", response.data);
        const data = response.data;
        const lastYear = data[data.length - 1];
        setTicketDetail(data);
        setSelelctTicketDetail(lastYear);
      })
      .catch((err) => {
        Modal.error({
          title: "ไม่สามารถโหลดข้อมูลได้",
          content: err.message,
          centered: true,
        });
      });
  };

  const fetchAllTickets = async (data) => {
    console.log("DATA SELECTED", data);
    await baseAPI
      .get("/city_pillar_shrine/tickets/orders", {
        headers: {
          "x-access-token": user.token,
        },
        params: { year: data.year },
      })
      .then((response) => {
        console.log("ALL TICKET", response.data);
        setOrders(response.data);
        setOrderHolders(response.data);
        console.log(response.data);
      })
      .catch((err) => {
        Modal.error({
          title: "ไม่สามารถโหลดข้อมูลได้",
          content: err.message,
          centered: true,
        });
      });
  };

  const fetchAllBookingLogDeluxe = async (data) => {
    await baseAPI
      .get("/city_pillar_shrine/tickets/booking/" + data.id, {
        headers: {
          "x-access-token": user.token,
        },
        params: { type: 1 },
      })
      .then((response) => {
        console.log("STANDARD", response.data);
        setBookingLogDeluxe(response.data);
        // mapDashboardStandard(response.data);

        // setLoading(false);
      })
      .catch((err) => {
        Modal.error({
          title: "ไม่สามารถโหลดข้อมูลได้",
          content: err.message,
          centered: true,
        });
      });
  };

  // const fetchAllBookingLogVip = async (data) => {
  //   await baseAPI
  //     .get("/city_pillar_shrine/tickets/booking/" + data.id, {
  //       headers: {
  //         "x-access-token": user.token,
  //       },
  //       params: { type: 2 },
  //     })
  //     .then((response) => {
  //       console.log("VIP", response.data);
  //       setBookingLogVip(response.data);
  //       // mapDashboardVip(response.data);
  //     })
  //     .catch((err) => {
  //       Modal.error({
  //         title: "ไม่สามารถโหลดข้อมูลได้",
  //         content: err.message,
  //         centered: true,
  //       });
  //     });
  // };

  const handleClickAddItem = () => {
    setOpenEventModal(true);
    // console.log("ADD");
  };

  const onChange = (event, value) => {
    // console.log("Selected item", event);
    setSelelctTicketDetail(value.item);
  };

  const handleClick = (data) => {
    // console.log("onClick", data);
  };

  const handleSelected = async (data) => {
    setOpenSelectSeatModal(true);

    setOrderSelected(data);
  };

  const handleSubmitSeat = async (data) => {
    // console.log("Add Seat", data);
    setOpenSelectSeatModal(false);
    await baseAPI
      .post("/city_pillar_shrine/tickets/booking", data, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        // setOrders(response.data);
        Modal.success({
          content: "บันทึกสำเร็จ",
          centered: true,
        });
        const newState = orderHolders.map((obj) => {
          if (obj.id === data.order_id) {
            const seatType = data.ticket_type_id;
            if (seatType === 1) {
              return { ...obj, ...data };
            }
            return { ...obj, ...data, seat_number_vip: data.seat_number };
          }
          return obj;
        });
        // console.log("NEW ARRAY", newState);

        fetchAllBookingLogDeluxe(selectTicketDetail);

        setOrders(newState);
        setOrderHolders(newState);
      })
      .catch((err) => {
        Modal.error({
          title: "ไม่สามารถโหลดข้อมูลได้",
          content: err.message,
          centered: true,
        });
      });
  };

  const handleSubmitAddEvent = async (data) => {
    // console.log("Add Event", data);
    setOpenEventModal(false);
    setSelelctTicketDetail(data);
    await baseAPI
      .post("/city_pillar_shrine/tickets", data, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        // setOrders(response.data);
        // console.log(response.data);
      })
      .catch((err) => {
        Modal.error({
          title: "ไม่สามารถโหลดข้อมูลได้",
          content: err.message,
          centered: true,
        });
      });
  };

  const handleCancelSeat = async (data) => {
    setOpenSelectSeatModal(false);
    console.log("REMOVE", data);
    // setLoading(true);
    await baseAPI
      .delete(`/city_pillar_shrine/tickets/booking`, {
        headers: {
          "x-access-token": user.token,
        },
        data: {
          data,
        },
      })
      .then((response) => {
        const newState = orderHolders.map((obj) => {
          if (obj.id === data.order_id) {
            return { ...obj, ...data, ticket_type_id: null };
          }
          return { ...obj };
        });
        setOrders(newState);
        setOrderHolders(newState);
        if (data.ticket_type_id === 1) {
          const result = bookingLogDeluxe.filter(
            (obj) => obj.order_id !== data.order_id
          );
          setBookingLogDeluxe(result);
        } else {
          const result = bookingLogVip.filter(
            (obj) => obj.order_id !== data.order_id
          );
          setBookingLogVip(result);
        }

        Modal.success({ content: "ยกเลิกการจองสำเร็จ", centered: true });
        setLoading(false);
      })
      .catch((error) => {
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });

    // fetchAllBookingLogDeluxe();
  };

  const items = [
    {
      key: "1",
      label: "ยังไม่จองโต๊ะ",
      children: (
        <OrderTicketList
          data={orders.filter((item) => item.ticket_status_id === 1)}
          // onClick={handleClick}
          onClickEdit={handleSelected}
          onClickItem={handleClick}
        />
      ),
    },
    {
      key: "2",
      label: "จองโต๊ะแล้ว",
      children: (
        <OrderTicketList
          data={orders.filter((item) => item.ticket_status_id === 2)}
          onClickEdit={handleSelected}
          onClickItem={handleClick}
        />
      ),
    },
  ];

  const onSearchCustomer = (event) => {
    if (event.target.value) searchUserByName(event.target.value);
    else setOrders(orderHolders);
  };

  const searchUserByName = (term) => {
    if (isNumeric(term)) {
      // console.log(term);
      var dataNumber = orderHolders.filter(
        (item) =>
          item.seat_number === parseInt(term) ||
          item.seat_number_vip === parseInt(term)
      );

      setOrders(dataNumber);
    } else {
      var dataString = orderHolders.filter((item) =>
        item.storename.includes(term)
      );
      setOrders(dataString);
    }
  };

  function isNumeric(value) {
    return /^-?\d+$/.test(value);
  }

  const filterOption = (input, option) =>
    (option?.label ?? "").toLowerCase().includes(input.toLowerCase());

  const renderItemDashboard = (type, item) => {
    // if (type === 1) {
    return (
      <Tag
        key={"Type:" + type + "-" + item.seat_number}
        color={item.ticket_status_id === 1 ? "#87d068" : "#f50"}
        style={{
          width: 30,
          textAlign: "center",
          fontSize: "9px",
        }}
      >
        {item.seat_number}
      </Tag>
    );
    // }
    //  else {
    //   return (
    //     <Tag
    //       key={"Type:" + type + "-" + item.seat_number}
    //       color={item.ticket_status_id === 1 ? "#FBE065" : "#f50"}
    //       style={{
    //         width: 30,
    //         textAlign: "center",
    //         color: "black",
    //         fontSize: "9px",
    //       }}
    //     >
    //       {item.seat_number}
    //     </Tag>
    //   );
    // }
  };

  if (loading) {
    return <Loading />;
  } else
    return (
      <>
        <div
          style={{
            justifyContent: "end",
            display: "flex",
          }}
        >
          <Button onClick={handleClickAddItem} icon={<PlusOutlined />}>
            เพิ่มปีที่จัดงาน
          </Button>
        </div>

        <Divider />
        <div
          style={{
            flexDirection: "column",
            justifyContent: "center",
            display: "flex",
          }}
        >
          <div
            style={{
              marginBottom: "24px",
              width: "100%",
              justifyContent: "center",
              display: "flex",
            }}
          >
            <Space>
              <Text strong>เลือกปีที่จัดงาน</Text>
              <Select
                showSearch
                style={{ width: "200px" }}
                placeholder="เลือกปี"
                optionFilterProp="children"
                onChange={onChange}
                // onSearch={onSearch}
                filterOption={filterOption}
                options={ticketDetail.map((item) => ({
                  value: item.id,
                  label: item.year,
                  item,
                }))}
              />
            </Space>
          </div>
          <Space align="center" direction="vertical">
            <Text strong style={{ fontSize: 18 }}>
              แผนผังโต๊ะงานง่วนเซียว ประจำปี {selectTicketDetail.year}
            </Text>
            {/* <Space>ฝ */}
            {/* <Text style={{ fontSize: 16 }}>
                (VIP) {selectTicketDetail.table_vip_amount} ||
              </Text> */}
            <Text style={{ fontSize: 16 }}>
              จำนวน {selectTicketDetail.table_amount} ที่นั่ง
            </Text>
            {/* </Space> */}

            <Image src={selectTicketDetail.image} width={300} alt="" />
          </Space>
          <Divider />
          <div>
            {/* <h2>แผนผังโต๊ะ</h2> */}
            {dashboardStandard.map((item) => renderItemDashboard(1, item))}
            {/* <h2>VIP</h2>
            {dashboardVip.map((item) => renderItemDashboard(2, item))} */}
          </div>
          <Divider />
          <div
            style={{
              width: "100%",
              marginBottom: 16,
              // justifyContent: "flex-end",
              // display: "flex",
            }}
          >
            <Input
              placeholder="ค้นหาจากชื่อร้านค้า หรือเบอร์โต๊ะ"
              allowClear
              size="small"
              // onSearch={onSearch}
              // style={{ width: 250 }}
              onChange={onSearchCustomer}
            />
          </div>
          <OrderList data={orders.length > 0 && orders} />
          <Tabs defaultActiveKey="1" items={items} />

          <SelectSeatNumberModal
            open={openSelectSeatModal}
            onClose={setOpenSelectSeatModal}
            order={orderSelected}
            detail={selectTicketDetail}
            bookingLogDeluxe={bookingLogDeluxe}
            bookingLogVip={bookingLogVip}
            onSubmit={handleSubmitSeat}
            onCancel={handleCancelSeat}
          />

          <AddEventModal
            open={openEventModal}
            onClose={setOpenEventModal}
            onSubmit={handleSubmitAddEvent}
          />
        </div>
      </>
    );
}
