import React, { useState } from "react";
import { Button, Modal, Form, Input, Select, Tabs } from "antd";
import AddUserGroup from "./user_group/AddUserGroup";
import EditUserGroup from "./user_group/EditUserGroup";

export default function AddOrEditUserGroupModal({
  open,
  data,
  onClose,
  onSubmit,
}) {
  // const [form] = Form.useForm();
  const [group, setGroup] = useState({});
  // const [group, setGroup] = useState("");

  const handleClose = () => {
    onClose(false);
  };

  const handleSubmit = () => {
    // console.log("SUBMIT", group);
    onSubmit(group);
  };
  const handleAddUserGroup = (data) => {
    // console.log("ADD", data);
    setGroup(data);
  };

  const handleEditUserGroup = (data) => {
    // console.log("Edit", data);
    setGroup(data);
  };

  const items = [
    {
      key: "1",
      label: "เพิ่มกลุ่ม",
      children: <AddUserGroup onSubmit={handleAddUserGroup} />,
    },
    {
      key: "2",
      label: "แก้ไขกลุ่ม",
      children: <EditUserGroup data={data} onSubmit={handleEditUserGroup} />,
    },
  ];

  return (
    <Modal
      title="เพิ่มกลุ่มสมาชิก"
      centered={true}
      // width={1000}
      open={open}
      //   onOk={handleSubmit}
      closeIcon={false}
      onCancel={handleClose}
      footer={[
        <Button key="close" onClick={handleClose}>
          ยกเลิก
        </Button>,
        <Button
          key="submit"
          // htmlType="submit"
          type="primary"
          onClick={handleSubmit}
        >
          บันทึก
        </Button>,
      ]}
    >
      <Tabs defaultActiveKey="1" items={items} />
    </Modal>
  );
}
