import moment from "moment";
import React, { useEffect, useState } from "react";
import ReactExport from "react-export-excel";
import { Link } from "react-router-dom";

const ExcelFile = ReactExport.ExcelFile;
const ExcelSheet = ReactExport.ExcelFile.ExcelSheet;
const ExcelColumn = ReactExport.ExcelFile.ExcelColumn;

export default function ProductStock({ data }) {
  const [dataSource, setDataSource] = useState([]);

  console.log("Product Report", data);

  useEffect(() => {
    mapData();
  }, []);

  const mapData = () => {
    let arr = [];
    data.map((item) => {
      if (item.stock_timestamp[0].stock_datetime) {
        arr.push(...item.stock_timestamp);
      }
    });
    console.log(arr);
    setDataSource(arr);
  };

  return (
    <div style={{ width: "100%", justifyContent: "end", display: "flex" }}>
      <ExcelFile element={<Link>Download</Link>}>
        <ExcelSheet
          data={data.filter((item) => item.event_id === 1)}
          name="ขายโคม/ตรุษจีน/ง่วนเซียว"
        >
          <ExcelColumn label="สินค้า" value="name" />
          <ExcelColumn label="ทั้งหมด" value="total_amount" />
          <ExcelColumn
            label="ยอดขาย"
            value={(col) => parseInt(col.total_amount) - parseInt(col.amount)}
          />
          <ExcelColumn label="คงเหลือ" value="amount" />
        </ExcelSheet>
        <ExcelSheet data={dataSource} name="วันที่เพิ่มสต็อก">
          <ExcelColumn label="สินค้า" value="name" />
          <ExcelColumn
            label="วัน/เวลาที่เพิ่มสต็อก"
            value={(col) =>
              moment(col.stock_datetime).format("DD/MM/YYYY HH:mm:ss")
            }
          />
          <ExcelColumn label="จำนวนที่เพิ่ม" value="stock_amount" />
        </ExcelSheet>

        <ExcelSheet
          data={data.filter((item) => item.event_id === 2)}
          name="งานสมโภชประจำปี"
        >
          <ExcelColumn label="สินค้า" value="name" />
          <ExcelColumn label="ทั้งหมด" value="total_amount" />
          <ExcelColumn
            label="ยอดขาย"
            value={(col) => parseInt(col.total_amount) - parseInt(col.amount)}
          />
          <ExcelColumn label="คงเหลือ" value="amount" />
        </ExcelSheet>
        <ExcelSheet data={dataSource} name="วันที่เพิ่มสต็อก">
          <ExcelColumn label="สินค้า" value="name" />
          <ExcelColumn
            label="วัน/เวลาที่เพิ่มสต็อก"
            value={(col) =>
              moment(col.stock_datetime).format("DD/MM/YYYY HH:mm:ss")
            }
          />
          <ExcelColumn label="จำนวนที่เพิ่ม" value="stock_amount" />
        </ExcelSheet>
      </ExcelFile>
    </div>
  );
}
