import React, { useEffect, useState } from "react";
import YearPicker from "./YearPicker";
import {
  Divider,
  Form,
  Table,
  Typography,
  Select,
  Modal,
  Button,
  Space,
} from "antd";
import baseAPI from "../../../api/baseAPI";
import { useSelector } from "react-redux";
import Loading from "../../../utils/Loading";
import moment from "moment";
import AssociationTable from "./AssociationTable";

const { Text } = Typography;

export default function AddAssociationMembers({ onSubmit }) {
  const user = useSelector((state) => state.token);
  const [dataSource, setDataSource] = useState([]);
  const [customers, setCustomers] = useState([]);
  const [memberSelected, setMemberSelected] = useState({});
  const [year, setYear] = useState(moment(new Date()).format("YYYY"));
  // const [customersHolder, setCustomersHolder] = useState([]);
  const [members, setMembers] = useState([]);
  //   const [membersHolder, setMembersHolder] = useState([]);
  const [loading, setLoading] = useState(false);
  const [customerSelected, setCustomerSelected] = useState(null);

  const [form] = Form.useForm();

  useEffect(() => {
    fetchAllCustomers();
  }, []);

  const fetchAllCustomers = async () => {
    setLoading(true);
    await baseAPI
      .get(`/city_pillar_shrine/customers`, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((res) => {
        // console.log(res.data);
        setCustomers(res.data);
        // setCustomersHolder(res.data);
        setLoading(false);
      })
      .catch((err) => {
        // dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
  };

  const fetchAllCustomerMember = async (id) => {
    await baseAPI
      .get(`/city_pillar_shrine/customers/members/${id}`, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((res) => {
        // console.log(res.data);
        setMembers(res.data);
        // setMembersHolder(res.data);
      })
      .catch((err) => {
        // dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
      });
  };

  const onFinish = (values) => {
    let result = "";
    if (dataSource.length < 9) {
      result = `0${dataSource.length + 1}`;
    } else result = `${dataSource.length + 1}`;
    // const checkDataLenth =
    const dataCode = `KM${moment(year)
      .add(543, "years")
      .format("YY")}${result}`;

    const newValues = {
      code: dataCode,
      storename: customerSelected.storename,
      fullname: memberSelected.fullname,
      phone: memberSelected.phone,
      ...values,
      year,
    };
    setDataSource((pre) => [...pre, { ...newValues }]);
  };

  // useEffect(() => {
  //   console.log("Success:", dataSource);
  // }, [dataSource]);

  const onFinishFailed = (errorInfo) => {
    console.log("Failed:", errorInfo);
  };

  const handleChangeYear = (value) => {
    setYear(value);
    setDataSource([]);
    console.log("Year", value);
  };

  const handleChangeCustomer = (value, e) => {
    console.log("Customer:" + value, e);
    setCustomerSelected(e.item);
    fetchAllCustomerMember(value);
    form.setFieldValue("customer_member_id", null);
  };

  const handleChangeMembers = (value, e) => {
    setMemberSelected(e.item);
    console.log("Member:" + value, e.item);
  };

  const handleSubmitTable = () => {
    // console.log("Submit");
    Modal.confirm({
      title: "บันทึกรายการ",
      content: "ยืนยันรายชื่อสมาชิกทั้งหมด หรือไม่?",
      centered: true,
      onOk: () => {
        onSubmit(dataSource);
      },
    });
  };

  const filterOption = (input, option) =>
    (option?.label ?? "").toLowerCase().includes(input.toLowerCase());

  if (loading) return <Loading />;

  return (
    <div>
      <YearPicker onChange={handleChangeYear} />
      <Divider />
      <div style={{ marginBottom: 16 }}>
        <Text strong>เพิ่มรายชื่อสมาชิกสมาคมจัดงานสมโภช</Text>
      </div>

      <Form
        form={form}
        name="basic"
        labelCol={{
          span: 8,
        }}
        wrapperCol={{
          span: 16,
        }}
        style={{
          maxWidth: 600,
        }}
        // initialValues={{
        //   remember: true,
        // }}
        onFinish={onFinish}
        onFinishFailed={onFinishFailed}
        autoComplete="off"
      >
        <Form.Item
          label="ค้นหาร้านค้า"
          name="customer_id"
          rules={[
            {
              required: true,
              message: "ต้องไม่เว้นว่าง",
            },
          ]}
        >
          <Select
            showSearch
            placeholder="ค้นหาจากชื่อร้าน"
            optionFilterProp="children"
            // style={{ marginTop: "16px", width: "100%" }}
            onChange={handleChangeCustomer}
            // onSearch={onSearch}
            filterOption={filterOption}
            options={customers.map((item) => ({
              value: item.id,
              label: item.storename,
              item,
            }))}
          />
        </Form.Item>

        {customerSelected && (
          <Form.Item
            label="สมาชิกร้าน"
            name="customer_member_id"
            rules={[
              {
                required: true,
                message: "ต้องไม่เว้นว่าง",
              },
            ]}
          >
            <Select
              //   showSearch
              placeholder="เลือกสมาชิก"
              optionFilterProp="children"
              // style={{ marginTop: "16px", width: "100%" }}
              onChange={handleChangeMembers}
              // onSearch={onSearch}
              filterOption={filterOption}
              options={members.map((item) => ({
                value: item.id,
                label: item.fullname,
                item,
              }))}
            />
          </Form.Item>
        )}

        <Form.Item
          wrapperCol={{
            offset: 8,
            span: 16,
          }}
        >
          <Button type="primary" htmlType="submit">
            เพิ่มรายชื่อ
          </Button>
        </Form.Item>
      </Form>

      <AssociationTable data={dataSource} />

      {dataSource.length > 0 && (
        <div style={{ justifyContent: "center", display: "flex" }}>
          <Button type="primary" onClick={handleSubmitTable}>
            บันทึกตาราง
          </Button>
        </div>
      )}
    </div>
  );
}
