import React, { useEffect, useState } from "react";
import { DatePicker, Space, Typography } from "antd";
import dayjs from "dayjs";
import moment from "moment";

const { Text } = Typography;
export default function YearPicker({ onChange }) {
  const [year, setYear] = useState(moment().add(543, "years").format("YYYY"));
  const [dateSelected, setDateSelected] = useState(
    moment().format("YYYY-MM-DD")
  );

  useEffect(() => {
    const date = new Date();
    let month = date.getMonth() + 1;
    // let year = date.getFullYear();
    if (month >= 10) {
      // year += 1;
      setDateSelected(moment().add(1, "years").format("YYYY-MM-DD"));
    } else {
      setDateSelected(moment().format("YYYY-MM-DD"));
    }
  }, []);

  const handleDateChange = (date, dateString) => {
    console.log("handleDateChange", dateString);
    const yearSelected = moment(dateString).add(543, "years").format("YYYY");
    setYear(yearSelected);
    onChange(dateString);
  };

  return (
    <div>
      <Space>
        <Text strong>ประจำปี</Text>
        <DatePicker
          picker="year"
          onChange={handleDateChange}
          defaultValue={dayjs(dateSelected, "YYYY")}
          // format="YYYY"
          style={{ width: "100%" }}
        />
        {year && <Text strong>พ.ศ. {year}</Text>}
      </Space>
    </div>
  );
}
