import React, { useEffect, useState } from "react";
import {
  Button,
  DatePicker,
  Divider,
  Modal,
  Radio,
  Typography,
  Space,
  InputNumber,
} from "antd";
import {
  ShoppingCartOutlined,
  DollarOutlined,
  PlusOutlined,
  ShopOutlined,
} from "@ant-design/icons";
import { CheckOutlined } from "@ant-design/icons";
import OrderDetail from "./OrderDetail";
import AddOrderModal from "./AddOrderModal";
import AddDonateModal from "./AddDonateModal";
import AddCustomerModal from "../customer/AddCustomerModal";
import baseAPI from "../../../api/baseAPI";
import CustomerListModal from "./CustomerListModal";
import { useNavigate } from "react-router-dom";
import { useDispatch, useSelector } from "react-redux";
import { addOrder, addToken } from "../../../redux/reduxSlice";
import Loading from "../../../utils/Loading";
import dayjs from "dayjs";
import moment from "moment";
import CustomerDetail from "./CustomerDetail";
import OrderDetailList from "./OrderDetailList";
import { currencyFormat, currencyFormatTH } from "../../../utils/numberFormat";
import ConfirmOrderModal from "./ConfirmOrderModal";

const { Text } = Typography;

export default function Main() {
  const user = useSelector((state) => state.token);

  const dispatch = useDispatch();
  const navigate = useNavigate();
  const [openProductsModal, setOpenProductsModal] = useState(false);
  const [openDonateModal, setOpenDonateModal] = useState(false);
  const [openAddCustomerModal, setOpenAddCustomerModal] = useState(false);
  const [disableAddProductButton, setDisableAddProductButton] = useState(true);
  const [openCustomerListModal, setOpenCustomerListModal] = useState(false);
  const [openModalConfirm, setOpenModalConfirm] = useState(false);

  const [productList, setProductList] = useState([]);
  const [productListEventSelected, setProductListEventSelected] = useState([]);
  const [orderType, setOrderType] = useState([]);
  const [customerList, setCustomerList] = useState([]);
  const [orderProducts, setOrderProducts] = useState([]);
  const [orderCustomer, setOrderCustomer] = useState({});
  // const [productsType, setProductsType] = useState([]);
  const [orderDonate, setOrderDonate] = useState(0);
  const [eventType, setEventType] = useState(1);
  const [paymentChannel, setPaymentChannel] = useState(1);
  const [orderTypeSelect, setOrderTypeSelect] = useState();
  const [amount, setAmount] = useState(0);
  const [orderCreate, setOrderCreate] = useState({});

  const [dateSelect, setDateSelect] = useState("");
  const [year, setYear] = useState("");

  const [loading, setLoading] = useState(false);

  const sum = orderProducts.reduce((accumulator, object) => {
    const total = object.price * object.amount;
    return accumulator + total;
  }, 0);
  // const user =

  useEffect(() => {
    setOrderTypeSelect(orderType[0]?.id || null);
  }, [orderType]);

  useEffect(() => {
    const date = new Date();
    let month = date.getMonth() + 1;
    let year = date.getFullYear();
    if (month > 11) {
      setYear(year + 1);
      setDateSelect(moment().add(1, "years").format("YYYY-MM-DD"));
    } else {
      setYear(year);
      setDateSelect(moment().format("YYYY-MM-DD"));
    }

    getProducts(year);
    getOrderType();
    fetchAllCustomers();
    // fetchProductType();
  }, []);

  const getProducts = async (year) => {
    setLoading(true);
    await baseAPI
      .get(`/city_pillar_shrine/products/active`, {
        params: { year },
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((res) => {
        setProductList(res.data);
        setLoading(false);
      })
      .catch((error) => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
  };

  const getOrderType = async () => {
    setLoading(true);
    await baseAPI
      .get(`/city_pillar_shrine/order-type`, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((res) => {
        setOrderType(res.data);
        setLoading(false);
      })
      .catch((error) => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
  };

  const fetchAllCustomers = async () => {
    setLoading(true);
    await baseAPI
      .get("/city_pillar_shrine/customers", {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        setCustomerList(response.data);
        setLoading(false);
      })
      .catch((err) => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
  };

  // const fetchProductType = async () => {
  //   setLoading(true);
  //   await baseAPI
  //     .get(`/city_pillar_shrine/products/type`, {
  //       headers: {
  //         "x-access-token": user.token,
  //       },
  //     })
  //     .then((result) => {
  //       setProductsType(result.data);
  //       setLoading(false);
  //     })
  //     .catch((error) => {
  //       dispatch(addToken({}));
  //       // navigate("/login");
  //       Modal.warning({
  //         title: "คำขอล้มเหลว",
  //         content: "Sessions Expired",
  //         centered: true,
  //       });
  //       setLoading(false);
  //     });
  // };

  const handleOpenProducts = () => {
    setProductListEventSelected(
      productList.filter((product) => product.event_id === eventType)
    );
    setOpenProductsModal(true);
  };

  const handleOpenDonate = () => {
    setOpenDonateModal(true);
  };

  const handleOpenAddCustomer = () => {
    setOpenAddCustomerModal(true);
  };

  const handleOpenCustomerList = () => {
    setOpenCustomerListModal(true);
  };

  const handleSubmitProducts = (data) => {
    setOpenProductsModal(false);

    setOrderProducts(data);
    // console.log("ORDER PRODUCTS", data);
  };

  const handleSubmitDonate = (data) => {
    // console.log("ORDER DONATE", data);
    setOpenDonateModal(false);
    setOrderDonate(data);
  };

  const handleSubmitAddCustomer = async (data) => {
    // console.log("ORDER CUSTOMERS", data);
    setLoading(true);
    await baseAPI
      .post(`/city_pillar_shrine/customers`, data, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        setOrderCustomer({ ...data, id: response.data.id });
        setDisableAddProductButton(false);
        setLoading(false);
      })
      .catch((error) => {
        setDisableAddProductButton(true);
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
    setOpenAddCustomerModal(false);
  };

  const handleSelectCustomer = (data) => {
    setOpenCustomerListModal(false);
    setOpenAddCustomerModal(false);
    setOrderCustomer(data);
    setDisableAddProductButton(false);
    console.log("CUSTOMER SELECT", data);
  };

  const postOrder = async (data) => {
    console.log("POST ORDER", data);

    await baseAPI
      .post(`/city_pillar_shrine/orders`, data, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        setLoading(false);
        navigate("/myorders");

        // setOrderCustomer({});
        // setOrderProducts([]);
        // setOrderDonate(0);
        // setDisableAddProductButton(true);
      })
      .catch((error) => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
  };

  const handleSubmitOrder = async (data) => {
    // console.log("SUBMIT", data);
    const result = {
      ...data,
      event_id: eventType,
      year,
    };
    Modal.confirm({
      centered: true,
      title: "ยืนยันรายการ",
      content: "หากยืนยันแล้ว ข้อมูลจะถูกบันทึกไปยังฐานข้อมูล",
      onOk: async () => {
        // console.log("ORDER SUBMIT", data);
        setLoading(true);
        dispatch(addOrder(result, year));
        postOrder(result);
      },
    });
  };

  const onChangeYear = (date, dateString) => {
    setYear(dateString);
    getProducts(dateString);
    // setDateSelect(moment().set("year", dateString).format("YYYY-MM-DD"));
  };

  const onRadioChange = (e) => {
    // console.log("onRadioChange", e.target.value);
    setEventType(e.target.value);
    setOrderProducts([]);
    setOrderDonate(0);
  };

  const onChangePaymentType = (event) => {
    setPaymentChannel(event.target.value);
  };

  const onChangeOrderType = (event) => {
    setOrderTypeSelect(event.target.value);

    console.log(event.target.value);
  };

  const handleChangeAmount = (event) => {
    setAmount(event);
  };

  const onClickConfirmOrder = (e) => {
    // console.log();
    const createOrder = {
      order_number: moment().format("YYMMDDhhmmss"),
      ...orderDonate,
      // datetime: moment().format(),
      total_price: sum + (orderDonate?.donate || 0),
      products: [...orderProducts],
      // customer: customer,
      customer_id: orderCustomer.id,
      payment_by_id: paymentChannel,
      user_id: user.id,
      order_type_id: orderTypeSelect,
    };

    setOrderCreate(createOrder);
    // onSubmit(createOrder);
    // console.log(e);
    setOpenModalConfirm(true);
    // }
  };

  // const handleSubmitConfirm = async (data) => {
  //   // console.log(data);
  //   onSubmit(data);
  //   setOpenModalConfirm(false);
  // };

  if (loading) return <Loading />;

  if (dateSelect)
    return (
      <div>
        <div
          style={{
            flexDirection: "column",
            width: "100%",
            justifyContent: "center",
            alignItems: "center",
            display: "flex",
          }}
        >
          <Space>
            <h3>เลือกปี</h3>
            <DatePicker
              onChange={onChangeYear}
              // defaultValue={moment(year, "YYYY")}
              // value={moment(year, "YYYY")}
              picker="year"
            />
          </Space>
        </div>
        <h3>ขายสินค้าประจำปี: {year}</h3>
        <Radio.Group onChange={onRadioChange} value={eventType}>
          <Space direction="vertical">
            <Radio key={1} value={1}>
              เดินขายโคม/ตรุษจีน/ง่วนเซียว
            </Radio>
            <Radio key={2} value={2}>
              งานสมโภชศาลเจ้าปึงเถ่ากง-ม่า
            </Radio>
          </Space>
        </Radio.Group>
        <Divider />
        <div
          style={{
            justifyContent: "space-between",
            display: "flex",
          }}
        >
          <Space direction="vertical">
            <Button
              onClick={handleOpenAddCustomer}
              icon={<PlusOutlined />}
              // disabled={!disableAddProductButton}
            >
              เพิ่มร้านค้าใหม่
            </Button>
            <Button
              onClick={handleOpenCustomerList}
              icon={<ShopOutlined />}
              // disabled={!disableAddProductButton}
            >
              ร้านค้าในระบบ
            </Button>
          </Space>
          <Space direction="vertical">
            {eventType === 1 && (
              <Button
                onClick={handleOpenDonate}
                icon={<DollarOutlined />}
                disabled={disableAddProductButton}
              >
                เงินบริจาค
              </Button>
            )}

            <Button
              onClick={handleOpenProducts}
              icon={<ShoppingCartOutlined />}
              disabled={disableAddProductButton}
            >
              เลือกสินค้า
            </Button>
          </Space>
        </div>
        <Divider />
        {/* {orderCustomer?.storename && <CustomerDetail data={orderCustomer} />} */}

        <CustomerDetail data={orderCustomer} />
        <h4>รายการซื้อ {orderProducts.length} รายการ</h4>
        <OrderDetailList data={orderProducts} />

        {orderDonate.donate ? (
          <div>
            <div
              style={{
                display: "flex",
                justifyContent: "space-between",
                marginTop: "16px",
                marginBottom: "16px",
              }}
            >
              <Space direction="vertical">
                <Text strong>เงินบริจาค</Text>
              </Space>

              <Text strong> {currencyFormatTH(orderDonate.donate)}</Text>
            </div>

            <hr />
          </div>
        ) : null}
        <div
          style={{
            alignItems: "end",
            // justifyContent: "end",
            display: "flex",
            flexDirection: "column",
          }}
        >
          <Text strong>
            รวม {currencyFormatTH(sum + (orderDonate.donate || 0))}
          </Text>
          {paymentChannel === 1 && amount > 0 && (
            <>
              <Text strong>เงินสด {currencyFormatTH(amount)}</Text>
              <Text strong>
                ทอน{" "}
                {currencyFormatTH(amount - (sum + (orderDonate.donate || 0)))}
              </Text>
            </>
          )}
        </div>

        <hr />
        {orderProducts.length !== 0 || orderDonate.donate !== 0 ? (
          <div>
            <h4>ช่องทางชำระ</h4>
            <Radio.Group onChange={onChangePaymentType} value={paymentChannel}>
              <Space direction="vertical">
                <div
                  style={{
                    flexDirection: "row",
                    alignItems: "center",
                    display: "flex",
                    justifyContent: "space-between",
                  }}
                >
                  <Radio value={1}>เงินสด</Radio>
                  <InputNumber
                    style={{ width: 150 }}
                    placeholder="ใส่จำนวนเงินรับ"
                    formatter={(value) =>
                      `${value}`.replace(/\B(?=(\d{3})+(?!\d))/g, ",")
                    }
                    onChange={handleChangeAmount}
                  />
                </div>

                <Radio value={2}>โอนเข้าบัญชี</Radio>
                {eventType === 2 && (
                  <Radio value={3}>เงินเชื่อ (ชำระภายหลัง)</Radio>
                )}
                {/* <Radio value={3}>ชำระภายหลัง</Radio> */}
              </Space>
            </Radio.Group>
            <hr />

            {orderType.length > 0 && eventType === 1 && (
              <>
                <h4>ประเภทบิล</h4>
                <Radio.Group
                  onChange={onChangeOrderType}
                  value={orderTypeSelect}
                >
                  <Space direction="vertical">
                    {orderType?.map((item) => (
                      <Radio key={item.id} value={item.id}>
                        {item.name}
                      </Radio>
                    ))}
                  </Space>
                </Radio.Group>
              </>
            )}

            <div
              style={{
                marginTop: "36px",
                justifyContent: "center",
                display: "flex",
              }}
            >
              <Button
                type="primary"
                key="confirm"
                onClick={onClickConfirmOrder}
                icon={<CheckOutlined />}
              >
                ยืนยันคำสั่งซื้อ
              </Button>
            </div>
          </div>
        ) : null}

        {/* {orderCustomer.id && (
          <OrderDetail
            products={orderProducts}
            orderType={orderType}
            customer={orderCustomer}
            donate={orderDonate}
            onSubmit={handleSubmitOrder}
          />
        )} */}

        <AddCustomerModal
          customers={customerList}
          open={openAddCustomerModal}
          onClose={setOpenAddCustomerModal}
          onSubmit={handleSubmitAddCustomer}
          onSelect={handleSelectCustomer}
        />

        <CustomerListModal
          open={openCustomerListModal}
          data={customerList}
          onClose={setOpenCustomerListModal}
          onSelect={handleSelectCustomer}
        />

        <AddOrderModal
          data={productListEventSelected}
          eventType={eventType}
          open={openProductsModal}
          onClose={setOpenProductsModal}
          onSubmit={handleSubmitProducts}
        />

        <AddDonateModal
          open={openDonateModal}
          onClose={setOpenDonateModal}
          onSubmit={handleSubmitDonate}
        />

        <ConfirmOrderModal
          open={openModalConfirm}
          orderTypeSelect={orderType.filter(
            (item) => item.id === orderCreate.order_type_id
          )}
          event={eventType}
          onSubmit={handleSubmitOrder}
          onClose={setOpenModalConfirm}
          data={orderCreate}
        />
      </div>
    );
}
