import { List } from "antd";
import React from "react";
import { Link } from "react-router-dom";

export default function CustomerItem({
  data,
  onEdit,
  onClickMember,
  onClickItem,
}) {
  const handleClick = () => {
    // console.log("DATA", data);
    onEdit(data);
  };

  const onClickList = () => {
    onClickItem(data);
  };

  const handleClickMember = () => {
    onClickMember(data);
  };

  return (
    <List.Item
      actions={[
        // <Switch
        //   onChange={handleChangeStatus}
        //   checkedChildren="มี"
        //   unCheckedChildren="ไม่มี"
        //   defaultChecked={data.active}
        // />,
        <Link key="members" onClick={handleClickMember}>
          สมาชิก
        </Link>,
        <Link key="choose" onClick={handleClick}>
          แก้ไข
        </Link>,
      ]}
    >
      <List.Item.Meta
        onClick={onClickList}
        title={data?.storename}
        description={data?.address}
      />
    </List.Item>
  );
}
