import {
  Radio,
  Space,
  Typography,
  DatePicker,
  Divider,
  Modal,
  Tabs,
} from "antd";
import React, { useEffect, useState } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { useDispatch, useSelector } from "react-redux";
import { addMyOrder, addOrder, addToken } from "../../../redux/reduxSlice";
import baseAPI from "../../../api/baseAPI";
import OrderList from "./OrderList";
import ConfirmOrderModal from "../order/ConfirmOrderModal";
import OrderDetailModal from "../history/OrderDetailModal";
import Loading from "../../../utils/Loading";
import dayjs from "dayjs";
import moment from "moment";
import OrderHistoryList from "../history/OrderHistoryList";
import OrderEditList from "../history/OrderEditList";
import OrderCancelList from "../history/OrderCancelList";
import OrderReferDetailModal from "../history/OrderReferDetailModal";

// const { RangePicker } = DatePicker;
const { Text } = Typography;
export default function Main() {
  const user = useSelector((state) => state.token);
  // console.log("MYORDER", user);
  // const { id } = useParams();
  const dispatch = useDispatch();
  const navigate = useNavigate();

  // const [radioSelected, setRadioSelected] = useState(1);
  const [orders, setOrders] = useState([]);
  const [orderSelect, setOrderSelect] = useState({});
  const [orderRefer, setOrderRefer] = useState({});
  const [openModalConfirm, setOpenModalConfirm] = useState(false);
  const [openOrderDetailModal, setOpenOrderDetailModal] = useState(false);
  const [openOrderEditModal, setOpenOrderEditModal] = useState(false);
  const [openOrderCancelModal, setOpenOrderCancelModal] = useState(false);
  const [radioSelected, setRadioSelected] = useState(1);

  const [dateSelect, setDateSelect] = useState("");
  const [year, setYear] = useState("");

  const [loading, setLoading] = useState(false);

  useEffect(() => {
    const date = new Date();
    let month = date.getMonth() + 1;
    let year = date.getFullYear();
    if (month > 11) {
      setYear(year + 1);
      setDateSelect(moment().add(1, "years").format("YYYY-MM-DD"));
    } else {
      setYear(year);
      setDateSelect(moment().format("YYYY-MM-DD"));
    }
  }, []);

  useEffect(() => {
    fethcOrder();
  }, [year]);

  const fethcOrder = async () => {
    setLoading(true);
    await baseAPI
      .get(`/city_pillar_shrine/users/order/${user.id}`, {
        params: { year },
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        setOrders(response.data);
        setLoading(false);
      })
      .catch((error) => {
        // dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
  };
  // const onChangeType = (event) => {
  //   setRadioSelected(event.target.value);
  // };

  // const handleChangeDate = async (date, dateString) => {
  //   console.log(date, dateString);
  //   const params = {
  //     dateStart: dateString[0],
  //     dateEnd: dateString[1],
  //   };
  //   // const result = await fetchOrderByDate(params);
  //   // setOrders(result);
  //   // console.log("RESULT", result);
  // };

  const updatePaymentStatus = async (data) => {
    // console.log(data);
    setLoading(true);
    await baseAPI
      .put(`/city_pillar_shrine/orders-payment`, data, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        Modal.success({ content: "ยืนยันการชำระสำเร็จ", centered: true });
        const newState = orders.map((obj) => {
          if (obj.id === data.id) {
            return { ...obj, ...data };
          }
          return obj;
        });
        setOrders(newState);
        setLoading(false);
      })
      .catch((error) => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
  };

  const handleSubmitConfirm = async (data) => {
    setOpenModalConfirm(false);
    updatePaymentStatus(data);
  };

  const handleClickCompleteItem = (item) => {
    console.log("ITEM SELECTED", item);

    if (item.order_refer_id) {
      setOrderRefer(item);
      getOrderIfOrderRefer(item.order_refer_id);
      // handleClickItemEdit(item);
    } else {
      setOrderSelect(item);
      setOpenOrderDetailModal(true);
    }

    // console.log("handleClickItem", item);
  };

  const getOrderIfOrderRefer = async (id) => {
    await baseAPI
      .get(`/city_pillar_shrine/orders/id/${id}`, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        console.log("Order Refer", response.data);
        setOrderSelect(response.data);
        setOpenOrderEditModal(true);
      })
      .catch((err) => {
        // setLoading(false);
        Modal.error({
          title: "ไม่สามารถโหลดข้อมูลได้",
          content: err.message,
          centered: true,
        });
      });
  };

  const handlePrintReceipt = (data) => {
    console.log("MyOrder", data);
    setOpenOrderDetailModal(false);
    setOpenModalConfirm(false);
    dispatch(addMyOrder(data));
    Modal.confirm({
      centered: true,
      title: "พิมพ์ใบเสร็จ",
      content: "ต้องการพิมพ์ใบเสร็จ?",
      onOk: () => {
        navigate("/myorder/receipt");
      },
    });
  };

  const handleCancelOrder = async (data) => {
    console.log("DATA", data);
    setLoading(true);
    await baseAPI
      .put(`/city_pillar_shrine/orders/status`, data, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        Modal.success({
          content: "ยกเลิกรายการสำเร็จ",
          centered: true,
        });
        const newState = orders.map((obj) => {
          if (obj.id === data.id) {
            return { ...obj, ...data, order_status_id: 2 };
          }
          return obj;
        });
        setOrders(newState);
        setOpenOrderDetailModal(false);
        setLoading(false);
      })
      .catch((err) => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
  };

  const handleSubmitMark = async (data) => {
    console.log("DATA", data);
    setOpenOrderDetailModal(false);
    setLoading(true);
    await baseAPI
      .put(`/city_pillar_shrine/orders/status`, data, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        Modal.success({
          content: "แก้ไขรายการสำเร็จ",
          centered: true,
        });
        const newState = orders.map((obj) => {
          if (obj.id === data.id) {
            return { ...obj, ...data };
          }
          return obj;
        });
        setOrders(newState);
        setLoading(false);
      })
      .catch((err) => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
  };

  const handleEditProductList = (data) => {
    dispatch(addOrder(data));
    console.log("Edit MyOrder", data);
    navigate("/orders/edit");
  };

  const handleClickItemEdit = async (data) => {
    // console.log("Old data", data);
    setOrderSelect(data);
    // setLoading(true);
    console.log("Edit History", data);
    await baseAPI
      .get(`/city_pillar_shrine/orders/refer/${data.id}`, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        // console.log("Order Refer", response.data);
        setOrderRefer(response.data);
        setOpenOrderEditModal(true);
        // setLoading(false);
      })
      .catch((err) => {
        // setLoading(false);
        Modal.error({
          title: "ไม่สามารถโหลดข้อมูลได้",
          content: err.message,
          centered: true,
        });
      });
  };

  const onChangeYear = (date, dateString) => {
    setYear(dateString);
    setDateSelect(moment().set("year", dateString).format("YYYY-MM-DD"));
  };

  const handleClickCancleList = (data) => {
    setOrderSelect(data);
    setOpenOrderDetailModal(true);
  };

  const items = [
    {
      key: "1",
      label: "ชำระแล้ว",
      children: (
        <OrderHistoryList
          data={orders.filter(
            (order) =>
              order.order_status_id === 1 &&
              order.payment_by_id !== 3 &&
              order.event_id === 1
          )}
          onClickItem={handleClickCompleteItem}
          // onClickStore={handleClickStore}
        />
      ),
    },
    {
      key: "2",
      label: "เปลี่ยน/แก้ไข",
      children: (
        <OrderEditList
          data={orders.filter(
            (order) => order.order_status_id === 4 && order.event_id === 1
          )}
          onClick={handleClickItemEdit}
        />
      ),
    },
    {
      key: "3",
      label: "ยกเลิก",
      children: (
        <OrderCancelList
          data={orders.filter(
            (order) =>
              (order.order_status_id === 2 || order.order_status_id === 3) &&
              order.event_id === 1
          )}
          onClick={handleClickCancleList}
        />
      ),
    },
    // {
    //   key: "4",
    //   label: "ยกเลิกแล้ว",
    //   children: (
    //     <OrderCancelList
    //       data={orders.filter(
    //         (order) => order.order_status_id === 3 && order.event_id === 1
    //       )}
    //       onClick={handleClickCancleList}
    //     />
    //   ),
    // },
  ];

  const itemCelebrationList = [
    {
      key: "1",
      label: "ยังไม่ชำระ",
      children: (
        <OrderHistoryList
          data={orders.filter(
            (order) =>
              order.order_status_id === 1 &&
              order.payment_by_id === 3 &&
              order.event_id === 2
          )}
          onClickItem={handleClickCompleteItem}
          // onConfirm={handleClickConfirmOrder}
          // onClickItem={handleClickItemEdit}
        />
      ),
    },
    {
      key: "2",
      label: "ชำระแล้ว",
      children: (
        <OrderHistoryList
          data={orders.filter(
            (order) =>
              order.order_status_id === 1 &&
              order.payment_by_id !== 3 &&
              order.event_id === 2
          )}
          onClickItem={handleClickCompleteItem}
        />
      ),
    },
    {
      key: "4",
      label: "แก้ไข/เปลี่ยน",
      children: (
        <OrderEditList
          data={orders.filter(
            (order) => order.order_status_id === 4 && order.event_id === 2
          )}
          onClick={handleClickItemEdit}
        />
      ),
    },
    {
      key: "3",
      label: "ยกเลิก",
      children: (
        <OrderCancelList
          data={orders.filter(
            (order) =>
              order.order_status_id !== 1 &&
              order.order_status_id !== 4 &&
              order.event_id === 2
          )}
          onClick={handleClickCancleList}
          // onClickStore={handleClickStore}
        />
      ),
    },
  ];

  const onChangeType = (event) => {
    console.log("onChangeType", event);
    setRadioSelected(event.target.value);
  };

  if (loading) return <Loading />;

  return (
    <>
      <Space style={{ width: "100%" }} direction="vertical">
        <Text strong>ประเภทบิล</Text>
        <Radio.Group onChange={onChangeType} value={radioSelected}>
          <Space direction="vertical">
            <Radio value={1}>เดินขายโคม/ตรุษจีน/ง่วนเซียว</Radio>
            <Radio value={2}>งานสมโภชศาลเจ้าปึงเถ่ากง-ม่า</Radio>
          </Space>
        </Radio.Group>
        <Divider />
      </Space>

      <div
        style={{
          width: "100%",
          justifyContent: "center",
          display: "flex",
        }}
      >
        <Space>
          <h3>ประจำปี</h3>
          <DatePicker
            onChange={onChangeYear}
            defaultValue={dayjs(dateSelect, "YYYY")}
            picker="year"
          />
        </Space>
      </div>
      <Divider />
      {radioSelected === 1 ? (
        <>
          <Tabs defaultActiveKey="1" items={items} />
        </>
      ) : (
        <>
          <Tabs defaultActiveKey="1" items={itemCelebrationList} />
        </>
      )}
      {/* <Tabs defaultActiveKey="1" items={items} /> */}
      {/* <OrderList data={orders} onClickItem={handleClickItem} /> */}

      <ConfirmOrderModal
        open={openModalConfirm}
        onSubmit={handleSubmitConfirm}
        onClose={setOpenModalConfirm}
        onDownloadReceipt={handlePrintReceipt}
        data={orderSelect}
      />

      <OrderDetailModal
        open={openOrderDetailModal}
        data={orderSelect}
        onclose={setOpenOrderDetailModal}
        onCancelOrder={handleCancelOrder}
        onSubmit={handleSubmitMark}
        onPrint={handlePrintReceipt}
        onEdit={handleEditProductList}
      />

      <OrderReferDetailModal
        open={openOrderEditModal}
        data={orderSelect}
        dataRefer={orderRefer}
        onclose={setOpenOrderEditModal}
        onCancelOrder={handleCancelOrder}
        onSubmit={handleSubmitMark}
        onPrint={handlePrintReceipt}
      />
    </>
  );
}
