import { List } from "antd";
import React from "react";
import CustomerMemberItem from "./CustomerMemberItem";

export default function CustomerMemberList({ data, onDelete }) {
  console.log("CustomerMemberList", data);
  return (
    <List
      pagination={{
        onChange: (page) => {
          console.log(page);
        },
        pageSize: 10,
      }}
      itemLayout="horizontal"
      dataSource={data}
      renderItem={(item, index) => (
        <CustomerMemberItem
          data={item}
          onDelete={onDelete}

          //   onStatusChange={onStatusChange}
          //   onEdit={handleEditProduct}
          //   onRemove={handleRemove}
        />
      )}
    />
  );
}
