import React, { useEffect, useState } from "react";
import {
  Modal,
  Button,
  Typography,
  Divider,
  Space,
  Upload,
  Image,
  List,
} from "antd";
import Resizer from "react-image-file-resizer";
// import OrderDetailList from "./OrderDetailList";
import OrderDetailList from "../order/OrderDetailList";
import moment from "moment";
import ProductItem from "./ProductItem";
const { Text } = Typography;

export default function FinishJobModal({ open, data, onClose, onSubmit }) {
  //   console.log("ITEM CLICKED", data);
  const [imgFile, setImgFile] = useState(null);
  const handleClose = () => {
    onClose(false);
  };

  useEffect(() => {
    return () => {
      setImgFile(null);
    };
  }, [data]);

  const handleSubmit = () => {
    const newData = {
      id: data.id,
      maintenance_status_id: 3,
      maintenance_by_user_id: data.maintenance_by_user_id,
      maintenance_finish_datetime: moment().format("YYYY-MM-DD HH:mm:ss"),
      maintenance_img: imgFile,
    };
    // console.log("onSubmit", newData);
    onSubmit(newData);
  };

  const onChange = async (e) => {
    const file = e.target.files[0];
    const image = await resizeFile(file);
    // console.log(image);
    setImgFile(image);
  };

  const resizeFile = (file) =>
    new Promise((resolve) => {
      Resizer.imageFileResizer(
        file,
        300,
        300,
        "JPEG",
        300,
        0,
        (uri) => {
          resolve(uri);
        },
        "base64"
      );
    });

  return (
    <Modal
      title="ยืนยันรายการ"
      centered={true}
      open={open}
      onOk={handleSubmit}
      closeIcon={false}
      footer={[
        // <Button key="receipt" onClick={handleDownloadReceipt}>
        //   พิมพ์ใบเสร็จ
        // </Button>,
        <Button
          disabled={!imgFile}
          key="submit"
          type="primary"
          onClick={handleSubmit}
        >
          ส่งงานติดตั้ง
        </Button>,
        <Button key="close" onClick={handleClose}>
          ปิด
        </Button>,
      ]}
    >
      <div>
        <Space direction="vertical">
          <Text strong>ชื่อลูกค้า :{data?.storename}</Text>
          <Text strong>โทร : {data.phone}</Text>
        </Space>

        <Divider />
        <List
          itemLayout="horizontal"
          dataSource={data.products}
          renderItem={(item, index) => <ProductItem key={index} data={item} />}
        />
        {/* <OrderDetailList data={data.products} /> */}

        <Divider />
        <div style={{ justifyContent: "center", display: "flex" }}>
          <Space direction="vertical" align="center">
            <Text strong>รูปถ่ายงานติดตั้งสำเร็จแล้ว</Text>
            <input type="file" onChange={onChange} />
            {imgFile ? (
              <div style={{ justifyContent: "center", display: "flex" }}>
                <Image width={100} src={imgFile} />
              </div>
            ) : null}
          </Space>
        </div>
        <Divider />
      </div>
    </Modal>
  );
}
