import {
  Modal,
  Button,
  Typography,
  Divider,
  List,
  Image,
  Input,
  Space,
} from "antd";
import React, { useEffect, useState } from "react";
import ProductItem from "./ProductItem";
import CustomerDetail from "../order/CustomerDetail";
import { useSelector } from "react-redux";
import { currencyFormat, currencyFormatTH } from "../../../utils/numberFormat";
import moment from "moment";

const { Text } = Typography;

export default function OrderDetailModal({
  open,
  data,
  onclose,
  onPrint,
  onCancelOrder,
  onSubmit,
  onEdit,
}) {
  // const [products, setProducts] = useState([]);
  const user = useSelector((state) => state.token);
  const [mark, setMark] = useState("");
  const handleClose = () => {
    onclose(false);
  };

  const handleEditProductList = () => {
    const newData = {
      ...data,
      // id: data.id,
      order_status_id: 4,
      mark: mark,
    };

    Modal.confirm({
      title: "แก้ไข/เปลี่ยน",
      content: "ต้องการแก้ไข หรือเปลี่ยนรายการสินค้า",
      centered: true,
      onOk: () => {
        onEdit(newData);
      },
    });
  };

  const handlePrint = () => {
    // console.log("DATA", data);
    onPrint(data);
  };

  const handleCancelOrder = () => {
    const status = {
      ...data,
      // id: data.id,
      order_status_id: 2,
      mark: mark,
    };
    Modal.confirm({
      title: "ยกเลิกรายการ",
      content: "ต้องการยกเลิกรายการสั่งซื้อนี้",
      centered: true,
      onOk: () => {
        onCancelOrder(status);
      },
    });
  };

  const handleSubmit = () => {
    const status = {
      ...data,
      // id: data.id,
      order_status_id: 1,
      mark: mark,
    };
    Modal.confirm({
      title: "บันทึกการแก้ไข",
      content: "ต้องการบันทึกรายการแก้ไขหมายเหตุ",
      centered: true,
      onOk: () => {
        onSubmit(status);
      },
    });
  };

  useEffect(() => {
    // setProducts(data);
    // console.log("ORDER DETAILS", data);
  }, [data]);

  return (
    <Modal
      title="รายละเอียด"
      centered={true}
      // width={1000}
      open={open}
      //   onOk={handleSubmit}
      closeIcon={false}
      onCancel={handleClose}
      footer={[
        data.order_status_id === 1 && (
          <Button
            danger
            type="primary"
            disabled={mark === ""}
            key="remove"
            onClick={handleCancelOrder}
          >
            ยกเลิกรายการ
          </Button>
        ),
        <Button
          key="edit"
          // type="primary"
          disabled={mark === ""}
          onClick={handleEditProductList}
        >
          แก้ไข/เปลี่ยน
        </Button>,
        <Button
          key="receipt"
          disabled={data?.order_status_id !== 1}
          onClick={handlePrint}
        >
          พิมพ์ใบเสร็จ
        </Button>,
        <Button
          type="primary"
          key="submit"
          disabled={mark === ""}
          onClick={handleSubmit}
        >
          บันทึก
        </Button>,
        <Button key="close" onClick={handleClose}>
          ปิด
        </Button>,
      ]}
    >
      <>
        <Divider />
        <CustomerDetail data={data} />

        <List
          itemLayout="horizontal"
          dataSource={data.products}
          renderItem={(item, index) => <ProductItem key={index} data={item} />}
        />

        {data.donate !== 0 && data.event_id === 1 && (
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              marginTop: "16px",
              marginBottom: "16px",
            }}
          >
            <Text strong>เงินบริจาค</Text>
            <Text strong> {currencyFormatTH(data.donate || 0)}</Text>
          </div>
        )}
        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            marginTop: "16px",
            marginBottom: "16px",
          }}
        >
          <Text strong>ยอดรวม</Text>
          <Text strong> {currencyFormatTH(data.total_price)}</Text>
        </div>
        <hr />
        <Space direction="vertical">
          <Text>ช่องทางชำระ: {data.payment}</Text>
          <Text color="secondary">
            วันที่ชำระ:{" "}
            {data.payment_date
              ? moment(data.payment_date).format("lll")
              : "ยังไม่ชำระ"}
          </Text>
          {data.order_type && data.event_id === 1 && (
            <Text>ประเภทบิล: {data.order_type}</Text>
          )}
          <Text type="secondary">หมายเหตุ: {data.mark}</Text>
        </Space>

        {data.payment_by_id === 2 && (
          <div
            style={{
              marginTop: "24px",
              justifyContent: "center",
              display: "flex",
            }}
          >
            {/* <img src={data.payment_img} alt="payment" /> */}
            <Image width={100} src={data.payment_img} />
          </div>
        )}
      </>
      <div
        style={{
          marginTop: "24px",
        }}
      >
        {data.order_status_id === 1 ? (
          <Input
            placeholder="ใส่หมายเหตุก่อนยกเลิก หรือแก้ไข"
            onChange={(e) => setMark(e.target.value)}
          />
        ) : (
          <Text strong type="danger">
            หมายเหตุ: {data.mark}
          </Text>
        )}
      </div>
    </Modal>
  );
}
