import React, { useEffect, useState } from "react";
import {
  Button,
  Divider,
  Modal,
  Radio,
  Select,
  Space,
  Tabs,
  Typography,
} from "antd";
import { PlusOutlined } from "@ant-design/icons";
import { useDispatch, useSelector } from "react-redux";
import baseAPI from "../../../api/baseAPI";
import Loading from "../../../utils/Loading";
import { useNavigate } from "react-router-dom";
import { addToken, addShippingOrder } from "../../../redux/reduxSlice";
import pdfMake from "pdfmake/build/pdfmake";
import pdfFonts from "pdfmake/build/vfs_fonts";
import moment from "moment";
import HistorySearch from "../history/HistorySearch";
import OrderList from "./OrderList";
import CustomerDetailModal from "../customer/CustomerDetailModal";
import PrintWorkSheetModal from "./PrintWorkSheetModal";
import { InstallationDoc } from "./pdf/InstallationDoc";
import FinishJobModal from "./FinishJobModal";
import OrderDetailModal from "./OrderDetailModal";
import DeliveryListExcel from "./report/DeliveryListExcel";

const { Text } = Typography;

pdfMake.vfs = pdfFonts.pdfMake.vfs;

//ต้องระบุตามชื่อของ ไฟล์ font
pdfMake.fonts = {
  THSarabunNew: {
    normal: "THSarabunNew.ttf",
    bold: "THSarabunNew Bold.ttf",
    italics: "THSarabunNew Italic.ttf",
    bolditalics: "THSarabunNew Bold Italic.ttf",
  },
  AngsanaNew: {
    normal: "AngsanaNew.ttf",
    bold: "AngsanaNew Bold.ttf",
    italics: "AngsanaNew Italic.ttf",
    bolditalics: "AngsanaNew Bold Italic.ttf",
  },
  Roboto: {
    normal: "Roboto-Regular.ttf",
    bold: "Roboto-Medium.ttf",
    italics: "Roboto-Italic.ttf",
    bolditalics: "Roboto-MediumItalic.ttf",
  },
};

export default function Main() {
  const user = useSelector((state) => state.token);
  // console.log(user);
  const dispatch = useDispatch();
  const navigate = useNavigate();

  const [openFinishJobModal, setOpenFinishJobModal] = useState(false);
  const [openFinishJobDetailModal, setOpenFinishJobDetailModal] =
    useState(false);
  const [openCustomerDetailsModal, setOpenCustomerDetailsModal] =
    useState(false);

  const [openPrintWorkSheetModal, setOpenPrintWorkSheetModal] = useState(false);
  const [customerSelect, setCustomerSelect] = useState(false);
  const [orderListHolder, setOrderListHolder] = useState([]);
  const [orderList, setOrderList] = useState([]);
  const [year, setYear] = useState(moment(new Date()).format("YYYY"));
  const [products, setProducts] = useState([]);
  // const [orderDelivery, setOrderDelivery] = useState([]);
  //   const [team, setTeam] = useState([]);
  //   const [data, setData] = useState({});
  // const [radioSelected, setRadioSelected] = useState(1);
  const [loading, setLoading] = useState(false);
  useEffect(() => {
    // if (user.role !== "admin") {
    const date = new Date();
    let month = date.getMonth() + 1;
    // let year = date.getFullYear();
    if (month >= 10) {
      // year += 1;
      setYear(moment().add(1, "years").format("YYYY"));
    } else {
      setYear(moment().format("YYYY"));
    }
    fecthLastData();
    fetchAllProducts(year);
    // }
  }, []);

  const fecthLastData = async () => {
    let url = `/city_pillar_shrine/delivery`;

    await baseAPI
      .get(url, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((res) => {
        setOrderList(res.data);
        setOrderListHolder(res.data);
      })
      .catch((err) => {
        Modal.error({
          title: "ไม่สามารถโหลดข้อมูลได้",
          content: err.message,
          centered: true,
        });
      });
  };

  const handleSearch = (data) => {
    setOrderList(data);
    setOrderListHolder(data);
  };

  const handleChangeYear = (data) => {
    setYear(data);
    fetchAllProducts(data);
  };

  const fetchAllProducts = async (year) => {
    await baseAPI
      .get("/city_pillar_shrine/products", {
        params: { year },
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        console.log("PRODUCTS", response.data);
        // const result = response.data.filter(
        //   (item) => item.name.includes("พร้อมติดตั้ง") === false
        // );
        setProducts(response.data);
      })
      .catch((err) => {
        Modal.error({
          title: "ไม่สามารถโหลดข้อมูลได้",
          content: err.message,
          centered: true,
        });
      });
  };

  const handleClickManageJob = async (data) => {
    setCustomerSelect(data);
    setOpenFinishJobModal(true);
  };

  const handleSubmitFinishJob = async (data) => {
    console.log("MAIN Submit", data);
    setOpenFinishJobModal(false);
    await baseAPI
      .put("/city_pillar_shrine/delivery-finish", data, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        Modal.success({
          title: "สำเร็จ",
          content: "ยืนยันการจัดส่งสำเร็จ",
          centered: true,
        });

        fecthLastData();
        // setOpenManageTeamModal(false);
        // fetchData();
        setLoading(false);
      })
      .catch((error) => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
  };

  const handleClickItem = (data) => {
    console.log("OnClickItem", data);
    setCustomerSelect(data);
    setOpenCustomerDetailsModal(true);
  };

  const handleClickFinishDetail = (data) => {
    setCustomerSelect(data);
    setOpenFinishJobDetailModal(true);
  };

  const handleSubmitPrint = async (data) => {
    // setOrderDelivery(data);
    console.log("Mark", data);
    await baseAPI
      .put("/city_pillar_shrine/delivery-mark", data, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        // const newState = orderList.map((obj) => {
        //   if (obj.id === data.id) {
        //     return { ...obj, ...data };
        //   }
        //   return obj;
        // });
        // setOrderList(newState);
        setOpenPrintWorkSheetModal(false);
        // fetchData();

        setLoading(false);
      })
      .catch((error) => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });

    handlePrint(data);
  };

  const handlePrint = async (data) => {
    let orders = [];
    data.products.map((product, index) => {
      const data = [
        {
          text: index + 1,
          alignment: "center",
          style: "textBody",
        },
        {
          text: product.name,
          alignment: "left",
          style: "textBody",
        },
        {
          text: product.amount,
          alignment: "center",
          style: "textBody",
        },
      ];
      orders.push(data);
    });
    const result = await InstallationDoc({ data, orders });
    pdfMake.createPdf(result).open();
  };

  const handleChangeProduct = async (e) => {
    console.log("Product", e);
    let arrNew = [];
    orderListHolder.filter((item) => {
      item.products.map((product) => {
        if (product.productId === e) {
          arrNew.push(item);
        }
      });
    });
    console.log(arrNew);
    setOrderList(arrNew);
  };

  const handleSearchProduct = async (e) => {
    let arrNew = [];
    orderListHolder.filter((item) => {
      item.products.map((product) => {
        if (product.name === e) {
          arrNew.push(item);
        }
      });
    });
    console.log(arrNew);
    setOrderList(arrNew);
  };

  const handlePrintAddress = (data) => {
    console.log("MyOrder", data);
    // setOpenOrderDetailModal(false);
    // setOpenModalConfirm(false);
    dispatch(addShippingOrder(data));
    Modal.confirm({
      centered: true,
      title: "พิมพ์ใบปะหน้าพัสดุ",
      content: "ต้องการพิมพ์ใบปะหน้าพัสดุ?",
      onOk: () => {
        navigate("/delivery/shipping");
      },
    });
  };

  if (loading) return <Loading />;

  const items = [
    {
      key: "1",
      label: "รายการใหม่",
      children: (
        <OrderList
          status={false}
          data={orderList.filter((order) => order.delivery_status_id === 1)}
          onClickPrintAddress={handlePrintAddress}
          onClickManageJob={handleClickManageJob}
          onClickItem={handleClickItem}
        />
      ),
    },
    {
      key: "2",
      label: "จัดส่งแล้วบางส่วน",
      children: (
        <OrderList
          status={true}
          data={orderList.filter((order) => order.delivery_status_id === 2)}
          onClickPrintAddress={handlePrintAddress}
          onClickManageJob={handleClickManageJob}
          onClickItem={handleClickItem}
        />
      ),
    },
    {
      key: "3",
      label: "จัดส่งแล้วทั้งหมด",
      children: (
        <OrderList
          status={true}
          data={orderList.filter((order) => order.delivery_status_id === 3)}
          onClickFinishJobDetail={handleClickFinishDetail}
          onClickItem={handleClickItem}
        />
      ),
    },
  ];

  const filterOption = (input, option) =>
    (option?.label ?? "").toLowerCase().includes(input.toLowerCase());

  return (
    <Space style={{ width: "100%" }} direction="vertical">
      <HistorySearch
        onSearch={handleSearch}
        searchType={"delivery"}
        onChangeYear={handleChangeYear}
      />
      <DeliveryListExcel data={orderList} />
      <Text style={{ marginTop: "16px" }}>ตัวกรอง</Text>
      <Select
        showSearch
        placeholder="ค้นหาจากชื่อรายการสินค้า"
        optionFilterProp="children"
        style={{ width: "100%" }}
        onChange={handleChangeProduct}
        onSearch={handleSearchProduct}
        filterOption={filterOption}
        options={products.map((item) => ({
          value: item.id,
          label: item.name,
          item,
        }))}
      />
      <Tabs defaultActiveKey="1" items={items} />
      {/* <InstallationManage
        open={openManageTeamModal}
        teamList={team}
        data={data}
        onClose={setOpenManageTeamModal}
        onSubmit={handleSubmitManage}
      /> */}
      <CustomerDetailModal
        data={customerSelect}
        open={openCustomerDetailsModal}
        onClose={setOpenCustomerDetailsModal}
      />
      <FinishJobModal
        open={openFinishJobModal}
        data={customerSelect}
        onClose={setOpenFinishJobModal}
        onSubmit={handleSubmitFinishJob}
        onPrint={handleSubmitPrint}
      />
      <OrderDetailModal
        data={customerSelect}
        open={openFinishJobDetailModal}
        onClose={setOpenFinishJobDetailModal}
        onPrint={handlePrint}
      />

      <PrintWorkSheetModal
        open={openPrintWorkSheetModal}
        data={customerSelect}
        onClose={setOpenPrintWorkSheetModal}
        onSubmit={handleSubmitPrint}
      />
    </Space>
  );
}
