import React, { useEffect, useState } from "react";
import {
  Button,
  Modal,
  Form,
  Input,
  Select,
  Typography,
  Space,
  Radio,
  InputNumber,
} from "antd";
import GoogleMapReact from "google-map-react";
import { useDispatch, useSelector } from "react-redux";
import MarkerImg from "../../../assets/images/Marker.png";
import { GOOGLEMAP_API_KEY } from "../../../utils/googlemapkey";
import { Link } from "react-router-dom";
import baseAPI from "../../../api/baseAPI";
const { TextArea } = Input;
const { Text } = Typography;
const Marker = () => (
  <div>
    <img width={30} src={MarkerImg} alt="" />
    {/* <HomeFilled /> */}
  </div>
);

export default function AddCustomerModal({
  customers,
  open,
  onClose,
  onSubmit,
  onSelect,
}) {
  const user = useSelector((state) => state.token);
  const [latLng, setLatLng] = useState({ lat: 0, lng: 0 });
  const [customerByName, setCustomerByName] = useState(null);
  const [customerByPhone, setCustomerByPhone] = useState(null);
  const [selectMap, setSelectMap] = useState(1);
  const [selectProvince, setSelectProvince] = useState(1);
  const [roads, setRoads] = useState([]);

  // const [customerList, setCustomerList] = useState([]);

  useEffect(() => {
    if (open) {
      fetchAllRoad();
    }
  }, [open]);

  const fetchAllRoad = async () => {
    await baseAPI
      .get(`/city_pillar_shrine/khonkaen-road`, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        console.log(response.data);
        setRoads(response.data);
      })
      .catch((error) => {
        Modal.error({
          centered: true,
          title: "ผิดพลาด",
          content: error.message,
        });
      });
  };

  function success(position) {
    const latitude = position.coords.latitude;
    const longitude = position.coords.longitude;
    console.log(`Latitude: ${latitude}, Longitude: ${longitude}`);
    setLatLng({ lat: latitude, lng: longitude });
  }

  function errors() {
    console.log("Unable to retrieve your location");
  }
  var options = {
    enableHighAccuracy: true,
    timeout: 5000,
    maximumAge: 0,
  };

  useEffect(() => {
    form.setFieldsValue({
      road: "",
      address: "",
      moo: "",
      soi: "",
      subdistrict: "ในเมือง",
      district: "เมืองขอนแก่น",
      province: "ขอนแก่น",
      zipcode: "40000",
    });
    if (navigator.geolocation) {
      navigator.permissions
        .query({ name: "geolocation" })
        .then(function (result) {
          // console.log(result);
          if (result.state === "granted") {
            //If granted then you can directly call your function here
            navigator.geolocation.getCurrentPosition(success, errors, options);
          } else if (result.state === "prompt") {
            //If prompt then the user will be asked to give permission
            navigator.geolocation.getCurrentPosition(success, errors, options);
          } else if (result.state === "denied") {
            //If denied then you have to show instructions to enable location
          }
        });
    } else {
      console.log("Geolocation is not supported by this browser.");
    }
  }, []);

  const defaultProps = {
    center: {
      lat: latLng.lat,
      lng: latLng.lng,
    },
    zoom: 14,
  };
  const [marker, setMarker] = useState({
    lat: 0,
    lng: 0,
  });
  const [form] = Form.useForm();
  const handleClose = () => {
    onClose(false);
  };
  const handleSubmit = (data) => {
    // if (marker.lat !== 0 && marker.lng !== 0) {
    let group = {};
    if (data.moo !== "" && data.soi !== "") {
      group = {
        ...data,
        address:
          data.address +
          " หมู่ " +
          data.moo +
          " ซอย " +
          data.soi +
          " ต." +
          data.subdistrict +
          " อ." +
          data.district +
          " จ." +
          data.province +
          " " +
          data.zipcode,
        latitude: marker.lat,
        longitude: marker.lng,
      };
    } else if (data.moo !== "" && data.soi === "") {
      group = {
        ...data,
        address:
          data.address +
          " หมู่ " +
          data.moo +
          " ต." +
          data.subdistrict +
          " อ." +
          data.district +
          " จ." +
          data.province +
          " " +
          data.zipcode,
        latitude: marker.lat,
        longitude: marker.lng,
      };
    } else if (data.moo === "" && data.soi !== "") {
      group = {
        ...data,
        address:
          data.address +
          " ซอย " +
          data.soi +
          " ต." +
          data.subdistrict +
          " อ." +
          data.district +
          " จ." +
          data.province +
          " " +
          data.zipcode,
        latitude: marker.lat,
        longitude: marker.lng,
      };
    } else {
      group = {
        ...data,
        address:
          data.address +
          " ต." +
          data.subdistrict +
          " อ." +
          data.district +
          " จ." +
          data.province +
          " " +
          data.zipcode,
        latitude: marker.lat,
        longitude: marker.lng,
      };
    }
    onSubmit(group);
    console.log("ADD DATA", group);
    // } else {
    //   alert("กรุณาระบุพิกัด Google Map");
    // }
  };

  const onFinishFailed = (e) => {
    console.log("Failure", e);
  };

  const onMapClick = (data) => {
    // console.log("MapClick", data);
    setMarker({
      lat: data.lat,
      lng: data.lng,
    });
  };

  const onMapLoad = () => {
    setMarker({
      lat: latLng.lat,
      lng: latLng.lng,
    });
  };

  const handleChangeStorename = (e) => {
    const [result] = customers.filter((c) => c.storename === e.target.value);
    setCustomerByName(result);
    console.log(result);
  };

  const handleChangePhone = (e) => {
    const [result] = customers.filter((c) => c.phone === e.target.value);
    setCustomerByPhone(result);
    console.log(result);
  };

  const onSelectByName = () => {
    onSelect(customerByName);
  };

  const onSelectByPhone = () => {
    onSelect(customerByPhone);
  };

  const handleChageLatLng = (e) => {
    const result = e.target.value;
    // console.log(result);
    const arr = result.split(",");
    console.log(arr);
    setMarker({
      lat: arr[0],
      lng: arr[1],
    });
  };

  const handleSelectProvince = (e) => {
    const value = e.target.value;
    setSelectProvince(e.target.value);
    if (value === 1) {
      form.setFieldsValue({
        road: "",
        address: "",
        moo: "",
        soi: "",
        subdristrict: "ในเมือง",
        district: "เมืองขอนแก่น",
        province: "ขอนแก่น",
        zipcode: "40000",
      });
    } else {
      form.setFieldsValue({
        road: "",
        address: "",
        moo: "",
        soi: "",
        subdristrict: "",
        district: "",
        province: "",
        zipcode: "",
      });
    }
  };

  const filterOption = (input, option) =>
    (option?.label ?? "").toLowerCase().includes(input.toLowerCase());

  return (
    <Modal
      title="ข้อมูลร้านค้า"
      centered={true}
      // width={1000}
      open={open}
      //   onOk={handleSubmit}
      closeIcon={false}
      onCancel={handleClose}
      footer={[
        <Button key="close" onClick={handleClose}>
          ยกเลิก
        </Button>,
        <Button
          key="submit"
          htmlType="submit"
          type="primary"
          onClick={form.submit}
        >
          บันทึก
        </Button>,
      ]}
    >
      <Form
        id="form"
        onFinish={handleSubmit}
        onFinishFailed={onFinishFailed}
        layout={"vertical"}
        form={form}
      >
        {/* <div style={{ justifyContent: "end", display: "flex" }}>
          <Button onClick={handleSearchClick}>ค้นหาร้านค้าจากระบบ</Button>
        </div> */}
        <Form.Item
          name="storename"
          label="ชื่อร้านค้า"
          rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
        >
          <Input placeholder="ชื่อร้านค้า" onChange={handleChangeStorename} />
        </Form.Item>
        {customerByName && (
          <Space>
            <Text type="danger">มีร้านค้านี้ในระบบ</Text>
            <Button onClick={onSelectByName} type="primary">
              เลือกจากระบบ
            </Button>
          </Space>
        )}
        <Form.Item
          name="fullname"
          label="ชื่อ-สกุล"
          rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
        >
          <Input placeholder="ชื่อ-สกุล" />
        </Form.Item>
        <Radio.Group
          style={{ marginBottom: 16 }}
          onChange={handleSelectProvince}
          value={selectProvince}
        >
          <Space direction="vertical">
            <Radio value={1}>จังหวัดขอนแก่น</Radio>
            <Radio value={2}>กำหนดเอง</Radio>
          </Space>
        </Radio.Group>
        {selectProvince === 1 ? (
          <Form.Item
            name="road"
            label="สาย/ถนน"
            rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
          >
            <Select
              showSearch
              placeholder="ค้นหาจากชื่อร้าน"
              optionFilterProp="children"
              style={{ marginTop: "16px", width: "100%" }}
              // onChange={handleChangeRoad}
              // onSearch={onSearch}
              filterOption={filterOption}
              options={roads.map((item) => ({
                value: item.road,
                label: item.road,
                // item,
              }))}
            />
          </Form.Item>
        ) : (
          <Form.Item
            name="road"
            label="สาย/ถนน"
            rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
          >
            <Input placeholder="สาย/ถนน" />
          </Form.Item>
        )}
        <Form.Item
          name="address"
          label="บ้านเลขที่"
          rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
        >
          <Input placeholder="เลขที่" />
        </Form.Item>
        <Form.Item name="moo" label="หมู่ที่">
          <Input placeholder="หมู่ที่" />
        </Form.Item>
        <Form.Item name="soi" label="ซอย">
          <Input placeholder="ซอย" />
        </Form.Item>
        <Form.Item
          name="subdistrict"
          label="ตำบล"
          rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
        >
          <Input placeholder="ตำบล" />
        </Form.Item>
        <Form.Item
          name="district"
          label="อำเภอ"
          rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
        >
          <Input placeholder="อำเภอ" />
        </Form.Item>
        <Form.Item
          name="province"
          label="จังหวัด"
          rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
        >
          <Input placeholder="จังหวัด" />
        </Form.Item>
        <Form.Item
          name="zipcode"
          label="รหัสไปรษณีย์"
          rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
        >
          <Input placeholder="รหัสไปรษณีย์" />
        </Form.Item>
        <Radio.Group
          style={{ marginBottom: 16 }}
          onChange={(e) => setSelectMap(e.target.value)}
          value={selectMap}
        >
          <Space direction="vertical">
            <Radio value={1}>เลือกพิกัดเอง</Radio>

            <Radio value={2}>พิกัด Latitude, Longitude</Radio>
          </Space>
        </Radio.Group>
        {selectMap === 2 ? (
          // <div>
          <Form.Item
            label="ใส่พิกัดเป็น Lat, Lng "
            rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
          >
            <Input
              // style={{ width: 150 }}
              placeholder="เช่น 16.121565313, 102.335565354"
              // formatter={(value) =>
              //   `${value}`.replace(/\B(?=(\d{3})+(?!\d))/g, ",")
              // }
              onChange={handleChageLatLng}
            />
          </Form.Item>
        ) : (
          // </div>
          <>
            <div style={{ height: "350px", width: "100%", marginBottom: 16 }}>
              <GoogleMapReact
                bootstrapURLKeys={{ key: GOOGLEMAP_API_KEY }}
                center={defaultProps.center}
                defaultZoom={defaultProps.zoom}
                yesIWantToUseGoogleMapApiInternals
                onClick={onMapClick}
                onGoogleApiLoaded={onMapLoad}
              >
                <Marker lat={marker.lat} lng={marker.lng} />
              </GoogleMapReact>
            </div>
          </>
        )}
        <Form.Item
          name="phone"
          label="โทรศัพท์"
          rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
        >
          <Input placeholder="โทรศัพท์" onChange={handleChangePhone} />
        </Form.Item>
        {customerByPhone && (
          <Space>
            <Text type="danger">
              พบชื่อร้าน "{customerByPhone.storename}" ในระบบ
            </Text>
            <Button onClick={onSelectByPhone} type="primary">
              เลือกจากระบบ
            </Button>
          </Space>
        )}
        <Form.Item name="line" label="ไลน์">
          <Input placeholder="ไลน์" />
        </Form.Item>
      </Form>
    </Modal>
  );
}
