import moment from "moment";
import React, { useEffect, useState } from "react";
import ReactExport from "react-export-excel";
import { Link } from "react-router-dom";

const ExcelFile = ReactExport.ExcelFile;
const ExcelSheet = ReactExport.ExcelFile.ExcelSheet;
const ExcelColumn = ReactExport.ExcelFile.ExcelColumn;

export default function OrderList({ data }) {
  const [dataSource, setDataSource] = useState([]);

  useEffect(() => {
    mapData();
  }, [data]);

  //   useEffect(() => {
  // console.log(dataSource);
  //   }, [dataSource]);

  const mapData = () => {
    let arr = [];
    data.map((item) => arr.push(...item.products));
    setDataSource(arr);
  };

  //   const
  return (
    <div style={{ width: "100%", justifyContent: "end", display: "flex" }}>
      <ExcelFile element={<Link>Download</Link>}>
        {/* <ExcelSheet dataSet={multiDataSet} name="Organization" /> */}
        <ExcelSheet data={data} name="ยอดขายสินค้า">
          <ExcelColumn label="ประเภท" value="order_type" />
          <ExcelColumn label="สถานะ" value="order_status" />
          <ExcelColumn label="เลขที่ใบเสร็จ" value="order_number" />
          <ExcelColumn
            label="วันที่"
            value={(col) => moment(col.datetime).format("DD/MM/YY")}
          />
          <ExcelColumn
            label="กรรมการ"
            value={(col) =>
              col.user_name +
              " " +
              col.user_lastname +
              " ( " +
              col.user_nickname +
              " )"
            }
          />
          <ExcelColumn label="ร้านค้า" value="storename" />
          <ExcelColumn label="ชื่อลูกค้า" value="fullname" />
          <ExcelColumn label="ที่อยู่" value="address" />
          {/* <ExcelColumn label="รายการขาย" value="name" /> */}
          <ExcelColumn label="ช่องทางชำระ" value="payment" />
          <ExcelColumn
            label="ยอดซื้อสินค้า"
            value={(col) => parseInt(col.total_price) - parseInt(col.donate)}
          />
          <ExcelColumn label="เงินบริจาค" value="donate" />
          <ExcelColumn label="ยอดขายรวม" value="total_price" />
          <ExcelColumn label="หมายเหตุ" value="mark" />
        </ExcelSheet>
        <ExcelSheet data={dataSource} name="รายการขาย">
          <ExcelColumn label="ประเภท" value="order_type" />
          <ExcelColumn label="สถานะ" value="order_status" />
          <ExcelColumn label="เลขที่ใบเสร็จ" value="order_number" />
          <ExcelColumn
            label="วันที่"
            value={(col) => moment(col.datetime).format("DD/MM/YY")}
          />
          <ExcelColumn
            label="กรรมการ"
            value={(col) =>
              col.user_name +
              " " +
              col.user_lastname +
              " ( " +
              col.user_nickname +
              " )"
            }
          />
          <ExcelColumn label="ร้านค้า" value="storename" />
          <ExcelColumn label="ชื่อลูกค้า" value="fullname" />
          <ExcelColumn label="ที่อยู่" value="address" />
          <ExcelColumn label="รายการขาย" value="name" />
          <ExcelColumn label="จำนวน" value="amount" />
          <ExcelColumn label="ราคา" value="price" />
          <ExcelColumn label="เงินบริจาค" value="donate" />
          <ExcelColumn label="หมายเหตุ" value="mark" />
        </ExcelSheet>
      </ExcelFile>
    </div>
  );
}
