import React, { useEffect, useState } from "react";
import { Button, Modal, Form, Input } from "antd";
import CustomerMemberList from "./CustomerMemberList";
export default function CustomerMemberListModal({
  open,
  members,
  onClose,
  onSubmit,
  onDelete,
}) {
  const [form] = Form.useForm();
  const [addMember, setAddMember] = useState(false);

  useEffect(() => {
    setAddMember(false);
  }, [members]);

  const handleClickAdd = () => {
    setAddMember(true);
  };

  const handleClose = () => {
    onClose(false);
  };

  const handleSubmit = (data) => {
    Modal.confirm({
      title: "เพิ่มข้อมูลสมาชิก",
      content: "ตรวจสอบความถูกต้องแล้ว ต้องการเพิ่มสามชิก?",
      centered: true,
      onOk: () => {
        onSubmit({ ...data, customer_id: members[0].customer_id });
      },
    });
  };

  const handleDelete = (data) => {
    onDelete(data);
  };

  const onFinishFailed = (e) => {
    console.log("Failure", e);
  };

  return (
    <Modal
      title="รายชื่อสมาชิกร้านค้า"
      centered={true}
      // width={1000}
      open={open}
      //   onOk={handleSubmit}
      closeIcon={false}
      onCancel={handleClose}
      footer={[
        <Button key="close" onClick={handleClose}>
          ยกเลิก
        </Button>,
        <Button
          key="submit"
          htmlType="submit"
          type="primary"
          onClick={form.submit}
          disabled={!addMember}
        >
          บันทึก
        </Button>,
      ]}
    >
      <CustomerMemberList data={members} onDelete={handleDelete} />
      {!addMember && (
        <Button type="primary" onClick={handleClickAdd}>
          เพิ่มสมาชิกใหม่
        </Button>
      )}
      {addMember && (
        <div>
          <Form
            id="form"
            onFinish={handleSubmit}
            onFinishFailed={onFinishFailed}
            layout={"vertical"}
            form={form}
          >
            <Form.Item
              name="fullname"
              label="เพิ่มรายชื่อสมาชิก"
              rules={[
                {
                  required: true,
                  message: "ต้องไม่เว้นว่าง",
                },
              ]}
            >
              <Input placeholder="ชื่อสมาชิกใหม่" />
            </Form.Item>
            <Form.Item
              name="phone"
              label="เบอร์โทร"
              rules={[
                {
                  required: true,
                  message: "ต้องไม่เว้นว่าง",
                },
              ]}
            >
              <Input placeholder="เบอร์โทร" />
            </Form.Item>
            <Form.Item name="line" label="ไลน์">
              <Input placeholder="ไลน์" />
            </Form.Item>
          </Form>
        </div>
      )}
    </Modal>
  );
}
