import { Typography } from "antd";
import React from "react";
import { currencyFormatTH } from "../../../utils/numberFormat";

const { Text } = Typography;

export default function SaleItem({ data }) {
  const RenderStatisticsContent = ({ title, data }) => (
    <div
      style={{
        flexDirection: "row",
        justifyContent: "space-between",
        display: "flex",
      }}
    >
      <Text style={{ fontSize: 12 }} type="secondary">
        {title}
      </Text>
      <Text strong style={{ fontSize: 12 }}>
        {data}
      </Text>
    </div>
  );
  return (
    <>
      <Text strong>
        {data.firstname} {data.lastname} ( {data.nickname} )
      </Text>
      <RenderStatisticsContent title={"กลุ่ม: " + data.group_name} data="" />
      <RenderStatisticsContent
        title="เงินสด"
        data={currencyFormatTH(data.cash)}
      />
      <RenderStatisticsContent
        title="เงินโอน"
        data={currencyFormatTH(data.transfer)}
      />
      <hr />
    </>
  );
}
