import moment from "moment";
import React, { useEffect, useState } from "react";
import ReactExport from "react-export-excel";
import { Link } from "react-router-dom";

const ExcelFile = ReactExport.ExcelFile;
const ExcelSheet = ReactExport.ExcelFile.ExcelSheet;
const ExcelColumn = ReactExport.ExcelFile.ExcelColumn;

export default function MaintenanceList({ data }) {
  const [dataSource, setDataSource] = useState([]);

  useEffect(() => {
    mapData();
  }, [data]);

  useEffect(() => {
    console.log(dataSource);
  }, [dataSource]);

  const mapData = () => {
    let arr = [];
    data.map((item) => arr.push(...item.products));
    setDataSource(arr);
  };

  //   const
  return (
    <div style={{ width: "100%", justifyContent: "end", display: "flex" }}>
      <ExcelFile element={<Link>Download</Link>}>
        {/* <ExcelSheet dataSet={multiDataSet} name="Organization" /> */}
        <ExcelSheet
          data={data.filter((item) => item.maintenance_status_id === 1)}
          name="รายการใหม่"
        >
          <ExcelColumn label="เลขที่ใบเสร็จ" value="order_number" />
          <ExcelColumn
            label="วันที่สั่งซื้อ"
            value={(col) => moment(col.datetime).format("DD/MM/YY")}
          />
          <ExcelColumn label="ร้านค้า" value="storename" />
          <ExcelColumn label="ชื่อลูกค้า" value="fullname" />
          <ExcelColumn label="ที่อยู่" value="address" />
          <ExcelColumn label="ถนน" value="road" />
          <ExcelColumn
            label="กรรมการ"
            value={(col) =>
              col.user_name +
              " " +
              col.user_lastname +
              " ( " +
              col.user_nickname +
              " )"
            }
          />
        </ExcelSheet>
        <ExcelSheet
          data={dataSource.filter((item) => item.maintenance_status_id === 1)}
          name="สินค้า (รายการใหม่)"
        >
          <ExcelColumn label="สถานะ" value="order_status" />
          <ExcelColumn label="เลขที่ใบเสร็จ" value="order_number" />
          <ExcelColumn
            label="วันที่สั่งซื้อ"
            value={(col) => moment(col.datetime).format("DD/MM/YY")}
          />
          <ExcelColumn
            label="กรรมการ"
            value={(col) =>
              col.user_name +
              " " +
              col.user_lastname +
              " ( " +
              col.user_nickname +
              " )"
            }
          />
          <ExcelColumn label="ร้านค้า" value="storename" />
          <ExcelColumn label="ชื่อลูกค้า" value="fullname" />
          <ExcelColumn label="ที่อยู่" value="address" />
          <ExcelColumn label="รายการขาย" value="name" />
          <ExcelColumn label="จำนวน" value="amount" />
        </ExcelSheet>
        <ExcelSheet
          data={data.filter((item) => item.maintenance_status_id === 2)}
          name="รอติดตั้ง"
        >
          <ExcelColumn label="เลขที่ใบเสร็จ" value="order_number" />
          <ExcelColumn
            label="วันที่จ่ายงาน"
            value={(col) =>
              moment(col.maintenance_processing_datetime).format("DD/MM/YY")
            }
          />
          <ExcelColumn label="ร้านค้า" value="storename" />
          <ExcelColumn label="ชื่อลูกค้า" value="fullname" />
          <ExcelColumn label="ที่อยู่" value="address" />
          <ExcelColumn label="ถนน" value="road" />
          <ExcelColumn
            label="กรรมการ"
            value={(col) =>
              col.user_name +
              " " +
              col.user_lastname +
              " ( " +
              col.user_nickname +
              " )"
            }
          />
          <ExcelColumn
            label="ผู้ติดตั้ง"
            value={(col) =>
              col.maintenance_name +
              " " +
              col.maintenance_lastname +
              " ( " +
              col.maintenance_nickname +
              " )"
            }
          />
          <ExcelColumn label="หมายเหตุ" value="maintenance_mark" />
        </ExcelSheet>
        <ExcelSheet
          data={dataSource.filter((item) => item.maintenance_status_id === 2)}
          name="สินค้า (รอติดตั้ง)"
        >
          <ExcelColumn label="สถานะ" value="order_status" />
          <ExcelColumn label="เลขที่ใบเสร็จ" value="order_number" />
          <ExcelColumn
            label="วันที่จ่ายงาน"
            value={(col) =>
              moment(col.maintenance_processing_datetime).format("DD/MM/YY")
            }
          />
          <ExcelColumn
            label="กรรมการ"
            value={(col) =>
              col.user_name +
              " " +
              col.user_lastname +
              " ( " +
              col.user_nickname +
              " )"
            }
          />
          <ExcelColumn label="ร้านค้า" value="storename" />
          <ExcelColumn label="ชื่อลูกค้า" value="fullname" />
          <ExcelColumn label="ที่อยู่" value="address" />
          <ExcelColumn label="รายการขาย" value="name" />
          <ExcelColumn label="จำนวน" value="amount" />
        </ExcelSheet>
        <ExcelSheet
          data={data.filter((item) => item.maintenance_status_id === 3)}
          name="ติดตั้งสำเร็จ"
        >
          <ExcelColumn label="เลขที่ใบเสร็จ" value="order_number" />
          <ExcelColumn
            label="วันที่ติดตั้งเสร็จ"
            value={(col) =>
              moment(col.maintenance_finish_datetime).format("DD/MM/YY")
            }
          />
          <ExcelColumn label="ร้านค้า" value="storename" />
          <ExcelColumn label="ชื่อลูกค้า" value="fullname" />
          <ExcelColumn label="ที่อยู่" value="address" />
          <ExcelColumn label="ถนน" value="road" />
          <ExcelColumn
            label="กรรมการ"
            value={(col) =>
              col.user_name +
              " " +
              col.user_lastname +
              " ( " +
              col.user_nickname +
              " )"
            }
          />
          <ExcelColumn
            label="ผู้ติดตั้ง"
            value={(col) =>
              col.maintenance_name +
              " " +
              col.maintenance_lastname +
              " ( " +
              col.maintenance_nickname +
              " )"
            }
          />
          <ExcelColumn label="หมายเหตุ" value="maintenance_mark" />
        </ExcelSheet>
        <ExcelSheet
          data={dataSource.filter((item) => item.maintenance_status_id === 3)}
          name="สินค้า (ติดตั้งแล้ว)"
        >
          <ExcelColumn label="สถานะ" value="order_status" />
          <ExcelColumn label="เลขที่ใบเสร็จ" value="order_number" />
          <ExcelColumn
            label="วันที่ติดตั้งเสร็จ"
            value={(col) =>
              moment(col.maintenance_finish_datetime).format("DD/MM/YY")
            }
          />
          <ExcelColumn
            label="กรรมการ"
            value={(col) =>
              col.user_name +
              " " +
              col.user_lastname +
              " ( " +
              col.user_nickname +
              " )"
            }
          />
          <ExcelColumn label="ร้านค้า" value="storename" />
          <ExcelColumn label="ชื่อลูกค้า" value="fullname" />
          <ExcelColumn label="ที่อยู่" value="address" />
          <ExcelColumn label="รายการขาย" value="name" />
          <ExcelColumn label="จำนวน" value="amount" />
        </ExcelSheet>
      </ExcelFile>
    </div>
  );
}
