import moment from "moment";
import React, { useEffect, useState } from "react";
import ReactExport from "react-export-excel";
import { Link } from "react-router-dom";

const ExcelFile = ReactExport.ExcelFile;
const ExcelSheet = ReactExport.ExcelFile.ExcelSheet;
const ExcelColumn = ReactExport.ExcelFile.ExcelColumn;

export default function DonateListExcel({ data }) {
  // const [dataSource, setDataSource] = useState(data);

  useEffect(() => {
    // mapData();
  }, [data]);

  //   useEffect(() => {
  // console.log(dataSource);
  //   }, [dataSource]);

  // const mapData = () => {
  //   let arr = [];
  //   data.map((item) => arr.push(...item.products));
  //   setDataSource(arr);
  // };

  //   const
  return (
    <div style={{ width: "100%", justifyContent: "end", display: "flex" }}>
      <ExcelFile element={<Link>Download</Link>}>
        {/* <ExcelSheet dataSet={multiDataSet} name="Organization" /> */}
        <ExcelSheet
          data={data.filter((item) => item.order_status_id === 1)}
          name="แบบรวม"
        >
          <ExcelColumn label="เลขที่บิล" value="id" />
          <ExcelColumn label="ช่องทางชำระ" value="payment" />
          <ExcelColumn
            label="วันที่ชำระ"
            value={(col) =>
              moment(col.payment_date).format("DD/MM/YY HH:mm:ss")
            }
          />
          <ExcelColumn
            label="กรรมการ"
            value={(col) =>
              col.user_firstname +
              " " +
              col.user_lastname +
              " ( " +
              col.user_nickname +
              " )"
            }
          />
          <ExcelColumn label="ร้านค้า" value="customer_storename" />
          <ExcelColumn label="ชื่อลูกค้า" value="customer_name" />
          <ExcelColumn label="ที่อยู่" value="customer_address" />
          <ExcelColumn label="เงินบริจาค" value="donate" />
          <ExcelColumn label="หมายเหตุ" value="mark" />
        </ExcelSheet>
        <ExcelSheet
          data={data.filter(
            (item) => item.privilege === 1 && item.order_status_id === 1
          )}
          name="ร่วมเสี่ยงทาย"
        >
          <ExcelColumn label="เลขที่บิล" value="id" />
          <ExcelColumn label="ช่องทางชำระ" value="payment" />
          <ExcelColumn
            label="วันที่ชำระ"
            value={(col) =>
              moment(col.payment_date).format("DD/MM/YY HH:mm:ss")
            }
          />
          <ExcelColumn
            label="กรรมการ"
            value={(col) =>
              col.user_firstname +
              " " +
              col.user_lastname +
              " ( " +
              col.user_nickname +
              " )"
            }
          />
          <ExcelColumn label="ร้านค้า" value="customer_storename" />
          <ExcelColumn label="ชื่อลูกค้า" value="customer_name" />
          <ExcelColumn label="ที่อยู่" value="customer_address" />
          <ExcelColumn label="เงินบริจาค" value="donate" />
          <ExcelColumn label="หมายเหตุ" value="mark" />
        </ExcelSheet>
        <ExcelSheet
          data={data.filter(
            (item) => item.privilege === 0 && item.order_status_id === 1
          )}
          name="ไม่ร่วมเสี่ยงทาย"
        >
          <ExcelColumn label="เลขที่บิล" value="id" />
          <ExcelColumn label="ช่องทางชำระ" value="payment" />
          <ExcelColumn
            label="วันที่ชำระ"
            value={(col) =>
              moment(col.payment_date).format("DD/MM/YY HH:mm:ss")
            }
          />
          <ExcelColumn
            label="กรรมการ"
            value={(col) =>
              col.user_firstname +
              " " +
              col.user_lastname +
              " ( " +
              col.user_nickname +
              " )"
            }
          />
          <ExcelColumn label="ร้านค้า" value="customer_storename" />
          <ExcelColumn label="ชื่อลูกค้า" value="customer_name" />
          <ExcelColumn label="ที่อยู่" value="customer_address" />
          <ExcelColumn label="เงินบริจาค" value="donate" />
          <ExcelColumn label="หมายเหตุ" value="mark" />
        </ExcelSheet>
        <ExcelSheet
          data={data.filter(
            (item) => item.order_status_id === 2 || item.order_status_id === 3
          )}
          name="รายการยกเลิก"
        >
          <ExcelColumn
            label="สถานะ"
            value={(col) =>
              col.order_status_id === 2 ? "รอดำเนินการ" : "ยกเลิกแล้ว"
            }
          />
          <ExcelColumn label="เลขที่บิล" value="id" />
          <ExcelColumn label="ช่องทางชำระ" value="payment" />
          <ExcelColumn
            label="วันที่ชำระ"
            value={(col) =>
              moment(col.payment_date).format("DD/MM/YY HH:mm:ss")
            }
          />
          <ExcelColumn
            label="กรรมการ"
            value={(col) =>
              col.user_firstname +
              " " +
              col.user_lastname +
              " ( " +
              col.user_nickname +
              " )"
            }
          />
          <ExcelColumn label="ร้านค้า" value="customer_storename" />
          <ExcelColumn label="ชื่อลูกค้า" value="customer_name" />
          <ExcelColumn label="ที่อยู่" value="customer_address" />
          <ExcelColumn label="เงินบริจาค" value="donate" />
          <ExcelColumn label="หมายเหตุ" value="mark" />
        </ExcelSheet>
      </ExcelFile>
    </div>
  );
}
