import { Descriptions } from "antd";
import React from "react";

export default function CustomerDetail({ data }) {
  return (
    <div>
      <Descriptions>
        <Descriptions.Item label="ชื่อร้าน">
          {data.customer_storename}
        </Descriptions.Item>
        {data.customer_name && (
          <Descriptions.Item label="ชื่อสกุล">
            {data.customer_name}
          </Descriptions.Item>
        )}
        <Descriptions.Item label="โทรศัพท์">
          {data.customer_phone}
        </Descriptions.Item>
        {/* {data.line && (
          <Descriptions.Item label="email">{data.line}</Descriptions.Item>
        )} */}
        {data.customer_address && (
          <Descriptions.Item label="ที่อยู่">
            {data.customer_address}
          </Descriptions.Item>
        )}
      </Descriptions>
      {/* <Divider /> */}
    </div>
  );
}
