import { Modal, Button, Typography, Divider, List, Image, Input } from "antd";
import React, { useEffect, useState } from "react";
import ProductItem from "./ProductItem";
import CustomerDetail from "../order/CustomerDetail";
import moment from "moment";
// import { useSelector } from "react-redux";

const { Text } = Typography;
export default function ConfirmCancelOrderModal({
  open,
  data,
  onclose,
  onCancelConfirm,
}) {
  //   const [mark, setMark] = useState("");

  const handleClose = () => {
    onclose(false);
  };

  const handleCancelOrder = () => {
    const status = {
      ...data,
      order_status_id: 3,
      cancel_at: moment().format("YYYY-MM-DD"),
    };
    onCancelConfirm(status);
  };
  return (
    <Modal
      title="รายละเอียด"
      centered={true}
      // width={1000}
      open={open}
      //   onOk={handleSubmit}
      closeIcon={false}
      onCancel={handleClose}
      footer={[
        data.order_status_id === 2 && (
          <Button
            danger
            type="primary"
            key="remove"
            onClick={handleCancelOrder}
          >
            ยืนยันรายการยกเลิก
          </Button>
        ),

        <Button key="close" onClick={handleClose}>
          ปิด
        </Button>,
      ]}
    >
      <>
        <Divider />
        <CustomerDetail data={data} />
        <List
          itemLayout="horizontal"
          dataSource={data.products}
          renderItem={(item, index) => <ProductItem key={index} data={item} />}
        />
        <hr />
        <Text strong type="danger">
          หมายเหตุ: {data.mark}
        </Text>
        <hr />
        <Text>
          ช่องทางชำระ: {data.payment_by_id === 1 ? "เงินสด" : "โอนเข้าบัญชี"}
        </Text>
        {data.payment_by_id === 2 && (
          <div
            style={{
              marginTop: "24px",
              justifyContent: "center",
              display: "flex",
            }}
          >
            {/* <img src={data.payment_img} alt="payment" /> */}
            <Image width={100} src={data.payment_img} />
          </div>
        )}
      </>
      {/* <hr /> */}
      {/* <Input
        style={{
          marginTop: "24px",
        }}
        placeholder="หมายเหตุ เพิ่มเติม"
        onChange={(e) => setMark(e.target.value)}
      /> */}
    </Modal>
  );
}
