import React, { useEffect, useState } from "react";
import { Modal, Button, Typography, Divider } from "antd";
import dayjs from "dayjs";
import customParseFormat from "dayjs/plugin/customParseFormat";
import moment from "moment";
import { useDispatch, useSelector } from "react-redux";
dayjs.extend(customParseFormat);
const { Text } = Typography;

export default function AuctionListDetailModal({
  open,
  data,
  onSubmit,
  onClose,
}) {
  const user = useSelector((state) => state.token);

  useEffect(() => {
    // console.log("DATA", data);
  }, [data]);

  const handleClose = () => {
    onClose(false);
  };

  const handleSubmit = () => {
    onSubmit(data);
  };

  const renderList = (item, index) => {
    return (
      <div
        key={index}
        style={{
          flexDirection: "row",
          justifyContent: "space-between",
          display: "flex",
        }}
      >
        <Text>{item.product_productName}</Text>
        <Text>{item.product_productAmount}</Text>
      </div>
    );
  };

  return (
    <Modal
      title="รายละเอียด"
      centered={true}
      open={open}
      onOk={handleSubmit}
      closeIcon={false}
      footer={[
        // <Button key="receipt" onClick={handleDownloadReceipt}>
        //   พิมพ์ใบเสร็จ
        // </Button>,
        // <Button
        //   disabled={!imgFile && data.payment_by_id === 2}
        //   key="submit"
        //   type="primary"
        //   onClick={handleSubmit}
        // >
        //   ยืนยันการชำระเงิน
        // </Button>,
        <Button key="close" onClick={handleClose}>
          ปิด
        </Button>,
      ]}
    >
      <Divider />
      <div
        style={{
          flexDirection: "row",
          justifyContent: "space-between",
          display: "flex",
        }}
      >
        <Text strong>รายการ</Text>
        <Text strong>จำนวน</Text>
      </div>
      {data?.map((item, index) => renderList(item, index))}
      <Divider />
    </Modal>
  );
}
