import moment from "moment";
import React, { useEffect, useState } from "react";
import ReactExport from "react-export-excel";
import { Link } from "react-router-dom";
import "moment/locale/th";

const ExcelFile = ReactExport.ExcelFile;
const ExcelSheet = ReactExport.ExcelFile.ExcelSheet;
const ExcelColumn = ReactExport.ExcelFile.ExcelColumn;

export default function EligiblePersonExcel({ data }) {
  useEffect(() => {
    // mapData();
  }, [data]);

  return (
    <div style={{ width: "100%", justifyContent: "end", display: "flex" }}>
      <ExcelFile element={<Link>Download</Link>}>
        {/* <ExcelSheet dataSet={multiDataSet} name="Organization" /> */}
        <ExcelSheet
          data={data.filter((item) => item.code === null)}
          name="มีสิทธิ์เสี่ยงทาย"
        >
          <ExcelColumn label="เลขที่บิล" value="id" />
          <ExcelColumn label="ชื่อ-สกุล" value="fullname" />
          <ExcelColumn label="ร้านค้า" value="storename" />
          <ExcelColumn label="ที่อยู่" value="address" />
          <ExcelColumn label="โทรศัพท์" value="phone" />
          <ExcelColumn label="โทรศัพท์(หน้าบิล)" value="phone2" />
          <ExcelColumn label="เงินบริจาค" value="donate" />
          <ExcelColumn label="หมายเหตุ" value="mark" />
        </ExcelSheet>
        <ExcelSheet
          data={data.filter((item) => item.code !== null)}
          name="ไม่มีสิทธิ์เสี่ยงทาย"
        >
          <ExcelColumn label="เลขที่บิล" value="id" />
          <ExcelColumn label="ชื่อ-สกุล" value="fullname" />
          <ExcelColumn label="ร้านค้า" value="storename" />
          <ExcelColumn label="ที่อยู่" value="address" />
          <ExcelColumn label="โทรศัพท์" value="phone" />
          <ExcelColumn label="โทรศัพท์(หน้าบิล)" value="phone2" />
          <ExcelColumn label="เงินบริจาค" value="donate" />
          <ExcelColumn label="หมายเหตุ" value="mark" />
          <ExcelColumn label="อดีตคณะกรรมการ รหัส" value="code" />
          {/* <ExcelColumn
            label="อดีตคณะกรรมการ รหัส"
            value={(col) =>
              moment(col.association_year).add(543, "years").format("YYYY")
            }
          /> */}
        </ExcelSheet>
      </ExcelFile>
    </div>
  );
}
