import React, { useEffect, useState } from "react";
import { Modal, Button, Typography, Divider, Space, List, Input } from "antd";

import ProductSelectItem from "./ProductSelectItem";
const { Text } = Typography;

export default function FinishJobModal({
  open,
  data,
  onClose,
  onSubmit,
  onPrint,
}) {
  const [dataCheckBox, setDataCheckBox] = useState([]);
  const [mark, setMark] = useState(false);

  const handleClose = () => {
    // setDataCheckBox([]);
    onClose(false);
  };

  useEffect(() => {
    setDataCheckBox(data?.products);
    setMark(data.delivery_mark);
  }, [data, open]);

  const handlePrint = () => {
    const dataPrint = {
      ...data,
      delivery_mark: mark,
      products: dataCheckBox.filter(
        (item) => item.order_product_delivery_id === 2
      ),
    };
    onPrint(dataPrint);
  };

  const handleSubmit = () => {
    // const arrProduct = dataCheckBox.filter(
    //   (item) => item.order_product_delivery_id === 2
    // );

    // console.log("ARRAY", arrProduct);

    const newProductList = dataCheckBox.map((product) => {
      if (product.order_product_delivery_id === 1) {
        return {
          order_id: product.id,
          product_id: product.productId,
          amount: product.amount,
          order_product_delivery_id: 1,
        };
      } else
        return {
          order_id: product.id,
          product_id: product.productId,
          amount: product.amount,
          order_product_delivery_id: 3,
        };
    });

    const productCount = newProductList.filter(
      (item) => item.order_product_delivery_id === 3
    );

    let status = 0;
    if (dataCheckBox?.length === productCount?.length) status = 3;
    else status = 2;

    const newData = {
      id: data.id,
      delivery_mark: mark,
      delivery_status_id: status,
      products: newProductList,
      // maintenance_img: imgFile,
    };
    // console.log("onSubmit", newData);

    onSubmit(newData);
  };

  const handleSelectItem = (checked, data) => {
    // console.log("onSubmit", dataCheckBox);
    // let newArr = [...dataCheckBox];
    // newArr["productId"] = data.productId;

    const updateList = dataCheckBox?.map((item) => {
      if (item.productId === data.productId) {
        return { ...item, ...data, order_product_delivery_id: checked ? 2 : 1 };
      } else {
        return { ...item };
      }
      // return item;
    });

    // console.log("Updated:", updateList);
    setDataCheckBox(updateList);

    // setDataCheckBox(newArr);

    // setDataCheckBox((pre) => [
    //   ...pre,
    //   { ...data, delivery_status_id: checked ? 2 : 1 },
    // ]);

    // setDataCheckBox((pre) => [...pre, {...data , delivery_status_id: checked ? 2 : 1}]);

    // console.log("Selected: " + cehcked, data);
  };

  return (
    <Modal
      destroyOnClose={true}
      title="เลือกรายการจัดส่ง"
      centered={true}
      open={open}
      onOk={handleSubmit}
      closeIcon={false}
      footer={[
        <Button key="receipt" onClick={handlePrint}>
          พิมพ์ใบสั่งซื้อ
        </Button>,
        <Button
          // disabled={value}
          key="submit"
          type="primary"
          onClick={handleSubmit}
        >
          ยืนยันการจัดส่ง
        </Button>,
        <Button key="close" onClick={handleClose}>
          ปิด
        </Button>,
      ]}
    >
      <div>
        <Space direction="vertical">
          <Text strong>ชื่อลูกค้า :{data?.storename}</Text>
          <Text strong>โทร : {data.phone}</Text>
        </Space>

        <Divider />

        <List
          itemLayout="horizontal"
          dataSource={data.products}
          renderItem={(item, index) => (
            <ProductSelectItem
              key={index}
              data={item}
              onSelectItem={handleSelectItem}
            />
          )}
        />

        <Divider />
        <Space direction="vertical">
          <Input
            defaultValue={data.delivery_mark}
            placeholder="หมายเหตุ (ถ้ามี)"
            onChange={(e) => setMark(e.target.value)}
          />
          <Text strong type="danger" style={{ fontSize: 12 }}>
            เลือกสินค้าที่ต้องการจัดส่ง และกด "พิมพ์ใบสั่งซื้อ" ก่อนกด
            "ยืนยันการจัดส่ง" หากรายการไหนยืนยันการจัดส่งแล้ว
            จะไม่สามารถพิมพ์ใบสั่งซื้อรายการนั้นได้อีก
          </Text>
        </Space>
      </div>
    </Modal>
  );
}
