import React, { useState } from "react";
import { Button, Modal, Form, Input, DatePicker, Divider, List } from "antd";

export default function AddYearModal({ open, data, onClose, onSubmit }) {
  const [form] = Form.useForm();
  const [year, setYear] = useState(0);
  const handleClose = () => {
    onClose(false);
  };
  const handleSubmit = () => {
    onSubmit(year);
  };

  const onFinishFailed = (e) => {
    console.log("Failure", e);
  };

  const onChange = (date, dateString) => {
    console.log(date, dateString);
    setYear(dateString);
  };

  return (
    <Modal
      title="เพิ่มปีที่เข้าถึงข้อมูล"
      centered={true}
      // width={1000}
      open={open}
      //   onOk={handleSubmit}
      closeIcon={false}
      onCancel={handleClose}
      footer={[
        <Button key="close" onClick={handleClose}>
          ยกเลิก
        </Button>,
        <Button
          key="submit"
          htmlType="submit"
          type="primary"
          onClick={form.submit}
        >
          บันทึก
        </Button>,
      ]}
    >
      <Form
        id="form"
        onFinish={handleSubmit}
        onFinishFailed={onFinishFailed}
        layout={"vertical"}
        form={form}
      >
        <Divider orientation="left">ปีทั้งหมด</Divider>
        <List
          size="small"
          pagination={{
            onChange: (page) => {
              console.log(page);
            },
            pageSize: 5,
          }}
          // header={<div>ปี</div>}
          //   footer={<div>Footer</div>}
          // bordered
          dataSource={data}
          renderItem={(item) => <List.Item>{item.years}</List.Item>}
        />
        <Form.Item name="years" label="ปีที่เข้าถึงข้อมูล">
          <DatePicker
            style={{ width: "100%" }}
            onChange={onChange}
            picker="year"
          />
        </Form.Item>
      </Form>

      {/* {data.map((item) => (
        <p>{item.years}</p>
      ))} */}
    </Modal>
  );
}
