import React from "react";
import { Routes, Route } from "react-router-dom";
import Dashboard from "../pages/dashboard/Main";
import OrderProducts from "../pages/order/Main";
import Products from "../pages/products/Main";
import Users from "../pages/users/Main";
import OrderHistory from "../pages/history/Main";
import Customers from "../pages/customer/Main";
// import CustomerMembers from "../pages/customer_members/Main";
// import Receipt from "../pages/history/receipt/ReceiptPDF";
import Myorder from "../pages/myorder/Main";
import MyOrderReceipt from "../pages/myorder/Receipt";
import Maintenance from "../pages/maintenance/Main";
import Delivery from "../pages/delivery/Main";
import ShippingAddress from "../pages/delivery/ShippingAddress";
import TicketConfig from "../pages/ticket_config/Main";
import ShrineEvent from "../pages/shrine_event/Main";
// import ShrineEventList from "../pages/shrine_event_list/Main";
import Toijee from "../pages/toijee/Main";
import ToijeeList from "../pages/toijee_donate_list/Main";
import ToijeeReceipt from "../pages/toijee_donate_list/Receipt";
import AssociationMembers from "../pages/association_members/Main";

import EditOrChangeOrder from "../pages/order/edit_change_orders/Main";
import { useSelector } from "react-redux";

export default function Contents() {
  const user = useSelector((state) => state.token);
  if (user.role === "admin") {
    return (
      <Routes>
        <Route path="/*" element={<Dashboard />} />
        <Route path="/orders" element={<OrderProducts />} />
        <Route path="/orders/edit" element={<EditOrChangeOrder />} />
        <Route path="/myorders" element={<Myorder />} />
        <Route path="/myorder/receipt" element={<MyOrderReceipt />} />
        <Route path="/users" element={<Users />} />
        <Route path="/products" element={<Products />} />
        <Route path="/history" element={<OrderHistory />} />
        {/* <Route path="/history/receipt-pdf" element={<Receipt />} /> */}
        <Route path="/customers" element={<Customers />} />
        {/* <Route path="/customer_members" element={<CustomerMembers />} /> */}
        <Route path="/maintenance" element={<Maintenance />} />
        <Route path="/delivery" element={<Delivery />} />
        <Route path="/delivery/shipping" element={<ShippingAddress />} />
        <Route path="/ticket-config" element={<TicketConfig />} />
        <Route path="/toi-jee" element={<Toijee />} />
        <Route path="/toi-jee-list" element={<ToijeeList />} />
        <Route path="/toi-jee-list/receipt" element={<ToijeeReceipt />} />
        <Route path="/shrine-event" element={<ShrineEvent />} />
        <Route path="/association-members" element={<AssociationMembers />} />
        {/* <Route path="/shrine-event-list" element={<ShrineEventList />} /> */}
      </Routes>
    );
  } else if (user.role === "editor") {
    return (
      <Routes>
        <Route path="/*" element={<Dashboard />} />
        <Route path="/products" element={<Products />} />
        <Route path="/history" element={<OrderHistory />} />
        <Route path="/customers" element={<Customers />} />
        {/* <Route path="/customer_members" element={<CustomerMembers />} /> */}
        {/* <Route path="/history/receipt-pdf" element={<Receipt />} /> */}
        <Route path="/maintenance" element={<Maintenance />} />
        <Route path="/myorder/receipt" element={<MyOrderReceipt />} />
        <Route path="/ticket-config" element={<TicketConfig />} />
        <Route path="/toi-jee" element={<Toijee />} />
        <Route path="/toi-jee-list" element={<ToijeeList />} />
        <Route path="/toi-jee-list/receipt" element={<ToijeeReceipt />} />
        <Route path="/shrine-event" element={<ShrineEvent />} />
        <Route path="/association-members" element={<AssociationMembers />} />
        {/* <Route path="/shrine-event-list" element={<ShrineEventList />} /> */}
      </Routes>
    );
  } else if (user.role === "seller") {
    return (
      <Routes>
        <Route path="/*" element={<Dashboard />} />
        <Route path="/orders" element={<OrderProducts />} />
        <Route path="/orders/edit" element={<EditOrChangeOrder />} />
        <Route path="/myorders" element={<Myorder />} />
        <Route path="/myorder/receipt" element={<MyOrderReceipt />} />
        <Route path="/customers" element={<Customers />} />
        {/* <Route path="/receipt" element={<Receipt />} /> */}
        <Route path="/toi-jee" element={<Toijee />} />
        <Route path="/toi-jee-list" element={<ToijeeList />} />
        <Route path="/toi-jee-list/receipt" element={<ToijeeReceipt />} />
        {/* <Route path="/ticket-config" element={<TicketConfig />} /> */}
      </Routes>
    );
  } else if (user.role === "maintenance") {
    return (
      <Routes>
        <Route path="/*" element={<Maintenance />} />
      </Routes>
    );
  } else if (user.role === "shipper") {
    return (
      <Routes>
        <Route path="/*" element={<Delivery />} />
        <Route path="/delivery/shipping" element={<ShippingAddress />} />
      </Routes>
    );
  }

  return false;
}
