import { Select, Space } from "antd";
import React, { useEffect, useState } from "react";
import baseAPI from "../../api/baseAPI";
import { useSelector } from "react-redux";

export default function UserListSelect({ onSelected }) {
  const user = useSelector((state) => state.token);
  const [userListHolders, setUserListHolders] = useState([]);
  const [userListShow, setUserListShow] = useState([]);
  const [groupList, setGroupList] = useState([]);
  const [groupSelected, setGroupSelected] = useState(0);

  useEffect(() => {
    if (groupSelected === 0) {
      fetchUsersList();
    } else {
      const sortUsersByGroup = userListHolders.filter(
        (user) => user.groupId === groupSelected
      );
      setUserListShow(sortUsersByGroup);
    }
  }, [groupSelected]);

  useEffect(() => {
    fetchUsersList();
    fetchGroupList();
  }, []);

  const fetchGroupList = async () => {
    const result = await baseAPI.get(`/city_pillar_shrine/group`, {
      headers: {
        "x-access-token": user.token,
      },
    });
    setGroupList(result.data);
  };

  const fetchUsersList = async () => {
    const result = await baseAPI.get(`/city_pillar_shrine/users`, {
      headers: {
        "x-access-token": user.token,
      },
    });
    setUserListShow(result.data);
    setUserListHolders(result.data);
  };

  const onGroupSelected = (data) => {
    setGroupSelected(data);
  };

  const handleUserSelect = (val, item) => {
    // console.log(val, item);
    onSelected(item.item);
  };

  return (
    <div style={{ marginTop: "16px", width: "100%" }}>
      <Space
        direction="vertical"
        style={{
          width: "100%",
        }}
      >
        <Select
          defaultValue={"ทั้งหมด"}
          placeholder="ชื่อกลุ่ม"
          style={{
            width: "100%",
          }}
          onChange={onGroupSelected}
          // loading
          options={groupList.map((item) => ({
            value: item.id,
            label: item.name,
          }))}
        />
        <Select
          placeholder="ชื่อกรรมการ"
          style={{
            width: "100%",
          }}
          onChange={(val, item) => handleUserSelect(val, item)}
          // loading
          options={userListShow.map((item) => ({
            value: item.id,
            label: item.firstname + " " + item.lastname,
            item: item,
          }))}
        />
      </Space>
    </div>
  );
}
