import React, { useEffect, useState } from "react";
import { Button, InputNumber, Radio, Space, Typography } from "antd";

import { CheckOutlined } from "@ant-design/icons";
import OrderDetailList from "./OrderDetailList";
import CustomerDetail from "./CustomerDetail";
import { currencyFormatTH } from "../../../utils/numberFormat";
import moment from "moment/moment";
import ConfirmOrderModal from "./ConfirmOrderModal";
import { useSelector } from "react-redux";

// import { useDispatch } from "react-redux";
// import { addOrder } from "../../../redux/reduxSlice";

const { Text } = Typography;

export default function OrderDetail({
  products,
  customer,
  orderType = [],
  donate = {},
  onSubmit,
}) {
  const user = useSelector((state) => state.token);
  const [openModalConfirm, setOpenModalConfirm] = useState(false);
  const [orderCreate, setOrderCreate] = useState({});
  const [orderProduct, setOrderPorduct] = useState(products);
  const [paymentChannel, setPaymentChannel] = useState(1);
  const [orderTypeSelect, setOrderTypeSelect] = useState(
    orderType[0]?.id || null
  );
  const [amount, setAmount] = useState(0);

  const sum = products.reduce((accumulator, object) => {
    const total = object.price * object.amount;
    return accumulator + total;
  }, 0);

  useEffect(() => {
    setOrderPorduct(products);
  }, [products]);

  useEffect(() => {
    // console.log("DONATE", donate);
  }, [donate]);

  const handleClick = (e) => {
    // console.log();
    const createOrder = {
      order_number: moment().format("YYMMDDhhmmss"),
      ...donate,
      // datetime: moment().format(),
      total_price: sum + (donate?.donate || 0),
      products: [...orderProduct],
      // customer: customer,
      customer_id: customer.id,
      payment_by_id: paymentChannel,
      user_id: user.id,
      order_type_id: orderTypeSelect,
    };

    setOrderCreate(createOrder);
    // onSubmit(createOrder);
    // console.log(e);
    setOpenModalConfirm(true);
    // }
  };

  const handleSubmitConfirm = async (data) => {
    // console.log(data);
    onSubmit(data);
    setOpenModalConfirm(false);
  };

  const onChangePaymentType = (event) => {
    setPaymentChannel(event.target.value);
  };

  const onChangeOrderType = (event) => {
    setOrderTypeSelect(event.target.value);

    // console.log(event.target.value);
  };

  const handleChangeAmount = (event) => {
    setAmount(event);
  };

  return (
    <div>
      <CustomerDetail data={customer} />
      <h4>รายการซื้อ {orderProduct.length} รายการ</h4>
      <OrderDetailList data={orderProduct} />

      {donate.donate ? (
        <div>
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              marginTop: "16px",
              marginBottom: "16px",
            }}
          >
            <Space direction="vertical">
              <Text strong>เงินบริจาค</Text>
            </Space>

            <Text strong> {currencyFormatTH(donate.donate)}</Text>
          </div>

          <hr />
        </div>
      ) : null}
      <div
        style={{
          alignItems: "end",
          // justifyContent: "end",
          display: "flex",
          flexDirection: "column",
        }}
      >
        <Text strong>รวม {currencyFormatTH(sum + (donate.donate || 0))}</Text>
        {paymentChannel === 1 && amount > 0 && (
          <>
            <Text strong>เงินสด {currencyFormatTH(amount)}</Text>
            <Text strong>
              ทอน {currencyFormatTH(amount - (sum + (donate.donate || 0)))}
            </Text>
          </>
        )}
      </div>

      <hr />
      {orderProduct.length !== 0 || donate.donate !== 0 ? (
        <div>
          <h4>ช่องทางชำระ</h4>
          <Radio.Group onChange={onChangePaymentType} value={paymentChannel}>
            <Space direction="vertical">
              <div
                style={{
                  flexDirection: "row",
                  alignItems: "center",
                  display: "flex",
                  justifyContent: "space-between",
                }}
              >
                <Radio value={1}>เงินสด</Radio>
                <InputNumber
                  style={{ width: 150 }}
                  placeholder="ใส่จำนวนเงินรับ"
                  formatter={(value) =>
                    `${value}`.replace(/\B(?=(\d{3})+(?!\d))/g, ",")
                  }
                  onChange={handleChangeAmount}
                />
              </div>

              <Radio value={2}>โอนเข้าบัญชี</Radio>
              {/* <Radio value={3}>ชำระภายหลัง</Radio> */}
            </Space>
          </Radio.Group>
          <hr />

          {orderType.length > 0 && (
            <>
              <h4>ประเภทบิล</h4>
              <Radio.Group onChange={onChangeOrderType} value={orderTypeSelect}>
                <Space direction="vertical">
                  {orderType?.map((item) => (
                    <Radio key={item.id} value={item.id}>
                      {item.name}
                    </Radio>
                  ))}
                </Space>
              </Radio.Group>
            </>
          )}

          <div
            style={{
              marginTop: "36px",
              justifyContent: "center",
              display: "flex",
            }}
          >
            <Button
              type="primary"
              key="confirm"
              onClick={handleClick}
              icon={<CheckOutlined />}
            >
              ยืนยันคำสั่งซื้อ
            </Button>
          </div>
        </div>
      ) : null}
      <ConfirmOrderModal
        open={openModalConfirm}
        orderTypeSelect={orderType.filter(
          (item) => item.id === orderCreate.order_type_id
        )}
        onSubmit={handleSubmitConfirm}
        onClose={setOpenModalConfirm}
        data={orderCreate}
      />
    </div>
  );
}
