import React, { useCallback, useEffect, useRef, useState } from "react";
import {
  Card,
  DatePicker,
  Divider,
  Modal,
  Radio,
  Space,
  Typography,
} from "antd";
import moment from "moment/moment";
import "moment/locale/th";
import { toPng } from "html-to-image";
import baseAPI from "../../../api/baseAPI";
import { currencyFormatTH } from "../../../utils/numberFormat";
import EChart from "./EChart";
import { Link, useNavigate } from "react-router-dom";
import OrderListModal from "./OrderListModal";
import SaleList from "./SaleList";
import { useDispatch, useSelector } from "react-redux";
import Loading from "../../../utils/Loading";
import { addToken } from "../../../redux/reduxSlice";
import PaymentUserList from "./report/PaymentUserList";
import EChartToiJee from "./EChartToiJee";

const { RangePicker } = DatePicker;
const { Text } = Typography;

export default function ToiJeeDashboard() {
  const user = useSelector((state) => state.token);
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const [dataList, setDataList] = useState([]);
  const [userList, setUserList] = useState([]);
  const [openOrderModal, setOpenOrderModal] = useState(false);
  const [paymentStatus, setPaymentStatus] = useState(0);
  const [dateSelected, setDateSelected] = useState(null);
  const [eChart, setEchart] = useState([]);

  const [loading, setLoading] = useState(false);
  const currentDate = moment().format("YYYY-MM-DD");

  useEffect(() => {
    let params = {
      dateStart: moment().add(-7, "days").format("YYYY-MM-DD"),
      dateEnd: currentDate,
    };
    fetchDataToday(currentDate);
    fetchToiJeeListByUsers(currentDate);
    fetchSumPriceWeek(params);
  }, []);

  useEffect(() => {
    if (dateSelected) {
      fetchDataToday(dateSelected);
      fetchToiJeeListByUsers(dateSelected);
    }
  }, [dateSelected]);

  const fetchDataToday = async (date) => {
    console.log(date);
    setLoading(true);
    await baseAPI
      .get(`/city_pillar_shrine/toi-jee/dashboard/${date}`, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((res) => {
        console.log(res.data);
        setDataList(res.data);
        setLoading(false);
      })
      .catch((error) => {
        // dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
  };

  const fetchSumPriceWeek = async (params) => {
    console.log(params);
    const result = await baseAPI.get(
      "/city_pillar_shrine/dashboard/toi-jee/sumprice",
      {
        params,
        headers: {
          "x-access-token": user.token,
        },
      }
    );
    console.log(result.data);
    setEchart(result.data);
  };

  const fetchToiJeeListByUsers = async (date) => {
    setLoading(true);
    await baseAPI
      .get(`/city_pillar_shrine/dashboard/toi-jee/user-amount/${date}`, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((res) => {
        setUserList(res.data);
        setLoading(false);
      })
      .catch(() => {
        // dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
  };

  const orderComplete = dataList.reduce((accumulator, object) => {
    let total = 0;
    if (object.order_status_id === 1) {
      total = total + 1;
    }
    return accumulator + total;
  }, 0);

  const sumPriceAll = dataList.reduce((accumulator, object) => {
    let total = 0;
    if (object.order_status_id === 1) {
      total = object.donate;
    }
    return accumulator + total;
  }, 0);

  // const sumDonate = dataList.reduce((accumulator, object) => {
  //   let total = 0;
  //   if (object.order_status_id === 1) {
  //     total = object.donate;
  //   }
  //   return accumulator + total;
  // }, 0);

  const sumPrivilege = dataList.reduce((accumulator, object) => {
    let total = 0;
    if (object.order_status_id === 1 && object.payment_by_id === 1) {
      total = object.donate;
    }
    return accumulator + total;
  }, 0);

  const sumNotPrivilege = dataList.reduce((accumulator, object) => {
    let total = 0;
    if (object.order_status_id === 1 && object.payment_by_id === 2) {
      total = object.donate;
    }
    return accumulator + total;
  }, 0);

  const handleOpenOrderModal = (value) => {
    setPaymentStatus(value);
    setOpenOrderModal(true);
  };

  const onChange = (date, dateString) => {
    setDateSelected(dateString);
    console.log("DATE", dateString);
  };

  const handleChangeDate = (date, dateString) => {
    // console.log(date, dateString);
    let params = {
      dateStart: dateString[0],
      dateEnd: dateString[1],
    };
    fetchSumPriceWeek(params);

    // let url = "";
  };

  const RenderStatisticsHeader = ({ title, data }) => (
    <div
      style={{
        flexDirection: "row",
        justifyContent: "space-between",
        display: "flex",
      }}
    >
      <Text strong type="secondary">
        {title}
      </Text>
      <Text strong>{data}</Text>
    </div>
  );

  const RenderStatisticsContent = ({ title, data }) => (
    <div
      style={{
        flexDirection: "row",
        justifyContent: "space-between",
        display: "flex",
      }}
    >
      <Text style={{ fontSize: 12 }} type="secondary">
        {title}
      </Text>
      <Text style={{ fontSize: 12 }} type="secondary">
        {data}
      </Text>
    </div>
  );

  return (
    <>
      <Text>วันที่แสดงแผนภูมิ</Text>
      <Space direction="vertical" style={{ width: "100%" }}>
        <RangePicker
          style={{ width: "100%", marginTop: "16px" }}
          onChange={handleChangeDate}
        />
        <EChartToiJee data={eChart} />
      </Space>
      <Divider />
      <DatePicker
        placeholder="เลือกวันที่"
        style={{ width: "100%" }}
        onChange={onChange}
      />

      <Space direction="vertical" style={{ width: "100%" }}>
        <Card
          title={
            "ยอดวันที่ " + moment(dateSelected || currentDate).format("LL")
          }
          bordered={false}
        >
          <RenderStatisticsHeader
            title="จำนวนรายการ"
            data={orderComplete + " รายการ"}
          />
          <RenderStatisticsHeader
            title="ยอดบริจาคทั้งหมด"
            data={currencyFormatTH(sumPriceAll)}
          />
          {/* <Divider /> */}
          <div>
            <RenderStatisticsContent
              title="เงินสด"
              data={currencyFormatTH(sumPrivilege)}
            />

            <RenderStatisticsContent
              title="เงินโอน"
              data={currencyFormatTH(sumNotPrivilege)}
            />

            <div style={{ justifyContent: "center", display: "flex" }}>
              <Link
                onClick={() => {
                  handleOpenOrderModal(2);
                }}
              >
                ดูรายละเอียด
              </Link>
            </div>
          </div>
        </Card>
        <Card>
          <PaymentUserList data={userList} />
          <SaleList data={userList} />
        </Card>
      </Space>
      <OrderListModal
        type={2}
        data={dataList}
        open={openOrderModal}
        paymentStatus={paymentStatus}
        onClose={setOpenOrderModal}
      />
    </>
  );
}
