import { List, Tag, Typography } from "antd";
import moment from "moment";
import React from "react";
import { Link } from "react-router-dom";
import { currencyFormat } from "../../../utils/numberFormat";

const { Text } = Typography;

export default function DonateItem({ data, onClickPrint, onClickItem }) {
  const handleClick = () => {
    onClickPrint(data);
  };

  const listItem1 = [
    // <Link onClick={handlePrintAddress}>ใบปะหน้า</Link>,
    <Link onClick={handleClick}>พิมพใบเสร็จ</Link>,
  ];

  const listItem2 = [
    <Tag color="processing">ยกเลิก (รออนุมัติ)</Tag>,
    // <Link onClick={handleClick}>รายละเอียด</Link>,
  ];

  const listItem3 = [
    <Tag color="error">ยกเลิกแล้ว </Tag>,
    // <Link onClick={handleClick}>รายละเอียด</Link>,
  ];
  return (
    <List.Item
      actions={
        data.order_status_id === 1
          ? listItem1
          : data.order_status_id === 2
          ? listItem2
          : listItem3
      }
    >
      <List.Item.Meta
        onClick={() => {
          onClickItem(data);
        }}
        // avatar={
        //   <Avatar
        //     src={`https://xsgames.co/randomusers/avatar.php?g=pixel&key=${1}`}
        //   />
        // }
        title={
          <div style={{ flexDirection: "column", display: "flex" }}>
            <Text>{data?.customer_storename}</Text>
            <Text type="secondary">{data.customer_phone}</Text>
          </div>
        }
        description={
          <div style={{ flexDirection: "column", display: "flex" }}>
            <Text strong>บริจาค {currencyFormat(data?.donate)} บาท</Text>
            <Text strong>{data.payment}</Text>
            <Text type="secondary">
              กรรมการ {data?.user_firstname} {data.user_lastname}
            </Text>
          </div>
        }
      />
    </List.Item>
  );
}
