import React from "react";
import { Table, Typography } from "antd";

const { Text } = Typography;

const columns = [
  {
    title: "รหัส",
    dataIndex: "code",
    key: "code",
  },
  {
    title: "ชื่อร้าน, ชื่อสมาชิก",
    // dataIndex: "fullname",
    key: "fullname",
    render: (record) => {
      return (
        <div style={{ flexDirection: "column", display: "flex" }}>
          <Text>ร้าน {record.storename}</Text>
          <Text type="secondary">คุณ {record.fullname}</Text>
        </div>
      );
    },
  },
  {
    title: "โทรศัพท์",
    dataIndex: "phone",
    key: "phone",
  },
];

export default function AssociationTable({ data }) {
  return <Table dataSource={data} columns={columns} />;
}
