import React, { useEffect, useState } from "react";
import { Button, Modal, Form, Input, Select, Table, Switch } from "antd";
// import { useSelector, useDispatch } from "react-redux";

const role = [
  {
    value: 1,
    label: "ผู้ดูแลระบบ",
  },
  {
    value: 2,
    label: "ผู้แก้ไข",
  },
  {
    value: 3,
    label: "ผู้ขาย",
  },
  {
    value: 4,
    label: "ผู้ติดตั้ง",
  },
  {
    value: 5,
    label: "ผู้จัดส่งสินค้า",
  },
];

const columns = [
  {
    title: "ปีที่มีสิทธิ์เข้าถึงข้อมูล",
    dataIndex: "years",
  },
];

export default function EditUserModal({
  open,
  data,
  groups,
  roleYears,
  onClose,
  onSubmit,
  onDelete,
}) {
  // const user = useSelector((state) => state.token);
  const [form] = Form.useForm();
  const [selectedRowKeys, setSelectedRowKeys] = useState([]);
  const [rows, setRows] = useState([]);

  useEffect(() => {
    const newRows =
      roleYears?.map((item) => ({
        key: item?.years, // Optional chaining here in case item is null or undefined
        years: item?.years, // Optional chaining here as well
      })) ?? [];
    setRows(newRows);
  }, [roleYears]);

  useEffect(() => {
    if (data.role_year) {
      const arrayData = JSON.parse(data.role_year);
      setSelectedRowKeys(arrayData);
    } else {
      setSelectedRowKeys([]);
    }
  }, [data]);

  const onSelectChange = (newSelectedRowKeys) => {
    // console.log("selectedRowKeys changed: ", newSelectedRowKeys);
    setSelectedRowKeys(newSelectedRowKeys);
  };
  const rowSelection = {
    selectedRowKeys,
    onChange: onSelectChange,
  };
  const handleClose = () => {
    onClose(false);
  };
  const handleSubmit = (value) => {
    const jsonString = JSON.stringify(selectedRowKeys);
    // console.log("JSON", jsonString);
    const group = {
      ...data,
      ...value,
      role_year: jsonString,
    };
    onSubmit(group);
    // console.log("onSubmit", group);
  };

  const onFinishFailed = (e) => {
    console.log("Failure", e);
  };

  const handleDelete = () => {
    Modal.confirm({
      title: "ลบข้อมูลสมาชิก",
      content: "ต้องการลบข้อมูลสมาชิกคนนี้?",
      centered: true,
      onOk: () => {
        onDelete(data);
      },
      okText: "ลบ",
      cancelText: "ยกเลิก",
    });
  };

  if (data.id) {
    return (
      <Modal
        destroyOnClose={true}
        title="แก้ไขข้อมูลสมาชิก"
        centered={true}
        // width={1000}
        open={open}
        //   onOk={handleSubmit}
        closeIcon={false}
        onCancel={handleClose}
        footer={[
          <Button danger key="delete" onClick={handleDelete}>
            ลบ
          </Button>,
          <Button key="close" onClick={handleClose}>
            ยกเลิก
          </Button>,
          <Button
            key="submit"
            htmlType="submit"
            type="primary"
            onClick={form.submit}
          >
            บันทึก
          </Button>,
        ]}
      >
        <Form
          id="form"
          preserve={false}
          onFinish={handleSubmit}
          onFinishFailed={onFinishFailed}
          layout={"vertical"}
          form={form}
        >
          <Form.Item
            name="firstname"
            label="ชื่อ"
            initialValue={data.firstname}
          >
            <Input placeholder="ชื่อ" />
          </Form.Item>
          <Form.Item
            name="lastname"
            label="นามสกุล"
            initialValue={data.lastname}
          >
            <Input placeholder="นามสกุล" />
          </Form.Item>
          <Form.Item
            name="nickname"
            label="ชื่อเล่น"
            initialValue={data.nickname}
          >
            <Input placeholder="ชื่อเล่น" />
          </Form.Item>
          <Form.Item name="address" label="ที่อยู่" initialValue={data.address}>
            <Input placeholder="ที่อยู่" />
          </Form.Item>

          <Form.Item name="phone" label="โทรศัพท์" initialValue={data.phone}>
            <Input placeholder="โทรศัพท์" />
          </Form.Item>
          <Form.Item name="email" label="อีเมล" initialValue={data.email}>
            <Input placeholder="ไลน์" />
          </Form.Item>
          <Form.Item name="line" label="ไลน์" initialValue={data.line}>
            <Input placeholder="ไลน์" />
          </Form.Item>
          <Form.Item
            name="role_id"
            label="สิทธิ์การใช้งาน"
            initialValue={data.role_id}
            rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
          >
            <Select
              size="large"
              placeholder="สิทธิ์การใช้งาน"
              options={role.map((item) => ({
                value: item.value,
                label: item.label,
              }))}
            />
          </Form.Item>
          <Form.Item name="groupId" label="กลุ่ม" initialValue={data.groupId}>
            <Select
              size="large"
              placeholder="กลุ่ม"
              options={groups.map((item) => ({
                value: item.id,
                label: item.name,
              }))}
            />
          </Form.Item>

          <Form.Item
            name="active"
            label="สถานะการใช้งาน"
            initialValue={data.active}
          >
            <Switch
              defaultChecked={data.active}
              checkedChildren="Active"
              unCheckedChildren="Inactive"
              // onChange={onStatusChange}
            />
          </Form.Item>
        </Form>
        {/* {data.role_id === 1 && ( */}
        <Table
          rowSelection={rowSelection}
          columns={columns}
          dataSource={rows}
        />
        {/* )} */}
      </Modal>
    );
  }
}
