import React from "react";
import ReactExport from "react-export-excel";
import { Link } from "react-router-dom";

const ExcelFile = ReactExport.ExcelFile;
const ExcelSheet = ReactExport.ExcelFile.ExcelSheet;
const ExcelColumn = ReactExport.ExcelFile.ExcelColumn;

export default function PaymentUserList({ data }) {
  //   console.log(data);
  return (
    <div style={{ width: "100%", justifyContent: "end", display: "flex" }}>
      <ExcelFile element={<Link>Download</Link>}>
        <ExcelSheet data={data} name="ยอดสั่งซืิ้อรายคน">
          <ExcelColumn label="ชื่อ" value="firstname" />
          <ExcelColumn label="นามสกุล" value="lastname" />
          <ExcelColumn label="ชื่อเล่น" value="nickname" />
          <ExcelColumn label="โทร" value="phone" />
          <ExcelColumn label="เงินสด" value="cash" />
          <ExcelColumn label="เงินโอน" value="transfer" />
          <ExcelColumn
            label="ยอดรวม"
            value={(col) => parseInt(col.cash) + parseInt(col.transfer)}
          />
        </ExcelSheet>
        {/* <ExcelSheet data={dataSet2} name="Leaves">
      <ExcelColumn label="Name" value="name"/>
      <ExcelColumn label="Total Leaves" value="total"/>
      <ExcelColumn label="Remaining Leaves" value="remaining"/>
  </ExcelSheet> */}
      </ExcelFile>
    </div>
  );
}
