import React from "react";
import { List } from "antd";
import AuctionItem from "./AuctionItem";

export default function AuctionList({ data, onPrint, onClickItem, onSubmit }) {
  return (
    <List
      pagination={{
        pageSize: 10,
      }}
      itemLayout="horizontal"
      dataSource={data}
      renderItem={(item) => (
        <AuctionItem
          data={item}
          onPrint={onPrint}
          onClickItem={onClickItem}
          onSubmit={onSubmit}
        />
      )}
    />
  );
}
