import React, { useEffect, useState } from "react";
import {
  Modal,
  Button,
  Typography,
  Divider,
  Space,
  Upload,
  Image,
  Input,
  DatePicker,
  TimePicker,
} from "antd";
import Resizer from "react-image-file-resizer";
import OrderDetailList from "./OrderDetailList";
import { currencyFormatTH } from "../../../utils/numberFormat";
import dayjs from "dayjs";
import customParseFormat from "dayjs/plugin/customParseFormat";
import moment from "moment";
dayjs.extend(customParseFormat);
const { Text } = Typography;

export default function ConfirmOrderModal({
  open,
  data,
  orderTypeSelect = [],
  event,
  onSubmit,
  onClose,
}) {
  const [imgFile, setImgFile] = useState(null);
  const [mark, setMark] = useState("");
  const [date, setDate] = useState("");
  const [time, setTime] = useState("");

  useEffect(() => {}, [data]);

  const handleClose = () => {
    onClose(false);
  };

  const handleSubmit = () => {
    if (data.payment_by_id === 2) {
      if (date !== "" && time !== "") {
        const newData = {
          ...data,
          payment_by_id: 2,
          payment_date: date + " " + time,
          payment_img: imgFile,
          mark: mark,
        };
        // console.log("onSubmit", newData);
        onSubmit(newData);
      } else {
        Modal.warning({
          title: "ผิดพลาด",
          content: "กรุณาระบุวันเวลาที่ชำระ ให้ครบถ้วน",
          centered: true,
        });
      }
    } else if (data.payment_by_id === 1) {
      const newData = {
        ...data,
        payment_by_id: 1,
        payment_date: moment().format("YYYY-MM-DD HH:mm:ss"),
        payment_img: imgFile,
        mark: mark,
      };
      console.log("onSubmit", newData);
      onSubmit(newData);
    } else {
      const newData = {
        ...data,
        payment_by_id: 3,
        // payment_date: null,
        payment_img: imgFile,
        mark: mark,
      };
      console.log("onSubmit", newData);
      onSubmit(newData);
    }
  };

  const onChangeDate = (date, dateString) => {
    setDate(dateString);
  };

  const onChangeTime = (time, timeString) => {
    setTime(timeString);
  };

  const onChange = async (e) => {
    const file = e.target.files[0];
    const image = await resizeFile(file);
    // console.log(image);
    setImgFile(image);
  };

  const resizeFile = (file) =>
    new Promise((resolve) => {
      Resizer.imageFileResizer(
        file,
        300,
        300,
        "JPEG",
        300,
        0,
        (uri) => {
          resolve(uri);
        },
        "base64"
      );
    });

  return (
    <Modal
      title="ยืนยันรายการ"
      centered={true}
      open={open}
      onOk={handleSubmit}
      closeIcon={false}
      footer={[
        // <Button key="receipt" onClick={handleDownloadReceipt}>
        //   พิมพ์ใบเสร็จ
        // </Button>,
        <Button
          disabled={!imgFile && data.payment_by_id === 2}
          key="submit"
          type="primary"
          onClick={handleSubmit}
        >
          {event === 1 ? "ยืนยันการชำระเงิน" : "ยืนยันรายการ"}
        </Button>,
        <Button key="close" onClick={handleClose}>
          ปิด
        </Button>,
      ]}
    >
      <div>
        <Divider />
        <OrderDetailList data={data.products} />
        {data.donate !== 0 && event === 1 && (
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              marginTop: "16px",
              marginBottom: "16px",
            }}
          >
            <Text strong>เงินบริจาค</Text>
            <Text strong> {currencyFormatTH(data.donate || 0)}</Text>
          </div>
        )}
        <div
          style={{
            justifyContent: "end",
            display: "flex",
          }}
        >
          <Text strong>รวม {currencyFormatTH(data.total_price)}</Text>
        </div>
        <Space direction="vertical">
          <Text strong>
            ช่องทางชำระ:{" "}
            {data.payment_by_id === 1
              ? "เงินสด"
              : data.payment_by_id === 2
              ? "โอนเข้าบัญชี"
              : "เงินเชื่อ (ชำระภายหลัง)"}
          </Text>
          {orderTypeSelect.length > 0 && event === 1 && (
            <Text strong>ประเภทบิล: {orderTypeSelect[0]?.name}</Text>
          )}
          {data.payment_by_id === 2 && (
            <>
              <Text type="secondary">
                วันเวลาที่ชำระ : (กรอกให้ตรงกับสลิปเงินโอน)
              </Text>
              <Space>
                <DatePicker onChange={onChangeDate} />
                <TimePicker
                  onChange={onChangeTime}
                  defaultOpenValue={dayjs("00:00:00", "HH:mm:ss")}
                />
              </Space>
            </>
          )}
        </Space>

        <Divider />
        {data.payment_by_id === 2 && (
          <>
            <div style={{ justifyContent: "center", display: "flex" }}>
              <Space direction="vertical" align="center">
                <Text strong>หลักฐานการชำระเงิน</Text>
                <input type="file" onChange={onChange} />
                {imgFile ? (
                  <div style={{ justifyContent: "center", display: "flex" }}>
                    <Image width={100} src={imgFile} />
                  </div>
                ) : null}
              </Space>
            </div>
            <Divider />
          </>
        )}
        <Input
          style={{
            marginTop: "24px",
          }}
          placeholder="หมายเหตุ (ถ้ามี)"
          onChange={(e) => setMark(e.target.value)}
        />
      </div>
    </Modal>
  );
}
