import React, { useState, useEffect } from "react";
import { Button, Form, Input, Card, Modal, InputNumber, Divider } from "antd";
import ProductTypeItem from "./ProductTypeItem";

export default function AddProductTypeModal({
  open,
  data,
  onClose,
  onSubmit,
  onDelete,
}) {
  const [type, setType] = useState("");

  const [form] = Form.useForm();

  const handleSubmit = () => {
    onSubmit(type);
  };

  const handleClose = () => {
    onClose(false);
  };

  const onFinishFailed = (errorInfo) => {
    console.log("Failed:", errorInfo);
  };

  const handleChangeInput = (e) => {
    // console.log(e);
    setType(e.target.value);
  };

  const handleItemClick = (data) => {
    onDelete(data);
  };

  return (
    <Modal
      title="เพิ่มประเภทสินค้า"
      destroyOnClose={true}
      centered={true}
      open={open}
      onOk={handleSubmit}
      closeIcon={false}
      // onCancel={handleClose}
      footer={[
        <Button
          key="close"
          // href="https://google.com"
          // loading={loading}
          onClick={handleClose}
        >
          ยกเลิก
        </Button>,
        <Button
          disabled={type === ""}
          key="submit"
          type="primary"
          onClick={form.submit}
        >
          บันทึก
        </Button>,
      ]}
    >
      <div style={{ padding: 16 }}>
        {data.map((item) => (
          <ProductTypeItem
            key={item.id}
            id={item.id}
            name={item.name}
            onClick={handleItemClick}
          />
        ))}
        <Divider />
        <Form
          form={form}
          labelCol={{
            span: 8,
          }}
          wrapperCol={{
            span: 18,
          }}
          layout="horizontal"
          onFinish={handleSubmit}
          onFinishFailed={onFinishFailed}
        >
          <Form.Item
            name="name"
            label="ชื่อรายการใหม่"
            rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
          >
            <Input name="name" onChange={handleChangeInput} />
          </Form.Item>
          {/* {data.order_type_id === 1 ? ( */}
          {/* <Form.Item
              name="price"
              label="ราคาขาย"
              rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
            >
              <InputNumber
                size="large"
                name="price"
                style={{ width: "100%" }}
                formatter={(value) =>
                  `${value}`.replace(/\B(?=(\d{3})+(?!\d))/g, ",")
                }
                onChange={handleChangePrice}
              />
            </Form.Item>
            <Form.Item
              name="amount"
              label="จำนวนสต็อก"
              rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
            >
              <InputNumber
                size="large"
                name="amount"
                style={{ width: "100%" }}
                formatter={(value) =>
                  `${value}`.replace(/\B(?=(\d{3})+(?!\d))/g, ",")
                }
                onChange={handleChangeAmount}
              />
            </Form.Item> */}
        </Form>
      </div>
    </Modal>
  );
}
