import React from "react";
import { Space, Typography } from "antd";
import { currencyFormatTH } from "../../../utils/numberFormat";
const { Text } = Typography;

export default function OrderDetailItem({ data, index }) {
  return (
    <div>
      <div
        style={{
          flexDirection: "row",
          display: "flex",
          justifyContent: "space-between",
        }}
      >
        <Space direction="vertical">
          <Text>{data.name}</Text>
          <Text type="secondary">{currencyFormatTH(data.price)}</Text>
        </Space>
        <Space direction="vertical" align="end ">
          <Text type="secondary">x{data.amount}</Text>
          <Text>{currencyFormatTH(data.price * data.amount)}</Text>
        </Space>
      </div>
      {/* <hr /> */}
      <div
        style={{
          width: "100%",
          borderBottom: "1px solid rgba(128,128,128,0.3)",
          borderRadius: "6px",
          marginBottom: "8px",
        }}
      />
      {/* <Divider /> */}
    </div>
  );
}
