import { List, Space, Tag, Typography } from "antd";
import moment from "moment";
import React from "react";
import { useSelector } from "react-redux";
import { Link } from "react-router-dom";

const { Text } = Typography;

export default function OrderItem({
  data,
  onClickManageJob,
  onFinishJob,
  onClickItem,
  onClickFinishJobDetail,
  onDownloadWorkSheet,
}) {
  const user = useSelector((state) => state.token);
  const handleClick = () => {
    onClickManageJob(data);
  };

  const handleClickFinish = () => {
    onFinishJob(data);
  };

  const handleClickFinishDetail = () => {
    onClickFinishJobDetail(data);
  };

  const handleClickWorkSheet = () => {
    onDownloadWorkSheet(data);
  };
  const listItem1 = [
    <Tag color="warning">รอดำเนินการ</Tag>,
    <Link onClick={handleClick}>จัดการ</Link>,
  ];

  const listItem2 = [
    <Link onClick={handleClickWorkSheet}>ใบติดตั้ง</Link>,
    <Link onClick={handleClick}>แก้ไข</Link>,
    <Link onClick={handleClickFinish}>ส่งงาน</Link>,
  ];

  const listItem3 = [<Link onClick={handleClickFinish}>ส่งงาน</Link>];

  const listItem4 = [
    <Link onClick={handleClickWorkSheet}>ใบติดตั้ง</Link>,
    <Link onClick={handleClickFinishDetail}>รายละเอียด</Link>,
  ];

  const listItem5 = [<Link onClick={handleClickFinishDetail}>รายละเอียด</Link>];

  return (
    <List.Item
      actions={
        data.maintenance_status_id === 1 && user.role === "admin"
          ? listItem1
          : data.maintenance_status_id === 2 && user.role === "admin"
          ? listItem2
          : data.maintenance_status_id === 2 && user.role === "maintenance"
          ? listItem3
          : data.maintenance_status_id === 3 && user.role === "admin"
          ? listItem4
          : listItem5
      }
    >
      <List.Item.Meta
        onClick={() => {
          onClickItem(data);
        }}
        // avatar={
        //   <Avatar
        //     src={`https://xsgames.co/randomusers/avatar.php?g=pixel&key=${1}`}
        //   />
        // }
        title={
          <div style={{ flexDirection: "column", display: "flex" }}>
            {/* <Space> */}
            <Text>{data?.storename}</Text>
            {/* {data.maintenance_status_id === 3 && (
                <Tag color="success">ติดตั้งแล้ว</Tag>
              )} */}
            {/* </Space> */}
            <Text type="secondary">{data.phone}</Text>
            <Text type="secondary" style={{ fontSize: 12 }}>
              ถนน {data.road}
            </Text>
          </div>
        }
        description={
          data.maintenance_status_id !== 1 && (
            <div style={{ flexDirection: "column", display: "flex" }}>
              <Text type="secondary" style={{ fontSize: 12 }}>
                ผู้ติดตั้ง {data.maintenance_name} {data.maintenance_lastname} (
                {data.maintenance_nickname})
              </Text>
              <Text type="secondary" style={{ fontSize: 12 }}>
                {data.maintenance_phone}
              </Text>

              <Text type="secondary" style={{ fontSize: 12 }}>
                วันที่:{" "}
                {data.maintenance_status_id === 2
                  ? moment(data.maintenance_processing_datetime).format(
                      "DD/MM/YYYY HH:mm:ss"
                    )
                  : moment(data.maintenance_finish_datetime).format(
                      "DD/MM/YYYY HH:mm:ss"
                    )}
              </Text>
            </div>
          )
        }
        // description={data.phone}
      />
    </List.Item>
  );
}
