import React, { useEffect, useState } from "react";
import { Button, Divider, Modal, Space } from "antd";
import {
  UserAddOutlined,
  UsergroupAddOutlined,
  OrderedListOutlined,
} from "@ant-design/icons";
import UserList from "./UserList";
import UserGroup from "./UserGroup";
import AddOrEditUserGroupModal from "./AddOrEditUserGroupModal";
import EditUserModal from "./EditUserModal";
import AddUserModal from "./AddUserModal";
// import PasswordModal from "./PasswordModal";
import baseAPI from "../../../api/baseAPI";
import { useSelector, useDispatch } from "react-redux";
// import { useNavigate } from "react-router-dom";
import Loading from "../../../utils/Loading";
import { addToken } from "../../../redux/reduxSlice";
import AddYearModal from "./AddYearModal";

export default function Main() {
  const user = useSelector((state) => state.token);
  const dispatch = useDispatch();
  // const navigate = useNavigate();
  const [openUserGroupModal, setOpenUserGroupModal] = useState(false);
  const [openUserModal, setOpenUserModal] = useState(false);
  const [openEditUserModal, setOpenEditUserModal] = useState(false);
  const [openAddYearModal, setOpenAddYearModal] = useState(false);
  const [userEdit, setUserEdit] = useState({});
  const [groups, setGroup] = useState([]);
  const [users, setUsers] = useState([]);
  const [userListHolders, setUserListHolders] = useState([]);
  const [groupSelected, setGroupSelected] = useState(0);
  const [roleYear, setRoleYear] = useState([]);

  const [loading, setLoading] = useState(false);

  useEffect(() => {
    fetchAllGroup();
    fetchUser();
    fetchAllRoleYear();
  }, []);

  const fetchAllRoleYear = async () => {
    setLoading(true);
    await baseAPI
      .get(`/city_pillar_shrine/role/year`, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((result) => {
        // console.log("Years", result.data);
        setRoleYear(result.data);
        setLoading(false);
      })
      .catch((error) => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
  };

  const fetchAllGroup = async () => {
    setLoading(true);
    await baseAPI
      .get(`/city_pillar_shrine/group`, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((result) => {
        setGroup(result.data);
        setLoading(false);
      })
      .catch((error) => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
  };

  const fetchUser = async () => {
    setLoading(true);
    await baseAPI
      .get(`/city_pillar_shrine/users`, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((res) => {
        setUsers(res.data);
        setUserListHolders(res.data);
        setLoading(false);
      })
      .catch(() => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
  };

  const handleClickAddGroup = () => {
    setOpenUserGroupModal(true);
  };

  const handleClickAddUser = () => {
    setOpenUserModal(true);
  };

  const postGroup = async (data) => {
    setLoading(true);
    setOpenUserGroupModal(false);
    await baseAPI
      .post(`/city_pillar_shrine/group`, data, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        Modal.success({ content: "เพิ่มกลุ่มสำเร็จ", centered: true });
        fetchAllGroup();
        // setLoading(false)
      })
      .catch((error) => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
  };

  const updateGroup = async (data) => {
    setLoading(true);
    setOpenUserGroupModal(false);
    await baseAPI
      .put(`/city_pillar_shrine/group`, data, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        Modal.success({ content: "แก้ไขกลุ่มสำเร็จ", centered: true });
        fetchAllGroup();
        // setLoading(false)
      })
      .catch((error) => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
  };

  const handleSubmitGroup = async (data) => {
    if (data.id && data.name) {
      updateGroup(data);
    } else if (data.name) {
      postGroup(data);
    } else {
      Modal.warning({
        title: "ไม่มีข้อมูล",
        content: "กรุณากรอกข้อมูลที่ต้องการจะเพิ่ม หรือแก้ไข",
        centered: true,
      });
    }

    // setGroup((pre) => [...pre, { ...data }]);
  };

  const handleSubmitAddUser = async (data) => {
    console.log("User Data", data);
    setLoading(true);
    await baseAPI
      .post(`/city_pillar_shrine/users`, data, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        Modal.success({ content: "เพิ่มสมาชิกสำเร็จ", centered: true });
        fetchUser();
      })
      .catch((error) => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
      });
    setLoading(false);
    setOpenUserModal(false);
  };

  const handleChangeGroup = (data) => {
    // console.log("GroupSelected", data);
    setGroupSelected(data);
  };

  useEffect(() => {
    setGroupSelected(0);
  }, []);

  useEffect(() => {
    if (groupSelected === 0) {
      setUsers(userListHolders);
    } else {
      const sortUsersByGroup = userListHolders.filter(
        (user) => user.groupId === groupSelected
      );
      setUsers(sortUsersByGroup);
      //   setGroupSelected(0);
    }
  }, [userListHolders, groupSelected]);

  const handleEditUser = (data) => {
    console.log("User Edit", data);
    setUserEdit(data);
    setOpenEditUserModal(true);
  };

  const handleSubmitEdit = async (data) => {
    console.log("Submit Edit", data);
    setLoading(true);
    await baseAPI
      .put(`/city_pillar_shrine/users`, data, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        Modal.success({ content: "แก้ไขข้อมูลสมาชิกสำเร็จ", centered: true });
        // fetchUser();
        const newState = userListHolders.map((obj) => {
          if (obj.id === data.id) {
            return { ...obj, ...data };
          }
          return obj;
        });
        // console.log("NEW ARRAY", newState);
        setUserListHolders(newState);
        setUsers(newState);
        setLoading(false);
      })
      .catch((error) => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });

    setOpenEditUserModal(false);
  };

  const handleDeleteUser = async (data) => {
    setOpenEditUserModal(false);
    setLoading(true);
    await baseAPI
      .delete(`/city_pillar_shrine/users/${data.id}`, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        Modal.success({ content: "ลบสมาชิกสำเร็จ", centered: true });
        const result = userListHolders.filter((item) => item.id !== data.id);
        setUserListHolders(result);
        setLoading(false);
      })
      .catch((error) => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
  };

  // const handleSelect = async (data) => {
  //   console.log(data);
  //   setLoading(true);
  //   await baseAPI
  //     .put(`/city_pillar_shrine/users/status`, data, {
  //       headers: {
  //         "x-access-token": user.token,
  //       },
  //     })
  //     .then((response) => {
  //       // Modal.success({ content: "แก้ไขข้อมูลสมาชิกสำเร็จ", centered: true });
  //       // fetchUser();
  //       const newState = userListHolders.map((obj) => {
  //         if (obj.id === data.id) {
  //           return { ...obj, ...data };
  //         }
  //         return obj;
  //       });
  //       // console.log("NEW ARRAY", newState);
  //       setUserListHolders(newState);
  //       setUsers(newState);
  //       setLoading(false);
  //     })
  //     .catch((error) => {
  //       dispatch(addToken({}));
  //       // navigate("/login");
  //       Modal.warning({
  //         title: "คำขอล้มเหลว",
  //         content: "Sessions Expired",
  //         centered: true,
  //       });
  //       setLoading(false);
  //     });
  // };

  const handleClickAddYears = () => {
    fetchAllRoleYear();
    setOpenAddYearModal(true);
  };

  const handleSubmitYear = async (value) => {
    console.log("Year", value);
    setOpenAddYearModal(false); //
    setLoading(true);
    const data = {
      year: value,
    };
    await baseAPI
      .post(`/city_pillar_shrine/role/year`, data, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        Modal.success({ content: "เพิ่มปีที่เข้าถึงข้อมูล", centered: true });
        // fetchUser();
        setLoading(false);
      })
      .catch((error) => {
        dispatch(addToken({}));
        // navigate("/login");
        setLoading(false);
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
      });

    // setOpenUserModal(false);
  };

  if (loading) return <Loading />;

  return (
    <div>
      <div
        style={{
          justifyContent: "end",
          display: "flex",
        }}
      >
        <Space>
          <Button onClick={handleClickAddYears}>เพิ่มปีที่เข้าถึงข้อมูล</Button>
          <Button onClick={handleClickAddGroup} icon={<UsergroupAddOutlined />}>
            เพิ่ม/แก้ไขกลุ่ม
          </Button>
          <Button onClick={handleClickAddUser} icon={<UserAddOutlined />}>
            เพิ่มสมาชิก
          </Button>
        </Space>
      </div>
      <Divider />
      <UserGroup
        data={groups}
        defaultValue={"ทั้งหมด"}
        onChange={handleChangeGroup}
      />
      <Divider />
      <UserList
        data={users}
        onEdit={handleEditUser}
        //  onSelect={handleSelect}
      />

      {/* MODAL HANDLE */}
      <AddOrEditUserGroupModal
        data={groups}
        open={openUserGroupModal}
        onClose={setOpenUserGroupModal}
        onSubmit={handleSubmitGroup}
      />
      <AddUserModal
        open={openUserModal}
        onClose={setOpenUserModal}
        groups={groups}
        roleYears={roleYear}
        onSubmit={handleSubmitAddUser}
      />
      <EditUserModal
        data={userEdit}
        open={openEditUserModal}
        onClose={setOpenEditUserModal}
        roleYears={roleYear}
        groups={groups}
        onSubmit={handleSubmitEdit}
        onDelete={handleDeleteUser}
      />

      <AddYearModal
        open={openAddYearModal}
        data={roleYear}
        onClose={setOpenAddYearModal}
        onSubmit={handleSubmitYear}
      />
    </div>
  );
}
