import React, { useEffect, useState } from "react";
import { Modal, Button, Typography, Divider, Space, Input, List } from "antd";
// import OrderDetailList from "../order/OrderDetailList";
import ProductItem from "./ProductItem";
const { Text } = Typography;

export default function PrintWorkSheetModal({ open, data, onSubmit, onClose }) {
  //   console.log("PrintWork", data);
  const [deliveryMark, setDeliveryMark] = useState(data.delivery_mark);

  useEffect(() => {
    setDeliveryMark(data.delivery_mark);
  }, [data]);

  const handleClose = () => {
    onClose(false);
  };

  const handleSubmit = () => {
    onSubmit({ ...data, delivery_mark: deliveryMark });
  };

  return (
    <Modal
      destroyOnClose={true}
      title="ยืนยันรายการ"
      centered={true}
      open={open}
      onOk={handleSubmit}
      closeIcon={false}
      footer={[
        // <Button key="receipt" onClick={handleDownloadReceipt}>
        //   พิมพ์ใบเสร็จ
        // </Button>,
        <Button
          // disabled={!imgFile}
          key="submit"
          type="primary"
          onClick={handleSubmit}
        >
          พิมพ์ใบงาน
        </Button>,
        <Button key="close" onClick={handleClose}>
          ปิด
        </Button>,
      ]}
    >
      <div>
        <Space direction="vertical">
          <Text strong>ชื่อลูกค้า :{data?.storename}</Text>
          <Text strong>โทร : {data.phone}</Text>
          <Text type="secondary">ถนน : {data.road}</Text>
        </Space>

        <Divider />
        <List
          itemLayout="horizontal"
          dataSource={data.products}
          renderItem={(item, index) => <ProductItem key={index} data={item} />}
        />
        {/* <OrderDetailList data={data.products} /> */}

        <Divider />
        <Input
          defaultValue={data.delivery_mark}
          placeholder="หมายเหตุ (ถ้ามี)"
          onChange={(e) => setDeliveryMark(e.target.value)}
        />
      </div>
    </Modal>
  );
}
