import React from "react";
import { Tag, Typography } from "antd";
import moment from "moment/moment";
import "moment/locale/th";
import { currencyFormatTH } from "../../../utils/numberFormat";
import { Link } from "react-router-dom";

const { Text } = Typography;
export default function OrderHistoryItem({ data, onClick, onConfirm }) {
  const sum = data.products.reduce((accumulator, object) => {
    const total = object.price * object.amount;
    return accumulator + total;
  }, 0);
  //   console.log(data);

  const handleClickItem = () => {
    onClick(data);
  };

  const onClickConfirmOrder = () => {
    onConfirm(data);
  };

  const RenderDataList = ({ title, content }) => (
    <div
      style={{
        flexDirection: "row",
        display: "flex",
        justifyContent: "space-between",
      }}
    >
      <Text style={{ fontSize: 12 }} type="secondary">
        {title}
      </Text>
      <Text style={{ fontSize: 12 }} type="secondary">
        {content}
      </Text>
    </div>
  );

  return (
    <div>
      <div onClick={handleClickItem}>
        <div
          style={{
            flexDirection: "column",
            display: "flex",
            justifyContent: "space-between",
          }}
        >
          <div
            style={{
              flexDirection: "row",
              display: "flex",
              justifyContent: "space-between",
            }}
          >
            <Text strong style={{ fontSize: 12 }}>
              เลขที่ {data.order_number}
            </Text>
            <Text style={{ fontSize: 12 }} type="secondary">
              {moment(data.datetime).format("ll")}
            </Text>
          </div>

          <RenderDataList
            title={"ชื่อร้านค้า : " + data.storename}
            content={""}
          />
          <RenderDataList
            title={"ยอดสั่งซื้อสินค้า"}
            content={currencyFormatTH(sum)}
          />
          <RenderDataList
            title={"ยอดบริจาค"}
            content={currencyFormatTH(data.donate)}
          />
        </div>
        <div
          style={{
            justifyContent: "space-between",
            display: "flex",
          }}
        >
          <Text strong style={{ fontSize: 12 }}>
            {data.payment}
          </Text>
          <Text strong style={{ fontSize: 12 }}>
            รวม {currencyFormatTH(data.total_price)}
          </Text>
        </div>
        {data.order_type && data.event_id === 1 && (
          <Text strong style={{ fontSize: 12 }}>
            ประเภท {data.order_type}
          </Text>
        )}
      </div>

      {data.event_id === 2 && data.payment_by_id === 3 && (
        <div style={{ justifyContent: "center", display: "flex" }}>
          <Link onClick={onClickConfirmOrder}>ยืนยันการชำระเงิน</Link>
        </div>
      )}
      <hr />
    </div>
  );
}
