import React from "react";
import { List, Tag } from "antd";
import { Link } from "react-router-dom";

export default function UserItem({
  data,
  onClick,
  onEdit,
  // onSelect
}) {
  console.log(data);
  const handleCkickUserItem = () => {
    onClick(data);
  };

  const handleEdit = () => {
    onEdit(data);
  };

  // const onChange = (value) => {
  //   console.log(value);
  //   onSelect({ ...data, active: value });
  // };

  return (
    <List.Item
      actions={[
        <Tag color={data.active === 1 ? "#87d068" : "gray"}>
          {data.active === 1 ? "ใช้งาน" : "ไม่ใช้งาน"}
        </Tag>,
        // <Switch
        //   defaultChecked={data.active}
        //   checkedChildren="Active"
        //   unCheckedChildren="Inactive"
        //   onChange={onChange}
        // />,
        <Link onClick={handleEdit}>แก้ไขข้มูล</Link>,
      ]}
    >
      <List.Item.Meta
        onClick={() => {
          handleCkickUserItem(data);
        }}
        // avatar={
        //   <Avatar
        //     src={`https://xsgames.co/randomusers/avatar.php?g=pixel&key=${1}`}
        //   />
        // }
        title={
          data?.firstname + " " + data.lastname + " (" + data.nickname + ")"
        }
        description={data.phone}
        // description={data.phone}
      />
    </List.Item>
  );
}
