import React, { useState } from "react";
import {
  Button,
  InputNumber,
  Modal,
  Radio,
  Typography,
  Divider,
  Space,
} from "antd";

const { Text } = Typography;

export default function AddDonateModal({ open, onClose, onSubmit }) {
  const [donate, setDonate] = useState(0);
  const [typeSelect, setTypeSelect] = useState(1);
  const handleSubmit = () => {
    console.log("onChangeType", { donate: donate, donate_type: typeSelect });
    onSubmit({ donate: donate, donate_type: typeSelect });
  };

  const handleChangeInput = (e) => {
    setDonate(e);
  };

  const handleClose = () => {
    onClose(false);
  };

  const onChangeType = (e) => {
    setTypeSelect(e.target.value);
  };

  return (
    <Modal
      title="เงินบริจาค"
      // width={1000}
      centered={true}
      open={open}
      onOk={handleSubmit}
      closeIcon={false}
      // onCancel={handleClose}
      footer={[
        <Button key="close" onClick={handleClose}>
          ยกเลิก
        </Button>,
        <Button key="submit" type="primary" onClick={handleSubmit}>
          บันทึก
        </Button>,
      ]}
    >
      <Divider />
      <div style={{ display: "flex", justifyContent: "space-between" }}>
        <Text strong>จำนวนเงิน</Text>
        <InputNumber
          formatter={(value) =>
            `${value}`.replace(/\B(?=(\d{3})+(?!\d))/g, ",")
          }
          onChange={handleChangeInput}
          style={{ width: 150 }}
        />
        <Text strong>บาท</Text>
      </div>
      {/* <Space direction="vertical">
        <Text strong>ประเภท</Text>
        <Radio.Group onChange={onChangeType} value={typeSelect}>
          <Space direction="vertical">
            <Radio value={1}>ทั่วไป</Radio>
            <Radio value={2}>งานสมโภช</Radio>
          </Space>
        </Radio.Group>
      </Space> */}
      <Divider />
    </Modal>
  );
}
