import React, { useEffect, useState } from "react";
import { Button, Modal, Descriptions, Typography, Divider } from "antd";
import GoogleMapReact from "google-map-react";

import MarkerImg from "../../../assets/images/Marker.png";
import { GOOGLEMAP_API_KEY } from "../../../utils/googlemapkey";

const Marker = () => (
  <div>
    <img width={50} src={MarkerImg} alt="" />
    {/* <HomeFilled /> */}
  </div>
);

export default function CustomerDetailModal({ open, onClose, data }) {
  //   console.log("USERDETAIL", data);
  const lat = parseFloat(data?.latitude);
  const lng = parseFloat(data?.longitude);

  const handleClickGPS = () => {
    window.open("https://maps.google.com?q=" + lat + "," + lng);
  };

  const defaultProps = {
    center: {
      lat: lat || 16.43215608802593,
      lng: lng || 102.82841191600843,
    },
    zoom: 12,
  };
  const handleClose = () => {
    onClose(false);
  };

  if (data.id) {
    return (
      <Modal
        title="รายละเอียด"
        centered={true}
        // width={1000}
        open={open}
        //   onOk={handleSubmit}
        closeIcon={false}
        onCancel={handleClose}
        footer={[
          <Button key="close" onClick={handleClose}>
            ปิด
          </Button>,
          // <Button key="submit" type="primary" onClick={handleSubmit}>
          //   บันทึก
          // </Button>,
        ]}
      >
        <Descriptions>
          <Descriptions.Item label="ชื่อร้าน">
            {data.storename}
          </Descriptions.Item>
          {/* <Descriptions.Item label="ชื่อสกุล">
            {data.fullname}
          </Descriptions.Item>
          <Descriptions.Item label="โทรศัพท์">{data.phone}</Descriptions.Item>
          <Descriptions.Item label="ไลน์">{data.line}</Descriptions.Item> */}
          <Descriptions.Item label="สาย/ถนน">{data.road}</Descriptions.Item>
          <Descriptions.Item label="ที่อยู่">{data.address}</Descriptions.Item>
        </Descriptions>
        <Divider />
        <div
          style={{
            justifyContent: "end",
            display: "flex",
            marginBottom: "16px",
          }}
        >
          <Button onClick={handleClickGPS} type="primary">
            นำทางด้วย Google Map
          </Button>
        </div>

        <div style={{ height: "300px", width: "100%", marginBottom: 16 }}>
          <GoogleMapReact
            bootstrapURLKeys={{ key: GOOGLEMAP_API_KEY }}
            center={defaultProps.center}
            defaultZoom={defaultProps.zoom}
            yesIWantToUseGoogleMapApiInternals
            // onClick={onMapClick}
          >
            <Marker lat={lat} lng={lng} />
          </GoogleMapReact>
        </div>
      </Modal>
    );
  }
  return false;
}
