import React, { useEffect, useState } from "react";
import YearPicker from "./YearPicker";
import {
  Divider,
  Form,
  Table,
  Typography,
  Select,
  Modal,
  Button,
  Space,
} from "antd";
import baseAPI from "../../../api/baseAPI";
import { useSelector } from "react-redux";
import moment from "moment";
import AssociationTable from "./AssociationTable";

export default function AssociationList() {
  const user = useSelector((state) => state.token);

  const [year, setYear] = useState(moment().format("YYYY"));
  const [dataSource, setDataSource] = useState([]);

  useEffect(() => {
    console.log("YEAR", year);
    fetchAssociationListByYear(year);
  }, [year]);

  const handleChangeYear = (value) => {
    setYear(value);
    setDataSource([]);
    // console.log("Year", value);
  };

  const fetchAssociationListByYear = async (year) => {
    await baseAPI
      .get(`/city_pillar_shrine/association`, {
        params: { year },
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((res) => {
        console.log(res.data);
        setDataSource(res.data);
        // setMembersHolder(res.data);
      })
      .catch((err) => {
        // dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
      });
  };

  return (
    <div>
      <YearPicker onChange={handleChangeYear} />
      <Divider />
      <AssociationTable data={dataSource} />
    </div>
  );
}
