import {
  Button,
  Divider,
  InputNumber,
  Modal,
  Select,
  Space,
  Tag,
  Typography,
} from "antd";
import React, { useEffect, useState } from "react";

const { Text } = Typography;

export default function SelectSeatNumberModal({
  open,
  order,
  detail,
  bookingLogDeluxe,
  bookingLogVip,
  onClose,
  onSubmit,
  onCancel,
}) {
  const [seatDeluxe, setSeatDeluxe] = useState([]);
  const [seatVip, setSeatVip] = useState([]);
  const [selectSeat, setSelectSeat] = useState(0);
  const [selectType, setSelectType] = useState(order.ticket_type_id);
  const [selectTypeText, setSelectTypeText] = useState(
    order.ticket_type_id === 2 ? "VIP" : "Standard"
  );

  useEffect(() => {
    // console.log("DETAIL55", detail);
  }, [open]);

  const handleClose = () => {
    onClose(false);
  };

  const handleCancelTable = () => {
    Modal.confirm({
      title: "ยกเลิกการจองโต๊ะ",
      content: "ต้องการยกเลิการจองหรือไม่",
      centered: true,
      onOk: () => {
        const data = {
          order_id: order.id,
          ticket_type_id: order.ticket_type_id,
          ticket_status_id: 1,
        };
        onCancel(data);
      },
    });
  };

  const handleSubmit = () => {
    const data = {
      order_id: order.id,
      ticket_sale_id: detail.id,
      ticket_type_id: selectType,
      ...selectSeat,
      ticket_status_id: 2,
    };

    if (order.ticket_type_id === null) {
      onSubmit(data);
    } else {
      if (order.ticket_type_id === selectType) {
        onSubmit(data);
      } else {
        Modal.error({
          title: `ร้านค้านี้ถูกเลือกแล้วโดยโต๊ะประเภท ${
            order.ticket_type_id === 1 ? "Standard" : "VIP"
          }`,
          content: "หากต้องการเปลี่ยนประเภทโต๊ะกรุณายกเลิกการจอง ก่อนจองใหม่",
          centered: true,
        });
      }
    }
  };

  const handleClickSeatDeluxe = (data) => {
    // console.log(data);
    setSelectSeat(data);
    const newSeat = seatDeluxe.map((seat) => {
      if (data.seat_number === seat.seat_number) {
        return { ...seat, ticket_status_id: 3 };
      } else if (seat.ticket_status_id === 2) {
        return { ...seat };
      } else {
        return { ...seat, ticket_status_id: 1 };
      }
    });
    setSeatDeluxe(newSeat);
  };

  const handleClickSeatVip = (data) => {
    // console.log(data);
    setSelectSeat(data);
    const newSeat = seatVip.map((seat) => {
      if (data.seat_number === seat.seat_number) {
        return { ...seat, ticket_status_id: 3 };
      } else if (seat.ticket_status_id === 2) {
        return { ...seat };
      } else {
        return { ...seat, ticket_status_id: 1 };
      }
    });
    setSeatVip(newSeat);
  };

  useEffect(() => {
    console.log("SELECT_TYPE", selectType);
  }, [open]);

  useEffect(() => {
    setSelectType(order.ticket_type_id === null ? 1 : order.ticket_type_id);
    setSelectTypeText(order.ticket_type_id === 2 ? "VIP" : "Standard");
    setSeatDeluxe([]);
    setSeatVip([]);
    // console.log("DETAIL", detail);
    for (let i = 0; i < detail.table_amount; i++) {
      const value = i + 1;
      //   console.log("Booking", bookingLog);
      let map = bookingLogDeluxe.filter(
        (log) => log.ticket_sale_id === detail.id && log.seat_number === value
      );
      // console.log("MAP", map);
      if (map.length > 0) {
        setSeatDeluxe((pre) => [...pre, { ...map[0], ticket_status_id: 2 }]);
      } else {
        setSeatDeluxe((pre) => [
          ...pre,
          {
            seat_number: value,
            ticket_status_id: 1,
            ticket_sale_id: detail.id,
          },
        ]);
      }
    }

    for (let i = 0; i < detail.table_vip_amount; i++) {
      const value = i + 1;
      //   console.log("Booking", bookingLog);
      let map = bookingLogVip.filter(
        (log) => log.ticket_sale_id === detail.id && log.seat_number === value
      );
      if (map.length > 0) {
        // console.log("MAP", map);
        setSeatVip((pre) => [...pre, { ...map[0], ticket_status_id: 2 }]);
      } else {
        setSeatVip((pre) => [
          ...pre,
          {
            seat_number: value,
            ticket_status_id: 1,
            ticket_sale_id: detail.id,
          },
        ]);
      }
    }

    return () => {
      setSeatDeluxe([]);
      setSeatVip([]);
      setSelectSeat(0);
    };
  }, [open]);

  const handleChange = (e) => {
    setSelectType(e);
    if (e === 1) {
      setSelectTypeText("Standard");
    } else {
      setSelectTypeText("VIP");
    }
  };

  return (
    <Modal
      destroyOnClose={true}
      title={"เลือกโต๊ะ ปีที่จัดงาน " + detail.year}
      centered={true}
      open={open}
      closeIcon={false}
      footer={[
        order.ticket_status_id === 2 && (
          <Button danger key="cancel" onClick={handleCancelTable}>
            ยกเลิกโต๊ะ
          </Button>
        ),
        <Button
          key="submit"
          type="primary"
          disabled={selectSeat === 0 ? true : false}
          onClick={handleSubmit}
        >
          ยืนยันการจอง
        </Button>,
        <Button key="close" onClick={handleClose}>
          ปิด
        </Button>,
      ]}
    >
      <>
        <div style={{ flexDirection: "column", display: "flex" }}>
          <Text strong>ชื่อลูกค้า {order.storename}</Text>
          <Text>โทร {order.phone}</Text>
          {order.ticket_status_id === 2 && order.ticket_type_id === 1 && (
            <Space>
              <Text strong>โต๊ะที่จอง</Text>
              <Tag
                color="#87d068"
                style={{ margin: 4, width: 40, textAlign: "center" }}
              >
                {order.seat_number}
              </Tag>
            </Space>
          )}
          {/* {order.ticket_status_id === 2 && order.ticket_type_id === 2 && (
            <Space>
              <Text strong>โต๊ะที่จอง VIP </Text>
              <Tag
                color="#FBE065"
                style={{
                  margin: 4,
                  width: 40,
                  textAlign: "center",
                  color: "black",
                }}
              >
                {order.seat_number_vip}
              </Tag>
            </Space>
          )} */}
        </div>
        {/* <Divider /> */}

        {/* <Space>
          <Text>เลือกประเภทโต๊ะ</Text>
          <Select
            defaultValue={order.ticket_type_id || 1}
            style={{ width: "150px" }}
            onChange={handleChange}
            options={[
              { label: "Standard", value: 1 },
              { label: "VIP", value: 2 },
            ]}
          />
        </Space> */}
        <Divider />
        {/* <h2>{selectTypeText}</h2> */}
        <div>
          {seatDeluxe.map((item) => (
            <Tag
              key={item.seat_number}
              color={
                item.ticket_status_id === 1
                  ? "#87d068"
                  : item.ticket_status_id === 3
                  ? "#108ee9"
                  : "#f50"
              }
              style={{ margin: 4, width: 40, textAlign: "center" }}
              onClick={() => {
                if (item.ticket_status_id !== 2) {
                  handleClickSeatDeluxe(item);
                } else {
                  alert("โต๊ะหมายเลขนี้ถูกจองแล้ว");
                  setSelectSeat(0);
                }
              }}
            >
              {item.seat_number}
            </Tag>
          ))}
          {/* {selectType !== 2
            ? seatDeluxe.map((item) => (
                <Tag
                  key={item.seat_number}
                  color={
                    item.ticket_status_id === 1
                      ? "#87d068"
                      : item.ticket_status_id === 3
                      ? "#108ee9"
                      : "#f50"
                  }
                  style={{ margin: 4, width: 40, textAlign: "center" }}
                  onClick={() => {
                    if (item.ticket_status_id !== 2) {
                      handleClickSeatDeluxe(item);
                    } else {
                      alert("โต๊ะหมายเลขนี้ถูกจองแล้ว");
                      setSelectSeat(0);
                    }
                  }}
                >
                  {item.seat_number}
                </Tag>
              ))
            : seatVip.map((item) => (
                <Tag
                  key={item.seat_number}
                  color={
                    item.ticket_status_id === 1
                      ? "#FBE065"
                      : item.ticket_status_id === 3
                      ? "#108ee9"
                      : "#f50"
                  }
                  style={{
                    margin: 4,
                    width: 40,
                    textAlign: "center",
                    color: "black",
                  }}
                  onClick={() => {
                    if (item.ticket_status_id !== 2) {
                      handleClickSeatVip(item);
                    } else {
                      alert("โต๊ะหมายเลขนี้ถูกจองแล้ว");
                      setSelectSeat(0);
                    }
                  }}
                >
                  {item.seat_number}
                </Tag>
              ))} */}
        </div>
        <Divider />
        <div style={{ flexDirection: "column", display: "flex" }}>
          {/* <Text type={selectType === 1 ? "success" : "warning"}>
            {selectType === 1 ? "สีเขียวคือว่าง" : "สีเหลืองคือว่าง"}
          </Text> */}
          <Text type="danger">* สีแดงคือจองแล้ว *</Text>

          {/* <InputNumber
            style={{ width: "100%", marginTop: "8px" }}
            placeholder="เลือกหมายเลขโต๊ะที่ยังว่าง"
            onChange={(e) => setSeat(e.target.value)}
          /> */}
        </div>
      </>
    </Modal>
  );
}
