import React, { useState, useEffect } from "react";
import { Typography, Divider, Modal, message, Spin, Button } from "antd";
import * as XLSX from "xlsx";
import { useDispatch, useSelector } from "react-redux";
import AuctionList from "./acution/AuctionList";
import baseAPI from "../../../api/baseAPI";

const { Text } = Typography;

export default function Auction() {
  const user = useSelector((state) => state.token);
  const [messageApi, contextHolder] = message.useMessage();
  const [dataList1, setDataList1] = useState([]);
  const [dataList2, setDataList2] = useState([]);
  const [dataList3, setDataList3] = useState([]);
  const [dataShow, setDataShow] = useState([]);
  const [loading, setLoading] = useState(false);

  const onImportFile1 = (e) => {
    const [file] = e.target.files;
    const reader = new FileReader();

    reader.onload = (evt) => {
      const bstr = evt.target.result;
      const wb = XLSX.read(bstr, { type: "binary" });
      const wsname = wb.SheetNames[0];
      const ws = wb.Sheets[wsname];
      const data = XLSX.utils.sheet_to_json(ws, {
        header: 1,
        raw: false, // ให้เปลี่ยนค่าตัวเลข Excel เป็นวันที่ JS
        dateNF: "yyyy-mm-dd", // รูปแบบของวันที่ใน Excel
      });

      mapData1(data);
    };
    reader.readAsBinaryString(file);
  };

  const mapData1 = (data) => {
    const result = data.filter((item) => item[8]?.includes("BI"));
    createObjectList1(result);
  };

  const createObjectList1 = (list) => {
    const result = list.map((item) => ({
      date: item[1],
      product_name: item[2],
      customer: item[3],
      address: item[4],
      address_delivery: item[5],
      user: item[6],
      phone: item[7],
      bill_no: item[8],
      status: item[9],
      price: item[10],
    }));
    console.log("READ1", result);
    setDataList1(result);
  };

  const onImportFile2 = (e) => {
    const [file] = e.target.files;
    const reader = new FileReader();

    reader.onload = (evt) => {
      const bstr = evt.target.result;
      const wb = XLSX.read(bstr, { type: "binary" });
      const wsname = wb.SheetNames[0];
      const ws = wb.Sheets[wsname];
      const data = XLSX.utils.sheet_to_json(ws, { header: 1 });

      mapData2(data);
    };
    reader.readAsBinaryString(file);
  };

  const mapData2 = (data) => {
    const result = data.filter((item) => item[3]?.includes("BI"));
    createObjectList2(result);
  };

  const createObjectList2 = (list) => {
    // console.log("List", list);
    const result = list.map((item) => ({
      product_name: item[1],
      amount: item[2],
      bill_no: item[3],
      customer: item[4],
      category: item[5],
    }));
    // console.log("RESULT2", result);
    console.log("READ2", result);
    setDataList2(result);
  };

  const onImportFile3 = (e) => {
    const [file] = e.target.files;
    const reader = new FileReader();

    reader.onload = (evt) => {
      const bstr = evt.target.result;
      const wb = XLSX.read(bstr, { type: "binary" });
      const wsname = wb.SheetNames[0];
      const ws = wb.Sheets[wsname];
      const data = XLSX.utils.sheet_to_json(ws, { header: 1 });

      mapData3(data);
    };
    reader.readAsBinaryString(file);
  };

  const mapData3 = (data) => {
    const result = data.filter((item) => item[1]?.includes("BI"));
    // console.log("result", result);
    createObjectList3(result);
  };

  const createObjectList3 = (list) => {
    // console.log("List", list);
    const result = list.map((item) => ({
      date: item[0],
      bill_no: item[1],
      customer: item[2],
      amount: item[3],
      lot_by: item[4],
    }));
    // console.log("RESULT3", result);
    console.log("READ3", result);
    setDataList3(result);
  };

  useEffect(() => {
    if (dataList1.length > 0 && dataList2.length > 0 && dataList3.length > 0) {
      let newDataList2 = [];
      let list2 = [];

      // Loop For Checking Lot Data Map dataList2

      dataList2.forEach((obj2) => {
        // หา obj3 ที่มี bill_no ตรงกับ obj2.bill_no
        let matchingObj3 = dataList3.find((obj3) =>
          obj2.bill_no.includes(obj3.bill_no)
        );

        // ตรวจสอบว่าเจอ matchingObj3 หรือไม่
        if (matchingObj3) {
          if (obj2.product_name.includes("สลากออมสิน")) {
            newDataList2.push({ ...obj2, lot_by: matchingObj3.lot_by });
          } else {
            newDataList2.push({ ...obj2, lot_by: null });
          }
        } else {
          newDataList2.push({ ...obj2, lot_by: null });
        }
      });

      dataList1.forEach((obj1) => {
        // หา obj2 ที่มี bill_no ตรงกับ obj1.bill_no ใน newDataList2
        let matchingProducts = newDataList2.filter((obj2) =>
          obj1.bill_no.includes(obj2.bill_no)
        );

        // ถ้าไม่มี matchingProducts, ให้ products เป็น []
        if (matchingProducts.length === 0) {
          matchingProducts = [];
        }

        list2.push({
          bill_no: obj1.bill_no,
          data: obj1,
          products: matchingProducts,
        });
      });

      setDataShow((pre) => [...pre, ...list2]);
    }
  }, [dataList1, dataList2, dataList3]);

  useEffect(() => {
    console.log("RESULT ", dataShow);
  }, [dataShow]);

  // function isValidDate(date) {
  //   var datePattern = /^([12]\d{3}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01]))/;

  //   var matchArray = date.match(datePattern);
  //   if (matchArray == null) {
  //     return false;
  //   }

  //   var dateString = date.replace(/\D/g, "");

  //   var year = parseInt(dateString.substr(0, 4));
  //   var month = parseInt(dateString.substr(4, 2));
  //   var day = parseInt(dateString.substr(6, 2));

  //   var daysInMonth = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

  //   if (year % 400 === 0 || (year % 100 !== 0 && year % 4 === 0)) {
  //     daysInMonth[1] = 29;
  //   }

  //   if (month < 1 || month > 12 || day < 1 || day > daysInMonth[month - 1]) {
  //     return false;
  //   }
  //   return true;
  // }

  const errorMessage = ({ content }) => {
    messageApi.open({
      type: "error",
      content,
    });
  };

  const handleSubmitDataList = async () => {
    console.log("Data Submit", dataShow);
    setLoading(true);

    const count = dataShow.length / 5;
    let i = 0;
    let start = 0;
    let stop = 5;
    let dataSuccess = 0;
    let dataUnsuccess = 0;
    let dataAlreadyExists = 0;

    const Loop = () => {
      let newValue = dataShow.slice(
        start,
        stop < dataShow.length ? stop : dataShow.length
      );
      newValue.map(async (element) => {
        console.log(element);
        await baseAPI
          .get(`/city_pillar_shrine/shrine-event/auctions/billno`, {
            params: element,
            headers: {
              "x-access-token": user.token,
            },
          })
          .then(async (response) => {
            if (response.data.length === 0) {
              await baseAPI
                .post(`/city_pillar_shrine/shrine-event/auctions`, element, {
                  headers: {
                    "x-access-token": user.token,
                  },
                })
                .then((response) => {
                  dataSuccess++;
                })
                .catch((error) => {
                  dataUnsuccess++;
                  errorMessage({
                    content: "บันทึกบิลเลขที่ " + element.bill_no + " ล้มเหลว",
                  });
                });
            } else {
              dataAlreadyExists++;
            }

            // dataSuccess++;
          })
          .catch((error) => {
            // dataUnsuccess++;
            errorMessage({
              content: "บันทึกบิลเลขที่ " + element.bill_no + " ล้มเหลว",
            });
          });
      });
      i++;
      start += 5;
      stop += 5;
      setTimeout(() => {
        if (i < count) {
          Loop();
        } else {
          setLoading(false);
          Modal.success({
            title: "บันทึกแล้ว",
            content:
              "อัพโหลดสำเร็จ " +
              dataSuccess +
              " รายการ\nไม่สำเร็จ " +
              dataUnsuccess +
              " รายการ\nบิลซ้ำ " +
              dataAlreadyExists +
              " รายการ",

            centered: true,
          });
        }
      }, 3000);
    };

    Loop();
  };

  // const postData = async (data) => {
  //   //
  //   await baseAPI
  //     .post(`/city_pillar_shrine/shrine-event/auctions`, data, {
  //       headers: {
  //         "x-access-token": user.token,
  //       },
  //     })
  //     .then((response) => {
  //       // console.log(response);
  //       // Modal.success({
  //       //   centered: true,
  //       //   content: "เพิ่มร้านค้าสำเร็จ",
  //       // });
  //       // setLoading(false);
  //     })
  //     .catch((error) => {
  //       errorMessage({
  //         content: "บันทึกบิลเลขที่ " + data.bill_no + " ล้มเหลว",
  //       });
  //       // dispatch(addToken({}));
  //       // navigate("/login");
  //       // Modal.warning({
  //       //   title: "คำขอล้มเหลว",
  //       //   content: "Sessions Expired",
  //       //   centered: true,
  //       // });
  //       // setLoading(false);
  //     });
  // };

  return (
    <div>
      {/* <h3 style={{ color: "red" }}>ขั้นตอนการอัพโหลดรายการประมูล</h3>
      <p style={{ color: "red" }}>
        1. อัพโหลดรายการประมูล และตามด้วยรายการสินค้า
        เมื่อแสดงรายการขึ้นถูกต้องแล้ว กดบันทึกทั้งหมด
      </p>
      <p style={{ color: "red" }}>
        2. รอจนบันทึกเสร็จสิ้น แล้วค่อยอัพโหลดรายการ สลากออมสิน เป็นลำดับสุดท้าย
      </p> */}
      <Divider orientation="left">รายการประมูล</Divider>
      <div
        style={{
          flexDirection: "row",
          display: "flex",
          alignContent: "center",

          //   padding: 8,
        }}
      >
        <input type="file" onChange={onImportFile1} />
        <Text strong>อัพโหลดไฟล์ (xlsx)</Text>
      </div>
      <Divider orientation="left">รายการสินค้า</Divider>
      <div
        style={{
          flexDirection: "row",
          display: "flex",
          alignContent: "center",

          //   padding: 8,
        }}
      >
        <input type="file" onChange={onImportFile2} />
        <Text strong>อัพโหลดไฟล์ (xlsx)</Text>
      </div>
      <Divider orientation="left">รายการสลากออมสิน</Divider>
      <div
        style={{
          flexDirection: "row",
          display: "flex",
          alignContent: "center",

          //   padding: 8,
        }}
      >
        <input type="file" onChange={onImportFile3} />
        <Text strong>อัพโหลดไฟล์ (xlsx)</Text>
      </div>
      <Divider />
      {dataShow.length > 0 ? (
        <>
          <div
            style={{
              justifyContent: "space-between",
              alignItems: "center",
              display: "flex",
            }}
          >
            <Text strong>จำนวนบิลทั้งหมด {dataShow.length} บิล</Text>
            <Button type="primary" onClick={handleSubmitDataList}>
              บันทึกทั้งหมด
            </Button>
          </div>
          {dataShow.map((item, index) => (
            <AuctionList key={index} data={item} />
          ))}
        </>
      ) : null}
      <Spin spinning={loading} size="large" fullscreen />
      {contextHolder}
    </div>
  );
}
