import React, { useEffect, useState } from "react";
import { Button, Form, Typography, Modal, Radio, Space, Divider } from "antd";
import baseAPI from "../../../api/baseAPI";
import { useSelector } from "react-redux";
import moment from "moment";

const { Text } = Typography;

export default function InstallationManage({
  open,
  data,
  // teamList,
  onClose,
  onSubmit,
}) {
  const user = useSelector((state) => state.token);
  const [valueSelected, setValueSelected] = useState(null);
  const [teamList, setTeamList] = useState([]);
  const [newData, setNewData] = useState({});

  useEffect(() => {
    fetchTeamMaintenance();
  }, [open]);

  const fetchTeamMaintenance = async () => {
    await baseAPI
      .get("/city_pillar_shrine/maintenance-team", {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        setTeamList(response.data);
        // console.log(response.data);
        // setLoading(false);
        //
      })
      .catch((error) => {
        // dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        // setLoading(false);
      });
  };

  const handleSubmit = () => {
    onSubmit(newData, valueSelected);
  };

  const handleClose = () => {
    onClose(false);
  };

  const onChange = (event) => {
    const user = event.target.data;
    // console.log(event.target.data);
    setNewData({
      id: data.id,
      maintenance_status_id: 2,
      maintenance_by_user_id: user.id,
      maintenance_name: user.firstname,
      maintenance_lastname: user.lastname,
      maintenance_nickname: user.nickname,
      maintenance_phone: user.phone,
    });
    setValueSelected(event.target.value);
  };

  return (
    <Modal
      title="เลือกทีมติดตั้ง"
      // width={1000}
      centered={true}
      open={open}
      onOk={handleSubmit}
      closeIcon={false}
      // onCancel={handleClose}
      footer={[
        <Button
          key="close"
          // href="https://google.com"
          // loading={loading}
          onClick={handleClose}
        >
          ยกเลิก
        </Button>,
        <Button
          disabled={!valueSelected}
          key="submit"
          type="primary"
          onClick={handleSubmit}
        >
          บันทึก
        </Button>,
      ]}
    >
      <Divider />
      <div>
        <Radio.Group onChange={onChange} value={valueSelected}>
          <Space direction="vertical">
            {teamList.map((item, index) => (
              <div style={{ marginTop: 10 }} key={index}>
                <Radio value={item.id} data={item}>
                  <div style={{ flexDirection: "column", display: "flex" }}>
                    <Text strong>
                      {item.firstname} {item.lastname} ( {item.nickname} )
                    </Text>
                    <Text type="secondary">
                      จำนวนงาน:{" "}
                      {item.maintenance_by_user_id === null ? 0 : item.job}
                    </Text>
                  </div>
                </Radio>
              </div>
            ))}
          </Space>
        </Radio.Group>
        {/* <Form
            form={form}
            labelCol={{
              span: 8,
            }}
            wrapperCol={{
              span: 18,
            }}
            layout="horizontal"
            onFinish={handleSubmit}
            onFinishFailed={onFinishFailed}
          >
            <Form.Item
              name="fullname"
              label="ชื่อช่าง / ทีมติดตั้ง"
              rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
            >
              <Input name="fullname" />
            </Form.Item>
            <Form.Item name="address" label="ที่อยู่">
              <Input name="address" />
            </Form.Item>
            <Form.Item
              name="phone"
              label="เบอร์โทรศัพท์"
              rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
            >
              <Input name="phone" />
            </Form.Item>
          </Form> */}
      </div>
    </Modal>
  );
}
