import { Divider, Space, Typography } from "antd";
import moment from "moment";
import React from "react";
import { currencyFormatTH } from "../../../utils/numberFormat";

const { Text } = Typography;

export default function OrderItem({ data, index }) {
  return (
    <>
      <div
        style={{
          flexDirection: "row",
          justifyContent: "space-between",
          display: "flex",
        }}
      >
        <div style={{ flexDirection: "column", display: "flex" }}>
          <Text type="secondary" style={{ fontSize: 12 }}>
            เลขที่ {data.order_number}
          </Text>
          <Text strong>ร้าน {data.storename}</Text>
          <Text type="secondary" style={{ fontSize: 12 }}>
            ผู้ขาย {data.user_name + " " + data.user_lastname}
          </Text>
          <Text style={{ fontSize: 12 }}>
            {data.payment_by_id === 1 ? "เงินสด" : "เงินโอน"}
          </Text>
        </div>
        <div
          style={{
            flexDirection: "column",
            display: "flex",
            justifyContent: "space-between",
            alignItems: "end",
          }}
        >
          <Text type="secondary" style={{ fontSize: 12 }}>
            {moment(data.datetime).format("LL")}
          </Text>
          <Text strong>{currencyFormatTH(data.total_price)}</Text>
        </div>
      </div>
      <hr />
    </>
  );
}
