import React from "react";
import { List } from "antd";
import EligiblePersonItem from "./EligiblePersonItem";

export default function EligiblePersonList({ data }) {
  console.log("EligiblePersonList", data);
  return (
    <List
      pagination={{
        onChange: (page) => {
          console.log(page);
        },
        pageSize: 10,
      }}
      itemLayout="horizontal"
      dataSource={data}
      renderItem={(item, index) => (
        <EligiblePersonItem
          data={item}
          //   onClickPrint={onPrintReceipt}
          //   onClickItem={onClickItem}
        />
      )}
    />
  );
}
