import React from "react";
import { Button, Modal, Form, Input } from "antd";

export default function AddRoadModal({ open, onClose, onSubmit }) {
  const [form] = Form.useForm();
  const handleClose = () => {
    onClose(false);
  };
  const handleSubmit = (data) => {
    onSubmit(data);
  };

  const onFinishFailed = (e) => {
    console.log("Failure", e);
  };
  return (
    <Modal
      title="เพิ่มชื่อถนน"
      centered={true}
      // width={1000}
      open={open}
      //   onOk={handleSubmit}
      closeIcon={false}
      onCancel={handleClose}
      footer={[
        <Button key="close" onClick={handleClose}>
          ยกเลิก
        </Button>,
        <Button
          key="submit"
          htmlType="submit"
          type="primary"
          onClick={form.submit}
        >
          บันทึก
        </Button>,
      ]}
    >
      <Form
        id="form"
        onFinish={handleSubmit}
        onFinishFailed={onFinishFailed}
        layout={"vertical"}
        form={form}
      >
        <Form.Item name="road" label="ชื่อถนน">
          <Input placeholder="เพิ่มชื่อถนน" />
        </Form.Item>
      </Form>
    </Modal>
  );
}
