import { Button, Divider, Tabs } from "antd";
import React, { useState } from "react";
import Auction from "./Auction";
import AuctionList from "./auction_list/Main";

export default function Main() {
  const [checkAuctionRefresh, setCheckAuctionRefresh] = useState(1);
  const onChange = (key) => {
    console.log("onChange", key);
    setCheckAuctionRefresh(key);
  };
  const items = [
    {
      key: 1,
      label: "อัพโหลดไฟล์ประมูล",
      children: <Auction />,
    },
    {
      key: 2,
      label: "รายการบิลประมูล",
      children: <AuctionList refresh={checkAuctionRefresh} />,
    },

    // {
    //   key: "1",
    //   label: "รายการทั้งหมด",
    //   children: <AuctionList />,
    // },
  ];
  return (
    <>
      <Tabs defaultActiveKey="1" items={items} onChange={onChange} />
    </>
  );
}
