import { Descriptions } from "antd";
import React from "react";

export default function CustomerDetail({ data }) {
  return (
    <div>
      <Descriptions>
        <Descriptions.Item label="ชื่อร้าน">{data.storename}</Descriptions.Item>
        {data.fullname && (
          <Descriptions.Item label="ชื่อสกุล">
            {data.fullname}
          </Descriptions.Item>
        )}
        <Descriptions.Item label="โทรศัพท์">{data.phone}</Descriptions.Item>
        {data.line && (
          <Descriptions.Item label="ไลน์">{data.line}</Descriptions.Item>
        )}
        {data.address && (
          <Descriptions.Item label="ที่อยู่">{data.address}</Descriptions.Item>
        )}
      </Descriptions>
      {/* <Divider /> */}
    </div>
  );
}
