import React, { useEffect, useState } from "react";
import { Switch, Typography, List, Space, Tag } from "antd";
import { Link } from "react-router-dom";
import { currencyFormatTH } from "../../../utils/numberFormat";
import { useSelector } from "react-redux";

const { Text } = Typography;

export default function ProductItem({
  data,
  onEdit,
  onRemove,
  onStatusChange,
}) {
  const user = useSelector((state) => state.token);

  const handleEdit = () => {
    console.log(data);
    onEdit(data);
  };
  const handleChangeStatus = (value) => {
    const item = {
      ...data,
      active: value,
    };
    onStatusChange(item);
  };

  //   const handleRemove = () => {
  //     onRemove(data);
  //   };
  return (
    <List.Item
      actions={[
        <Text type={data.amount < 10 && "danger"} style={{ fontSize: 12 }}>
          คงเหลือ: {data.amount}/{data.total_amount}
        </Text>,
        // <Switch
        //   onChange={handleChangeStatus}
        //   checkedChildren="ขาย"
        //   unCheckedChildren="ไม่ขาย"
        //   defaultChecked={data.active}
        // />,

        <Link key="edit" onClick={handleEdit}>
          แก้ไข
        </Link>,

        // <Link key="remove" onClick={handleRemove}>
        //   ลบ
        // </Link>,
      ]}
    >
      <List.Item.Meta
        // avatar={
        //   <Avatar
        //     src={`https://xsgames.co/randomusers/avatar.php?g=pixel&key=${1}`}
        //   />
        // }
        title={
          <Text strong style={{ fontSize: 12 }}>
            {data?.name}
          </Text>
        }
        description={
          <Space direction="vertical">
            <Text style={{ fontSize: 12 }}>
              {currencyFormatTH(data?.price)}
            </Text>
            <Text type="secondary" style={{ fontSize: 12 }}>
              {data?.type_name}
            </Text>
            <Tag color={data.active ? "green" : "gray"}>
              {data.active ? "ใช้งาน" : "ไม่ใช้งาน"}{" "}
            </Tag>
          </Space>
        }
      />
    </List.Item>
  );
}
