import React from "react";
import ToiJeeListMain from "./ToiJeeListMain";
import { Tabs } from "antd";
import CheckEligiblePersonMain from "./CheckEligiblePersonMain";

export default function Main() {
  const items = [
    {
      key: 1,
      label: "รายการบิลโต่ยจี๊",
      children: <ToiJeeListMain />,
    },
    {
      key: 2,
      label: "รายชื่อผู้มีสิทธิ์เสี่ยงทาย",
      children: <CheckEligiblePersonMain />,
    },
  ];

  // const onChange = (key) => {
  //   console.log(key);
  // };
  return (
    <div>
      <Tabs defaultActiveKey="1" items={items} />
    </div>
  );
}
