import React, { useEffect, useState } from "react";
import { Typography, DatePicker, Form, Modal, Tabs } from "antd";
// import dayjs from "dayjs";
import baseAPI from "../../../api/baseAPI";
import { useSelector } from "react-redux";
import EligiblePersonList from "./EligiblePersonList";
import EligiblePersonExcel from "./report/EligiblePersonExcel";
import moment from "moment";

const { RangePicker } = DatePicker;
const { Text } = Typography;

export default function CheckListMain() {
  const user = useSelector((state) => state.token);
  const [dataSource, setDataSource] = useState([]);
  const [start, setStart] = useState("");
  const [end, setEnd] = useState("");

  const handleChangeDate = (date, dateString) => {
    console.log("DATE1", dateString[0]);
    console.log("DATE2", dateString[1]);
    setStart(moment(`${dateString[0]}-01-01`).add(543, "years").format("YYYY"));
    setEnd(moment(`${dateString[1]}-01-01`).add(543, "years").format("YYYY"));
    let params = {
      yearStart: dateString[0],
      yearEnd: dateString[1],
    };

    fetchEligiblePerson(params);
  };

  useEffect(() => {
    console.log("START", start);
    console.log("END", end);
  }, [start, end]);

  const fetchEligiblePerson = async (params) => {
    await baseAPI
      .get(`/city_pillar_shrine//toi-jee-list/eligible-persons`, {
        params,
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((res) => {
        console.log(res.data);
        setDataSource(res.data);
      })
      .catch((err) => {
        Modal.error({
          title: "ไม่สามารถโหลดข้อมูลได้",
          content: err.message,
          centered: true,
        });
      });
  };

  const items = [
    {
      key: 1,
      label: "มีสิทธิ์เสี่ยงทาย",
      children: (
        <EligiblePersonList
          data={dataSource.filter((item) => item.code === null)}
        />
      ),
    },
    {
      key: 2,
      label: "ไม่มีสิทธิ์เสี่ยงทาย",
      children: (
        <EligiblePersonList
          data={dataSource.filter((item) => item.code != null)}
        />
      ),
    },
  ];

  return (
    <div>
      <Form
        labelCol={{
          span: 8,
        }}
        wrapperCol={{
          span: 16,
        }}
        style={{
          maxWidth: "400px",
          width: "350px",
        }}
        autoComplete="off"
      >
        <Form.Item
          label="เริ่มจากปี... ถึงปี"
          name="year"
          rules={[
            {
              required: true,
              message: "ต้องไม่เว้นว่าง!",
            },
          ]}
        >
          <RangePicker
            format="YYYY"
            picker="year"
            onChange={handleChangeDate}
          />
        </Form.Item>
        <Form.Item label="ปี พ.ศ." name="buddish">
          <Text strong>
            {start} ถึง {end}
          </Text>
        </Form.Item>
      </Form>
      <div>
        <EligiblePersonExcel data={dataSource} />
        <Tabs defaultActiveKey="1" items={items} />
      </div>
    </div>
  );
}
