import {
  Button,
  DatePicker,
  Divider,
  Form,
  Image,
  InputNumber,
  Modal,
  Space,
  Typography,
} from "antd";
import React, { useEffect, useState } from "react";
import Resizer from "react-image-file-resizer";

const { Text } = Typography;

export default function AddEventModal({ open, onClose, onSubmit }) {
  const [data, setData] = useState({});
  const [imgFile, setImgFile] = useState(null);
  const [form] = Form.useForm();

  const handleClose = () => {
    onClose(false);
  };

  const handleSubmit = () => {
    // console.log("DATA", data);
    onSubmit({ ...data, image: imgFile });
  };

  useEffect(() => {
    // setProducts(data);
  }, []);

  const onFinishFailed = (errorInfo) => {
    console.log("Failed:", errorInfo);
  };

  const onChangeYear = (date, dateString) => {
    setData({ ...data, year: dateString });
    // console.log("Date", dateString);
  };

  const handleChangeTableAmount = (name, amount) => {
    setData({ ...data, [name]: amount });
  };

  const onChangeFile = async (e) => {
    const file = e.target.files[0];
    const image = await resizeFile(file);
    // console.log(image);
    setImgFile(image);
  };

  const resizeFile = (file) =>
    new Promise((resolve) => {
      Resizer.imageFileResizer(
        file,
        1280,
        800,
        "JPEG",
        100,
        0,
        (uri) => {
          resolve(uri);
        },
        "base64"
      );
    });

  return (
    <Modal
      title="เพิ่มปีที่จัดงาน"
      centered={true}
      // width={1000}
      open={open}
      //   onOk={handleSubmit}
      closeIcon={false}
      onCancel={handleClose}
      footer={[
        <Button
          key="submit"
          type="primary"
          //   disabled={data?.order_status_id !== 1}
          onClick={handleSubmit}
        >
          บันทึก
        </Button>,
        <Button key="close" onClick={handleClose}>
          ยกเลิก
        </Button>,
      ]}
    >
      <div style={{ padding: 16 }}>
        <Form
          form={form}
          labelCol={{
            span: 8,
          }}
          wrapperCol={{
            span: 18,
          }}
          layout="horizontal"
          onFinish={handleSubmit}
          onFinishFailed={onFinishFailed}
        >
          <Form.Item
            name="year"
            label="ปีที่จัดงาน"
            rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
          >
            <DatePicker
              style={{ width: "100%" }}
              name="year"
              onChange={onChangeYear}
              size="large"
              picker="year"
            />
          </Form.Item>
          {/* {data.order_type_id === 1 ? ( */}
          {/* <Form.Item
            name="table_vip_amount"
            label="จำนวนโต๊ะ VIP"
            rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
          >
            <InputNumber
              size="large"
              name="table_vip_amount"
              style={{ width: "100%" }}
              formatter={(value) =>
                `${value}`.replace(/\B(?=(\d{3})+(?!\d))/g, ",")
              }
              onChange={(e) => handleChangeTableAmount("table_vip_amount", e)}
            />
          </Form.Item> */}
          <Form.Item
            name="table_amount"
            label="จำนวนโต๊ะ"
            rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
          >
            <InputNumber
              size="large"
              name="table_amount"
              style={{ width: "100%" }}
              formatter={(value) =>
                `${value}`.replace(/\B(?=(\d{3})+(?!\d))/g, ",")
              }
              onChange={(e) => handleChangeTableAmount("table_amount", e)}
            />
          </Form.Item>
        </Form>

        <div style={{ justifyContent: "center", display: "flex" }}>
          <Space direction="vertical" align="center">
            <Text strong>รูปภาพแผนผังงาน</Text>
            <input type="file" onChange={onChangeFile} />
            {imgFile ? (
              <div style={{ justifyContent: "center", display: "flex" }}>
                <Image width={100} src={imgFile} />
              </div>
            ) : null}
          </Space>
        </div>
        <Divider />
      </div>
    </Modal>
  );
}
