import React from "react";
import { Space, Typography } from "antd";
import {
  currencyFormat,
  currencyFormatTH,
} from "../../../../utils/numberFormat";

const { Text } = Typography;

export default function ProductNewtem({ data }) {
  return (
    <div
      style={{
        flexDirection: "row",
        display: "flex",
        justifyContent: "space-between",
      }}
    >
      <Space>
        <Text>{data.name}</Text>
        <Text type="secondary">x{data.amount}</Text>
      </Space>
      <Space align="right">
        <Text>{currencyFormatTH(data.price * data.amount)}</Text>
      </Space>
    </div>
  );
}
