import { List } from "antd";
import React from "react";
import OrderHistoryItem from "./OrderHistoryItem";

export default function OrderHistoryList({ data, onClickItem, onConfirm }) {
  const handleClickItem = (data) => {
    onClickItem(data);
  };
  return (
    <div>
      <List
        // size="small"
        pagination={{
          onChange: (page) => {
            console.log(page);
          },
          pageSize: 10,
        }}
        dataSource={data}
        renderItem={(item, index) =>
          item.order_status_id === 1 && (
            <OrderHistoryItem
              data={item}
              index={index}
              onClick={handleClickItem}
              onConfirm={onConfirm}
            />
          )
        }
      />
    </div>
  );
}
