import React, { useEffect, useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import {
  Typography,
  Divider,
  Modal,
  message,
  Spin,
  Button,
  DatePicker,
  Space,
  Tabs,
} from "antd";

import moment from "moment";
import AuctionList from "./AuctionList";
import AuctionListDetailModal from "./AuctionListDetailModal";
import AomsinLotList from "./AomsinLotList";
import { Receipt } from "./pdf/Receipt";
import pdfMake from "pdfmake/build/pdfmake";
import pdfFonts from "pdfmake/build/vfs_fonts";
import AuctionListExcel from "./report/AuctionListExcel";
import baseAPI from "../../../../api/baseAPI";
import AomsinLotDetailModal from "./AomsinLotDetailModal";
import LotteryList from "./LotteryList";
import LotteryDetailModal from "./LotteryDetailModal";

pdfMake.vfs = pdfFonts.pdfMake.vfs;

//ต้องระบุตามชื่อของ ไฟล์ font
pdfMake.fonts = {
  THSarabunNew: {
    normal: "THSarabunNew.ttf",
    bold: "THSarabunNew Bold.ttf",
    italics: "THSarabunNew Italic.ttf",
    bolditalics: "THSarabunNew Bold Italic.ttf",
  },
  AngsanaNew: {
    normal: "AngsanaNew.ttf",
    bold: "AngsanaNew Bold.ttf",
    italics: "AngsanaNew Italic.ttf",
    bolditalics: "AngsanaNew Bold Italic.ttf",
  },
  Roboto: {
    normal: "Roboto-Regular.ttf",
    bold: "Roboto-Medium.ttf",
    italics: "Roboto-Italic.ttf",
    bolditalics: "Roboto-MediumItalic.ttf",
  },
};

export default function Main({ refresh }) {
  const user = useSelector((state) => state.token);
  const [auctionList, setAuctionList] = useState([]);
  const [openDetailListModal, setOpenDetailListModal] = useState(false);
  const [openAomsinDetailModal, setOpenAomsinDetailModal] = useState(false);
  const [openLotteryModal, setOpenLotteryModal] = useState(false);
  const [dataSelected, setDataSelected] = useState({});
  const [aomsinLots, setAomsinLots] = useState([]);
  const [lottery, setLottery] = useState([]);
  const [years, setYears] = useState(0);

  useEffect(() => {
    if (refresh === 2) {
      getAuctionList(moment().format("YYYY"));
      // console.log("REFRESH SUCCESSFUL");
    }
  }, [refresh]);

  const getAuctionList = async (year) => {
    // setLoading(true);
    await baseAPI
      .get(`/city_pillar_shrine/shrine-event/auctions`, {
        params: { year },
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        console.log(response.data);
        setAuctionList(response.data);
        findUserAomsinLot(response.data);
      })
      .catch((error) => {
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        // setLoading(false);
      });
  };

  const findUserAomsinLot = (data) => {
    let aomsins = [];
    let lottery = [];

    data.map((item) => {
      const result = item?.products.filter(
        (product) =>
          product.product_productName === "สลากออมสิน" &&
          product.product_productAmount > 0
      );
      aomsins.push(...result);
    });

    data.map((item) => {
      const result = item?.products.filter(
        (product) =>
          product.product_productName === "ล็อตเตอรี่" &&
          product.product_productAmount > 0
      );
      lottery.push(...result);
    });

    // console.log("ARRAY", arr);
    setAomsinLots(aomsins);
    setLottery(lottery);
  };

  const onChangeYear = (_, dateString) => {
    // console.log("onChangeYear", dateString);
    setYears(dateString);
    getAuctionList(dateString);
  };

  const handlePrintReceipt = async (data) => {
    const findDataLotBy = data.products.filter(
      (product) => product.product_productName === "สลากออมสิน"
    );

    data.product_productLotBy = findDataLotBy[0].product_productLotBy;
    // console.log("DATA LOT BY", data.product_productLotBy);

    const products = [];
    for (let i = 0; i < 12; i++) {
      if (data.products[i]) {
        const result = [
          {
            text: i + 2,
            alignment: "center",
            style: "textBody",
          },
          {
            text: data.products[i].product_productName,
            alignment: "left",
            style: "textBody",
          },
          {
            text: data.products[i].product_productAmount,
            alignment: "center",
            style: "textBody",
          },
          {
            text: "",
            alignment: "center",
            style: "textBody",
          },
          {
            text: "",
            alignment: "center",
            style: "textBody",
          },
        ];
        products.push(result);
      } else {
        // console.log(i, "false");
        const result = [
          {
            text: i + 2,
            alignment: "center",
            style: "textBody",
          },
          {
            text: "",
            alignment: "left",
            style: "textBody",
          },
          {
            text: "",
            alignment: "center",
            style: "textBody",
          },
          {
            text: "",
            alignment: "center",
            style: "textBody",
          },
          {
            text: "",
            alignment: "center",
            style: "textBody",
          },
        ];
        products.push(result);
      }
    }
    // console.log("PRODUCTS", products);

    const result = await Receipt({ data, products });
    pdfMake.createPdf(result).open();
  };

  // const handlePrint = async (data) => {};

  const handleClickItem = (data) => {
    // console.log("handleClickItem", data);
    setDataSelected(data);
    setOpenDetailListModal(true);
  };

  const handleClickAomsinLotItem = (data) => {
    // console.log("handleClickAomsinLotItem", data);
    setDataSelected(data);
    setOpenAomsinDetailModal(true);
  };

  const handleClickLotteryItem = (data) => {
    setDataSelected(data);
    setOpenLotteryModal(true);
  };

  const handleCancelAomsinLotOrLottery = async (data) => {
    console.log("handleCancelAomsinLot", data);
    setOpenAomsinDetailModal(false);
    setOpenLotteryModal(false);
    console.log(data);
    // setLoading(true);
    await baseAPI
      .put(`/city_pillar_shrine/shrine-event/auctions/cancel`, data, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        Modal.success({ content: "อัพเดตข้อมูลสำเร็จ", centered: true });
        // fetchUser();
        getAuctionList(years);
        // const newState = aomsinLots.map((obj) => {
        //   if (obj.id === data.id) {
        //     return { ...obj, ...data };
        //   }
        //   return obj;
        // });
        // console.log("NEW ARRAY", newState);
        // setAomsinLots(newState);
        // setUsers(newState);
        // setLoading(false);
      })
      .catch((error) => {
        // dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        // setLoading(false);
      });
  };

  const handleSubmitPayment = (data) => {
    setDataSelected(data);

    Modal.confirm({
      title: "ยืนยันการชำระ",
      content: `ต้องการยืนยันการชำระ บิลเลขที่ ${data.bill_no}`,
      centered: true,
      onOk() {
        updatePaymentStatus(data);
      },
      onCancel() {
        console.log("Cancel");
      },
    });
  };

  const updatePaymentStatus = async (data) => {
    console.log(data);
    await baseAPI
      .put(`/city_pillar_shrine/shrine-event/auctions/status`, data, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        Modal.success({ content: "อัพเดตข้อมูลสำเร็จ", centered: true });
        getAuctionList(years);
      })
      .catch((error) => {
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
      });
  };

  const items = [
    {
      key: "1",
      label: "ยังไม่ชำระ",
      children: (
        <AuctionList
          data={auctionList.filter((item) => item.status === "ยังไม่ชำระ")}
          onPrint={handlePrintReceipt}
          onClickItem={handleClickItem}
          onSubmit={handleSubmitPayment}
        />
      ),
    },
    {
      key: "2",
      label: "ชำระแล้ว",
      children: (
        <AuctionList
          data={auctionList.filter((item) => item.status === "ชำระแล้ว")}
          onPrint={handlePrintReceipt}
          onClickItem={handleClickItem}
          // onSubmit={handleSubmitStatus}
        />
      ),
    },
    {
      key: "3",
      label: "สลากออมสิน",
      children: (
        <AomsinLotList
          data={aomsinLots}
          onClickItem={handleClickAomsinLotItem}
        />
      ),
    },
    {
      key: "4",
      label: "ล็อตเตอรี่",
      children: (
        <LotteryList data={lottery} onClickItem={handleClickLotteryItem} />
      ),
    },
  ];

  return (
    <>
      <div style={{ justifyContent: "center", display: "flex" }}>
        <Space align="center">
          <h4>เลือกปี</h4> <DatePicker picker="year" onChange={onChangeYear} />
        </Space>
      </div>
      <Divider />
      <AuctionListExcel
        data={auctionList}
        aomsinLots={aomsinLots}
        lottery={lottery}
      />

      <Tabs defaultActiveKey="1" items={items} />

      <AuctionListDetailModal
        open={openDetailListModal}
        onClose={setOpenDetailListModal}
        data={dataSelected?.products}
      />

      <AomsinLotDetailModal
        open={openAomsinDetailModal}
        onClose={setOpenAomsinDetailModal}
        data={dataSelected}
        onCancel={handleCancelAomsinLotOrLottery}
      />

      <LotteryDetailModal
        open={openLotteryModal}
        onClose={setOpenLotteryModal}
        data={dataSelected}
        onCancel={handleCancelAomsinLotOrLottery}
      />
    </>
  );
}
