import { List } from "antd";
import React from "react";
import OrderTicketItem from "./OrderTicketItem";

export default function OrderTicketList({ data, onClickEdit, onClickItem }) {
  return (
    <div>
      <List
        // size="small"
        pagination={{
          onChange: (page) => {
            console.log(page);
          },
          pageSize: 10,
        }}
        dataSource={data}
        renderItem={(item, index) =>
          item.order_status_id === 1 && (
            <OrderTicketItem
              data={item}
              index={index}
              onClick={onClickItem}
              onEdit={onClickEdit}
            />
          )
        }
      />
    </div>
  );
}
