import React, { useEffect, useState } from "react";
import ProductList from "./ProductList";
import { Button, DatePicker, Divider, Modal, Space, Tabs } from "antd";
import { PlusOutlined } from "@ant-design/icons";
import AddProductModal from "./AddProductModal";
import EditProductModal from "./EditProductModal";

import baseAPI from "../../../api/baseAPI";
import { useDispatch, useSelector } from "react-redux";
import Loading from "../../../utils/Loading";
import { useNavigate } from "react-router-dom";
import { addToken } from "../../../redux/reduxSlice";
import ProductStock from "./report/ProductStock";
import AddBillTypeModal from "./AddBillTypeModal";
import AddProductTypeModal from "./AddProductTypeModal";
import dayjs from "dayjs";
import moment from "moment";

export default function Main() {
  const user = useSelector((state) => state.token);
  const dispatch = useDispatch();
  const navigate = useNavigate();
  // console.log("USER", user);
  const [openAddProductModal, setOpenAddProductModal] = useState(false);
  const [openAddBillTypeModal, setOpenAddBillTypeModal] = useState(false);
  const [openAddProductTypeModal, setOpenAddProductTypeModal] = useState(false);
  const [openEditModal, setOpenEditModal] = useState(false);
  const [dataEdit, setDataEdit] = useState({});
  const [products, setProducts] = useState([]);
  const [orderType, setOrderType] = useState([]);
  const [productsType, setProductsType] = useState([]);
  const [dateSelect, setDateSelect] = useState("");
  const [year, setYear] = useState("");

  const [loading, setLoading] = useState(false);

  useEffect(() => {
    // fetchData();
    fetchBillType();
    fetchProductType();
  }, []);

  useEffect(() => {
    const date = new Date();
    let month = date.getMonth() + 1;
    let year = date.getFullYear();
    if (month > 11) {
      setYear(year + 1);
      setDateSelect(moment().add(1, "years").format("YYYY-MM-DD"));
    } else {
      setYear(year);
      setDateSelect(moment().format("YYYY-MM-DD"));
    }
  }, []);

  useEffect(() => {
    fetchData(year);
  }, [year]);

  const fetchData = async (year) => {
    setLoading(true);
    await baseAPI
      .get(`/city_pillar_shrine/products`, {
        params: { year },
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((result) => {
        setProducts(result.data);
        setLoading(false);
      })
      .catch((error) => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
  };

  const fetchBillType = async () => {
    setLoading(true);
    await baseAPI
      .get(`/city_pillar_shrine/order-type`, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((result) => {
        setOrderType(result.data);
        setLoading(false);
      })
      .catch((error) => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
  };

  const fetchProductType = async () => {
    setLoading(true);
    await baseAPI
      .get(`/city_pillar_shrine/products/type`, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((result) => {
        setProductsType(result.data);
        setLoading(false);
      })
      .catch((error) => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
  };

  const handleAddProduct = async (data) => {
    setOpenAddProductModal(false);
    setLoading(true);
    await baseAPI
      .post(`/city_pillar_shrine/products`, data, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        Modal.success({ content: "เพิ่มรายการสินค้าสำเร็จ", centered: true });
        fetchData();
      })
      .catch((error) => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
  };

  const handleFinishEdit = async (data) => {
    console.log("EDIT SUBMIT", data);
    setOpenEditModal(false);
    setLoading(true);
    await baseAPI
      .put(`/city_pillar_shrine/products`, data, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        Modal.success({ content: "แก้ไขรายการสินค้าสำเร็จ", centered: true });
        fetchData();
      })
      .catch((error) => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
  };

  const handleChangeStatus = async (data) => {
    setLoading(true);
    await baseAPI
      .put(`/city_pillar_shrine/products/status`, data, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        //   Modal.success({ content: "แก้ไขรายการสินค้าสำเร็จ", centered: true });
        setLoading(false);
      })
      .catch((error) => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
  };

  const handleDeleteProduct = async (data) => {
    // setOpenAddProductModal(false);
    setLoading(true);
    await baseAPI
      .delete(`/city_pillar_shrine/products/${data.id}`, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        Modal.success({ content: "ลบรายการสำเร็จ", centered: true });
        setLoading(false);
      })
      .catch((error) => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
    const result = products.filter((item) => item.id !== data.id);
    setProducts(result);
  };

  const handleClickAddItem = () => {
    setOpenAddProductModal(true);
  };

  const handleClickEditItem = (data) => {
    setDataEdit(data);
    setOpenEditModal(true);
  };

  const handleRemoveItem = (data) => {
    // console.log(data);
    setOpenEditModal(false);
    Modal.confirm({
      title: "ลบสินค้า",
      content: "ต้องการลบรายการสินค้านี้หรือไม่?",
      centered: true,
      okText: "ลบ",
      cancelText: "ยกเลิก ",
      onOk: () => {
        handleDeleteProduct(data);
      },
    });
  };

  const deleteBillType = async (id) => {
    // setOpenAddProductModal(false);
    setLoading(true);
    await baseAPI
      .delete(`/city_pillar_shrine/order-type/${id}`, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        Modal.success({ content: "ลบรายการสำเร็จ", centered: true });
        setLoading(false);
      })
      .catch((error) => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
    const result = orderType.filter((item) => item.id !== id);
    setOrderType(result);
  };

  const handleClickAddBillType = () => {
    // console.log();
    setOpenAddBillTypeModal(true);
  };

  const handleClickAddProductType = () => {
    setOpenAddProductTypeModal(true);
  };

  const handleAddBillType = async (data) => {
    setOpenAddBillTypeModal(false);
    setLoading(true);
    await baseAPI
      .post(
        `/city_pillar_shrine/order-type`,
        { data },
        {
          headers: {
            "x-access-token": user.token,
          },
        }
      )
      .then((response) => {
        Modal.success({ content: "เพิ่มประเภทบิลสำเร็จ", centered: true });
        fetchBillType();
      })
      .catch((error) => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
  };

  const handleDeleteBillType = (data) => {
    setOpenAddBillTypeModal(false);
    Modal.confirm({
      title: "ลบสินค้า",
      content: "ต้องการลบประเภทบิลนี้หรือไม่?",
      centered: true,
      okText: "ลบ",
      cancelText: "ยกเลิก ",
      onOk: () => {
        deleteBillType(data);
      },
    });
  };

  const handleSubmitAddProductType = async (data) => {
    console.log(data);
    setOpenAddProductTypeModal(false);
    setLoading(true);
    await baseAPI
      .post(
        `/city_pillar_shrine/products/type`,
        { data },
        {
          headers: {
            "x-access-token": user.token,
          },
        }
      )
      .then((response) => {
        Modal.success({ content: "เพิ่มประเภทสินค้าสำเร็จ", centered: true });
        fetchProductType();
      })
      .catch((error) => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
  };

  const handleDeleteProductType = async (data) => {
    setOpenAddProductTypeModal(false);
    Modal.confirm({
      title: "ลบสินค้า",
      content: "ต้องการลบประเภทบิลนี้หรือไม่?",
      centered: true,
      okText: "ลบ",
      cancelText: "ยกเลิก ",
      onOk: () => {
        deleteProductType(data);
      },
    });
  };

  const deleteProductType = async (id) => {
    // setOpenAddProductModal(false);
    setLoading(true);
    await baseAPI
      .delete(`/city_pillar_shrine/products/type/${id}`, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        Modal.success({ content: "ลบรายการสำเร็จ", centered: true });
        setLoading(false);
      })
      .catch((error) => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
    const result = productsType.filter((item) => item.id !== id);
    setProductsType(result);
  };

  const items = [
    // {
    //   key: "1",
    //   label: "รายการทั้งหมด",
    //   children: <AuctionList />,
    // },
    {
      key: "2",
      label: "ขายโคม/ตรุษจีน/ง่วนเซียว",
      children: (
        <ProductList
          data={products.filter((product) => product.event_id === 1)}
          onStatusChange={handleChangeStatus}
          onClickEdit={handleClickEditItem}
        />
      ),
    },
    {
      key: "3",
      label: "งานสมโภช",
      children: (
        <ProductList
          data={products.filter((product) => product.event_id === 2)}
          onStatusChange={handleChangeStatus}
          onClickEdit={handleClickEditItem}
        />
      ),
    },
  ];

  const onChangeYear = (_, dateString) => {
    setYear(dateString);
    setDateSelect(moment().set("year", dateString).format("YYYY-MM-DD"));
    fetchData();
  };

  if (loading) return <Loading />;

  return (
    <div>
      <div
        style={{
          width: "100%",
          justifyContent: "center",
          display: "flex",
        }}
      >
        <Space>
          <h3>ประจำปี</h3>
          <DatePicker
            onChange={onChangeYear}
            defaultValue={dayjs(dateSelect, "YYYY")}
            picker="year"
          />
        </Space>
      </div>
      <Divider />
      <div
        style={{
          justifyContent: "space-between",
          alignItems: "center",
          display: "flex",
        }}
      >
        <Space direction="vertical">
          <Button style={{ width: 125 }} onClick={handleClickAddBillType}>
            เพิ่มประเภทบิล
          </Button>

          {/* <Button style={{ width: 125 }} onClick={handleClickAddProductType}>
            เพิ่มประเภทสินค้า
          </Button> */}
        </Space>
        <Button onClick={handleClickAddItem} icon={<PlusOutlined />}>
          เพิ่มรายการสินค้า
        </Button>
      </div>

      <Divider />
      <ProductStock data={products} />
      <>
        <Tabs defaultActiveKey="1" items={items} />
      </>
      <AddProductModal
        open={openAddProductModal}
        type={productsType}
        onClose={setOpenAddProductModal}
        onSubmit={handleAddProduct}
      />

      <EditProductModal
        open={openEditModal}
        data={dataEdit}
        type={productsType}
        onClose={setOpenEditModal}
        onFinishEdit={handleFinishEdit}
        onDelete={handleRemoveItem}
      />

      <AddBillTypeModal
        open={openAddBillTypeModal}
        data={orderType}
        onClose={setOpenAddBillTypeModal}
        onSubmit={handleAddBillType}
        onDelete={handleDeleteBillType}
      />

      <AddProductTypeModal
        open={openAddProductTypeModal}
        data={productsType}
        onClose={setOpenAddProductTypeModal}
        onSubmit={handleSubmitAddProductType}
        onDelete={handleDeleteProductType}
      />
    </div>
  );
}
