import React, { useState } from "react";
import { Form, Input, Select } from "antd";

export default function EditUserGroup({ data, onSubmit }) {
  const [form] = Form.useForm();
  const [selectGroup, setSelectGroup] = useState(0);

  const handleSelect = (event) => {
    console.log("SELECT", event);
    setSelectGroup({ id: event.value, name: event.label });
    // setGroupName(event.target.item.name);
    // setGroupName(event.label);
  };

  const handleChangeName = (event) => {
    onSubmit({ ...selectGroup, name: event.target.value });
    // setGroupName(event.target.value);
  };

  return (
    <Form id="form" layout={"vertical"} form={form}>
      <Form.Item name="id" label="เลือกชื่อเดิม">
        <Select
          onChange={(_, e) => handleSelect(e)}
          size="large"
          placeholder="กลุ่ม"
          options={data.map((item) => ({
            value: item.id,
            label: item.name,
          }))}
        />
      </Form.Item>
      <Form.Item name="name" label="ชื่อใหม่">
        <Input
          placeholder="แก้ไขชื่อใหม่"
          onChange={handleChangeName}
          disabled={!selectGroup.id}
        />
      </Form.Item>
    </Form>
  );
}
