import { Button, Divider, Modal } from "antd";
import React from "react";
import OrderList from "./OrderList";

export default function OrderListModal({ open, data, type, onClose }) {
  const handleClose = () => {
    onClose(false);
  };
  return (
    <Modal
      title="คำสั่งซื้อ"
      centered={true}
      // width={1000}
      open={open}
      //   onOk={handleSubmit}
      closeIcon={false}
      onCancel={handleClose}
      footer={[
        <Button key="close" onClick={handleClose}>
          ปิด
        </Button>,
      ]}
    >
      <Divider />
      <OrderList data={data} type={type} />
    </Modal>
  );
}
