import { List, Tag, Typography } from "antd";
import moment from "moment";
import React from "react";
import { useSelector } from "react-redux";
import { Link } from "react-router-dom";

const { Text } = Typography;

export default function OrderItem({
  data,
  onClickPrintAddress,
  onClickManageJob,
  onClickItem,
  onClickFinishJobDetail,
}) {
  const user = useSelector((state) => state.token);
  const handleClick = () => {
    onClickManageJob(data);
  };

  const handlePrintAddress = () => {
    onClickPrintAddress(data);
  };

  const handleClickFinishDetail = () => {
    onClickFinishJobDetail(data);
  };

  const listItem1 = [
    <Link onClick={handlePrintAddress}>ใบปะหน้า</Link>,
    <Link onClick={handleClick}>จัดการ</Link>,
  ];

  const listItem2 = [
    <Tag color="success">จัดส่งแล้ว</Tag>,
    <Link onClick={handleClickFinishDetail}>รายละเอียด</Link>,
  ];
  return (
    <List.Item actions={data.delivery_status_id !== 3 ? listItem1 : listItem2}>
      <List.Item.Meta
        onClick={() => {
          onClickItem(data);
        }}
        // avatar={
        //   <Avatar
        //     src={`https://xsgames.co/randomusers/avatar.php?g=pixel&key=${1}`}
        //   />
        // }
        title={
          <div style={{ flexDirection: "column", display: "flex" }}>
            <Text>{data?.storename}</Text>
            <Text type="secondary">{data.phone}</Text>
            <Text type="secondary" style={{ fontSize: 12 }}>
              ถนน {data.road}
            </Text>
          </div>
        }
        description={
          data.delivery_status_id !== 1 && (
            <Text type="secondary" style={{ fontSize: 12 }}>
              จัดส่งล่าสุด:{" "}
              {moment(data.delivery_datetime).format("DD/MM/YYYY HH:mm:ss")}
            </Text>
          )
        }
      />
    </List.Item>
  );
}
