import React from "react";
import { List, Typography } from "antd";
import { Link } from "react-router-dom";

const { Text } = Typography;

export default function AuctionItem({ data, onPrint, onSubmit, onClickItem }) {
  const handlePrint = () => {
    onPrint(data);
  };

  const handleClickItem = () => {
    onSubmit({ ...data, status: "ชำระแล้ว" });
  };

  return (
    <List.Item
      actions={[
        data.status === "ยังไม่ชำระ" && (
          <Link onClick={handleClickItem}>ยืนยันชำระ</Link>
        ),
        <Link onClick={handlePrint}>
          {data.status === `ชำระแล้ว` ? `พิมพ์ใบเสร็จ` : `พิมพ์ใบรับ`}
        </Link>,
      ]}
    >
      <List.Item.Meta
        onClick={() => {
          onClickItem(data);
        }}
        title={<Text>เลขที่ใบรับ {data.bill_no}</Text>}
        description={
          <div style={{ display: "flex", flexDirection: "column" }}>
            <Text strong>{data.product_name}</Text>
            <Text>ชื่อลูกค้า {data.customer}</Text>
            <Text type="secondary">ผู้ติดต่อ {data.user}</Text>
          </div>
        }
      />
    </List.Item>
  );
}
