import { List, Modal, Space, DatePicker, Divider } from "antd";
import React, { useEffect, useState } from "react";
import DonateItem from "../DonateItem";
import dayjs from "dayjs";
import moment from "moment";
import { useDispatch, useSelector } from "react-redux";
import baseAPI from "../../../../api/baseAPI";

export default function UserSearch({
  date,
  //   onClickItem,
  //   onPrint,
  onYearChange,
}) {
  const user = useSelector((state) => state.token);
  //   const [dataSource, setDataSource] = useState([]);
  const [dateSelect, setDateSelect] = useState(date);

  useEffect(() => {
    const date = new Date();
    let month = date.getMonth() + 1;
    let year = date.getFullYear();
    if (month >= 10) {
      year += 1;
      setDateSelect(moment().add(1, "years").format("YYYY-MM-DD"));
    } else {
      setDateSelect(moment().format("YYYY-MM-DD"));
    }
    fetchAllData(year);
  }, []);

  const fetchAllData = async (year) => {
    let url = "";
    if (user.role === "admin" || user.role === "editor") {
      url = "/city_pillar_shrine/toi-jee";
    } else {
      url = "/city_pillar_shrine/toi-jee/user/" + user.id;
    }

    await baseAPI
      .get(url, {
        headers: {
          "x-access-token": user.token,
        },
        params: { year },
      })

      .then((response) => {
        onYearChange(response.data);
      })
      .catch((err) => {
        // dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: err.message,
          centered: true,
        });
      });
  };
  const onChangeYear = (date, dateString) => {
    fetchAllData(dateString);
    // onYearChange(dateString);
  };

  if (dateSelect) {
    return (
      <div>
        <div
          style={{
            marginBottom: "24px",
            width: "100%",
            justifyContent: "center",
            display: "flex",
          }}
        >
          <Space>
            <h3>ประจำปี</h3>
            <DatePicker
              onChange={onChangeYear}
              defaultValue={dayjs(dateSelect, "YYYY")}
              picker="year"
            />
          </Space>
        </div>
        <Divider />
      </div>
    );
  }
}
