import React, { useState } from "react";
import { DatePicker, Divider, Radio, Space, Typography } from "antd";
import MainDashboard from "./MainDashboard";
import ToiJeeDashboard from "./ToiJeeDashboard";
import { useSelector } from "react-redux";
import Loading from "../../../utils/Loading";

const { Text } = Typography;

export default function Main() {
  const user = useSelector((state) => state.token);
  const [radioSelected, setRadioSelected] = useState(1);
  const [loading, setLoading] = useState(false);

  const onChangeType = (event) => {
    // console.log("onChangeType", event);

    setRadioSelected(event.target.value);
  };

  if (loading) return <Loading />;

  return (
    <>
      <Space direction="vertical">
        <Text strong>ประเภทงาน</Text>
        <Radio.Group onChange={onChangeType} value={radioSelected}>
          <Space direction="vertical">
            <Radio value={1}>ขายโคม/ตรุษจีน/ง่วนเซียว/งานสมโภช</Radio>
            <Radio value={2}>งานโต่ยจี๊</Radio>
          </Space>
        </Radio.Group>
      </Space>

      <Divider />
      {radioSelected === 1 ? <MainDashboard /> : <ToiJeeDashboard />}
    </>
  );
}
