import React from "react";
import { Typography } from "antd";
import { Link } from "react-router-dom";

const { Text } = Typography;

export default function BillTypeItem({ id, name, onClick }) {
  const handleClick = () => {
    onClick(id);
  };
  return (
    <div
      style={{
        width: "100%",
        justifyContent: "space-between",
        display: "flex",
      }}
    >
      <Text>{name}</Text>
      <Link onClick={handleClick}>ลบ</Link>
    </div>
  );
}
