import React, { useEffect, useState } from "react";
import {
  Button,
  DatePicker,
  Form,
  Input,
  InputNumber,
  Modal,
  Select,
  Space,
  Switch,
  Typography,
} from "antd";
import dayjs from "dayjs";
import moment from "moment";

const { Text } = Typography;

export default function EditProductModal({
  open,
  data,
  type,
  onClose,
  onFinishEdit,
  onDelete,
}) {
  const [form] = Form.useForm();
  const [year, setYear] = useState("");

  const handleSubmit = (value) => {
    const submit = {
      id: data.id,
      ...value,
      years: year,
      amount: value.amount ? value.amount : 0,
    };
    // console.log("EDIT", submit);
    onFinishEdit(submit);
  };

  const handleRemove = () => {
    onDelete(data);
  };

  const handleClose = () => {
    onClose(false);
  };

  const onFinishFailed = (errorInfo) => {
    console.log("Failed:", errorInfo);
  };

  const handleDateChange = (date, dateString) => {
    setYear(dateString);
    // form.setFieldsValue({ years: dateString });
  };

  return (
    <Modal
      destroyOnClose={true}
      title="แก้ไขสินค้า"
      centered={true}
      open={open}
      onOk={handleSubmit}
      closeIcon={false}
      // onCancel={handleClose}
      footer={[
        <Button danger key="delete" onClick={handleRemove}>
          ลบสินค้านี้
        </Button>,
        <Button
          key="close"
          // href="https://google.com"
          // loading={loading}
          onClick={handleClose}
        >
          ยกเลิก
        </Button>,
        <Button key="submit" type="primary" onClick={form.submit}>
          บันทึก
        </Button>,
      ]}
    >
      <div style={{ padding: 16 }}>
        <Form
          preserve={false}
          form={form}
          labelCol={{
            span: 8,
          }}
          wrapperCol={{
            span: 18,
          }}
          layout="horizontal"
          onFinish={handleSubmit}
          onFinishFailed={onFinishFailed}
        >
          <Form.Item
            name="years"
            label="สินค้าประจำปี"
            // initialValue={moment(data.years.toString(), "YYYY")}
            rules={[
              {
                required: true,
                message: "ต้องไม่เว้นว่าง",
              },
            ]}
          >
            <DatePicker
              picker="year"
              defaultValue={moment(data.years, "YYYY")}
              onChange={handleDateChange}
              style={{ width: "100%" }}
            />
          </Form.Item>
          <Form.Item
            name="name"
            label="ชื่อรายการ/สินค้า"
            initialValue={data.name}
            rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
          >
            <Input name="name" />
          </Form.Item>
          <Form.Item
            name="type_id"
            label="ประเภทสินค้า"
            rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
            initialValue={data.type_id}
          >
            <Select
              size="large"
              placeholder="เลือกประเภทสินค้า"
              options={type
                .filter((item) => data.event_id === item.event_id)
                .map((item) => ({
                  value: item.id,
                  label: item.name,
                }))}
            />
          </Form.Item>
          <Form.Item
            name="price"
            label="ราคาขาย"
            initialValue={data.price}
            rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
          >
            <InputNumber
              size="large"
              name="price"
              style={{ width: "100%" }}
              formatter={(value) =>
                `${value}`.replace(/\B(?=(\d{3})+(?!\d))/g, ",")
              }
            />
          </Form.Item>
          <Form.Item
            name="amount"
            label={
              <Space>
                <Text>เพิ่มสต็อก</Text>
                <Text type="secondary">
                  คงเหลือ: {data.amount} (จากทั้งหมด: {data.total_amount})
                </Text>
              </Space>
            }
            // initialValue={data.amount}
          >
            <InputNumber
              size="large"
              name="amount"
              style={{ width: "100%" }}
              formatter={(value) =>
                `${value}`.replace(/\B(?=(\d{3})+(?!\d))/g, ",")
              }
            />
          </Form.Item>
          <Form.Item
            name="active"
            label="สถานะสินค้า"
            initialValue={data.active}
            rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
          >
            <Switch
              checkedChildren="ขาย"
              unCheckedChildren="ไม่ขาย"
              defaultChecked={data.active}
            />
          </Form.Item>
        </Form>
      </div>
    </Modal>
  );
}
