import React from "react";
import { Button, Modal, Descriptions } from "antd";

export default function UserDetailModal({ open, onClose, data }) {
  const handleClose = () => {
    onClose(false);
  };

  if (data.id) {
    return (
      <Modal
        title="รายละเอียด"
        centered={true}
        // width={1000}
        open={open}
        //   onOk={handleSubmit}
        closeIcon={false}
        onCancel={handleClose}
        footer={[
          <Button key="close" onClick={handleClose}>
            ปิด
          </Button>,
          // <Button key="submit" type="primary" onClick={handleSubmit}>
          //   บันทึก
          // </Button>,
        ]}
      >
        <Descriptions>
          <Descriptions.Item label="ชื่อสกุล">
            {data.firstname + " " + data.lastname}
          </Descriptions.Item>
          <Descriptions.Item label="อีเมล">{data.email}</Descriptions.Item>
          <Descriptions.Item label="โทรศัพท์">{data.phone}</Descriptions.Item>
          <Descriptions.Item label="ไลน์">{data.line}</Descriptions.Item>
          <Descriptions.Item label="ที่อยู่">{data.address}</Descriptions.Item>

          <Descriptions.Item label="กลุ่มสมาชิก">
            {data.groupname}
          </Descriptions.Item>
          <Descriptions.Item label="สิทธิการใช้งาน">
            {data.role}
          </Descriptions.Item>
        </Descriptions>
      </Modal>
    );
  }
  return false;
}
