import React, { useEffect, useState } from "react";
import OrderHistoryList from "./OrderHistoryList";
import {
  Typography,
  Space,
  Radio,
  DatePicker,
  Tabs,
  Modal,
  Select,
  Divider,
} from "antd";
import UserListSelect from "../UserListSelect";
import OrderDetailModal from "./OrderDetailModal";
import baseAPI from "../../../api/baseAPI";
import OrderCancelList from "./OrderCancelList";
import { useNavigate } from "react-router-dom";
import { useDispatch, useSelector } from "react-redux";
import { addMyOrder, addOrder, addToken } from "../../../redux/reduxSlice";
import Loading from "../../../utils/Loading";
import OrderList from "./report/OrderList";
import ConfirmCancelOrderModal from "./ConfirmCancelOrderModal";
import HistorySearch from "./HistorySearch";
import OrderEditList from "./OrderEditList";
import OrderReferDetailModal from "./OrderReferDetailModal";
import CelebrationSearch from "./CelebrationSearch";
import { ReceiptPDF } from "./receipt/ReceiptPDF";

import pdfMake from "pdfmake/build/pdfmake";
import pdfFonts from "pdfmake/build/vfs_fonts";
import ConfirmOrderCelebrationModal from "./ConfirmOrderCelebrationModal";
import OrderCelebrationList from "./report/OrderCelebrationList";

pdfMake.vfs = pdfFonts.pdfMake.vfs;

//ต้องระบุตามชื่อของ ไฟล์ font
pdfMake.fonts = {
  THSarabunNew: {
    normal: "THSarabunNew.ttf",
    bold: "THSarabunNew Bold.ttf",
    italics: "THSarabunNew Italic.ttf",
    bolditalics: "THSarabunNew Bold Italic.ttf",
  },
  AngsanaNew: {
    normal: "AngsanaNew.ttf",
    bold: "AngsanaNew Bold.ttf",
    italics: "AngsanaNew Italic.ttf",
    bolditalics: "AngsanaNew Bold Italic.ttf",
  },
  Roboto: {
    normal: "Roboto-Regular.ttf",
    bold: "Roboto-Medium.ttf",
    italics: "Roboto-Italic.ttf",
    bolditalics: "Roboto-MediumItalic.ttf",
  },
};

const { Text } = Typography;

export default function Main() {
  const user = useSelector((state) => state.token);
  const dispatch = useDispatch();
  const navigate = useNavigate();

  const [orders, setOrders] = useState([]);
  const [orderDetail, setOrderDetail] = useState({});
  const [orderRefer, setOrderRefer] = useState({});
  const [radioSelected, setRadioSelected] = useState(1);

  const [openOrderDetailModal, setOpenOrderDetailModal] = useState(false);
  const [openOrderCancelModal, setOpenOrderCancelModal] = useState(false);
  const [openOrderEditModal, setOpenOrderEditModal] = useState(false);

  const [openConfirmOrderModal, setOpenConfirmOrderModal] = useState(false);
  //   console.log("OrderHistory", orders);

  const [loading, setLoading] = useState(false);
  const [orderCancel, setOrderCancel] = useState({});
  // const [orderReferSelected, setOrderReferSelected] = useState({});

  const handleClickCompleteItem = (item) => {
    console.log("ITEM SELECTED", item);

    if (item.order_refer_id) {
      setOrderRefer(item);
      getOrderIfOrderRefer(item.order_refer_id);
      // handleClickItemEdit(item);
    } else {
      setOrderDetail(item);
      setOpenOrderDetailModal(true);
    }

    // console.log("handleClickItem", item);
  };

  const getOrderIfOrderRefer = async (id) => {
    await baseAPI
      .get(`/city_pillar_shrine/orders/id/${id}`, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        // console.log("Order Refer", response.data);
        setOrderDetail(response.data);
        setOpenOrderEditModal(true);
      })
      .catch((err) => {
        // setLoading(false);
        Modal.error({
          title: "ไม่สามารถโหลดข้อมูลได้",
          content: err.message,
          centered: true,
        });
      });
  };

  const handleSearch = (data) => {
    // console.log("handleSearch", data);
    setOrders(data);
  };

  const onChangeType = (event) => {
    // console.log("onChangeType", event);

    setRadioSelected(event.target.value);
  };

  const handleClickCancelItem = (item) => {
    // console.log("handleClickCancelItem", item);
    setOrderCancel(item);
    setOpenOrderCancelModal(true);
  };

  const handleConfirmCancelOrder = async (data) => {
    Modal.confirm({
      title: "ยืนยันการยกเลิก",
      content: "ต้องการยืนยันการยกเลิกรายการสั่งซื้อนี้หรือไม่?",
      centered: true,
      onOk: () => {
        cancelOrder(data);
      },
    });
  };

  const cancelOrder = async (data) => {
    // console.log(data);
    setOpenOrderCancelModal(false);
    await baseAPI
      .put(`/city_pillar_shrine/orders/return-stock`, data, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        Modal.success({
          content: "ยกเลิกรายการสำเร็จ",
          centered: true,
        });
        const newState = orders.map((obj) => {
          if (obj.id === data.id) {
            return { ...obj, ...data };
          }
          return obj;
        });
        setOrders(newState);
        setLoading(false);
      })
      .catch((err) => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
  };

  const handlePrintCelebrationReceipt = async (data) => {
    const result = await ReceiptPDF({ data });
    pdfMake.createPdf(result).open();
  };

  const handlePrintReceipt = (data) => {
    setOpenOrderDetailModal(false);
    // console.log("handlePrintReceipt", data);
    dispatch(addMyOrder(data));

    Modal.confirm({
      centered: true,
      title: "ดาวน์โหลดใบเสร็จ",
      content: "ต้องการดาวโลหดใบเสร็จ?",
      onOk: () => {
        if (data.event_id === 1) {
          navigate("/myorder/receipt");
        } else handlePrintCelebrationReceipt(data);
      },
    });
  };

  const updateCancelOrder = async (data) => {
    setLoading(true);
    console.log(data);
    await baseAPI
      .put(`/city_pillar_shrine/orders/status`, data, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        Modal.success({
          content: "ยกเลิกรายการสำเร็จ",
          centered: true,
        });
        const newState = orders.map((obj) => {
          if (obj.id === data.id) {
            return { ...obj, ...data };
          }
          return obj;
        });
        setOrders(newState);
        setLoading(false);
      })
      .catch((err) => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
  };

  const handleCancelOrder = (data) => {
    setOpenOrderDetailModal(false);
    updateCancelOrder(data);
  };

  const handleCancelOrderRefer = (data) => {
    // console.log("CANCEL ORDER REFER", data);
    setOpenOrderEditModal(false);
    updateCancelOrder(data);
  };

  const handleSubmitMark = async (data) => {
    // console.log("DATA", data);
    setOpenOrderDetailModal(false);
    setLoading(true);
    await baseAPI
      .put(`/city_pillar_shrine/orders/status`, data, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        Modal.success({
          content: "แก้ไขรายการสำเร็จ",
          centered: true,
        });
        const newState = orders.map((obj) => {
          if (obj.id === data.id) {
            return { ...obj, ...data };
          }
          return obj;
        });
        setOrders(newState);
        setLoading(false);
      })
      .catch((err) => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
  };

  const handleEditProductList = (data) => {
    // console.log("Edit Product List", data);
    dispatch(addOrder(data));
    navigate("/orders/edit");
  };

  const handleClickItemEdit = async (data) => {
    // console.log("Old data", data);
    setOrderDetail(data);
    // setLoading(true);
    // console.log("Edit History", data);
    await baseAPI
      .get(`/city_pillar_shrine/orders/refer/${data.id}`, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        // console.log("Order Refer", response.data);
        setOrderRefer(response.data);
        setOpenOrderEditModal(true);
        // setLoading(false);
      })
      .catch((err) => {
        // setLoading(false);
        Modal.error({
          title: "ไม่สามารถโหลดข้อมูลได้",
          content: err.message,
          centered: true,
        });
      });
  };

  const handleClickConfirmOrder = (data) => {
    setOrderDetail(data);
    setOpenConfirmOrderModal(true);
  };

  const onSubmitConfirm = async (data) => {
    setOpenConfirmOrderModal(false);
    setLoading(true);
    await baseAPI
      .put(`/city_pillar_shrine/orders/payment/${data.id}`, data, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        Modal.success({
          content: "ยืนยันการชำระสำเร็จ",
          centered: true,
        });
        const newState = orders.map((obj) => {
          if (obj.id === data.id) {
            return { ...obj, ...data };
          }
          return obj;
        });
        setOrders(newState);
        setLoading(false);
      })
      .catch((err) => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
  };

  const items = [
    {
      key: "1",
      label: "ชำระแล้ว",
      children: (
        <OrderHistoryList
          data={orders.filter(
            (order) =>
              order.order_status_id === 1 &&
              order.payment_by_id !== 3 &&
              order.event_id === 1
          )}
          onClickItem={handleClickCompleteItem}
          // onClickStore={handleClickStore}
        />
      ),
    },
    {
      key: "4",
      label: "เปลี่ยน/แก้ไข",
      children: (
        <OrderEditList
          data={orders.filter(
            (order) => order.order_status_id === 4 && order.event_id === 1
          )}
          onClick={handleClickItemEdit}
        />
      ),
    },
    {
      key: "3",
      label: "ยกเลิก",
      children: (
        <OrderCancelList
          data={orders.filter(
            (order) =>
              order.order_status_id !== 1 &&
              order.order_status_id !== 4 &&
              order.event_id === 1
          )}
          onClick={handleClickCancelItem}
        />
      ),
    },
  ];

  const itemCelebrationList = [
    {
      key: "1",
      label: "ยังไม่ชำระ",
      children: (
        <OrderHistoryList
          data={orders.filter(
            (order) =>
              order.order_status_id === 1 &&
              order.payment_by_id === 3 &&
              order.event_id === 2
          )}
          onClickItem={handleClickCompleteItem}
          onConfirm={handleClickConfirmOrder}
          // onClickItem={handleClickItemEdit}
        />
      ),
    },
    {
      key: "2",
      label: "ชำระแล้ว",
      children: (
        <OrderHistoryList
          data={orders.filter(
            (order) =>
              order.order_status_id === 1 &&
              order.payment_by_id !== 3 &&
              order.event_id === 2
          )}
          onClickItem={handleClickCompleteItem}
        />
      ),
    },
    {
      key: "4",
      label: "แก้ไข/เปลี่ยน",
      children: (
        <OrderEditList
          data={orders.filter(
            (order) => order.order_status_id === 4 && order.event_id === 2
          )}
          onClick={handleClickItemEdit}
        />
      ),
    },
    {
      key: "3",
      label: "ยกเลิก",
      children: (
        <OrderCancelList
          data={orders.filter(
            (order) =>
              order.order_status_id !== 1 &&
              order.order_status_id !== 4 &&
              order.event_id === 2
          )}
          onClick={handleClickCancelItem}
          // onClickStore={handleClickStore}
        />
      ),
    },
  ];

  if (loading) return <Loading />;

  return (
    <Space style={{ width: "100%" }} direction="vertical">
      <Text strong>ประเภทงาน</Text>
      <Radio.Group onChange={onChangeType} value={radioSelected}>
        <Space direction="vertical">
          <Radio value={1}>เดินขายโคม/ตรุษจีน/ง่วนเซียว</Radio>
          <Radio value={2}>งานสมโภชศาลเจ้าปึงเถ่ากง-ม่า</Radio>
        </Space>
      </Radio.Group>
      <Divider />
      {radioSelected === 1 ? (
        <>
          <HistorySearch onSearch={handleSearch} searchType={"orders"} />
          <OrderList data={orders} />
          <Tabs defaultActiveKey="1" items={items} />
        </>
      ) : (
        <>
          <CelebrationSearch onSearch={handleSearch} />
          <OrderCelebrationList data={orders} />
          <Tabs defaultActiveKey="1" items={itemCelebrationList} />
        </>
      )}

      <OrderDetailModal
        open={openOrderDetailModal}
        data={orderDetail}
        onclose={setOpenOrderDetailModal}
        onCancelOrder={handleCancelOrder}
        onSubmit={handleSubmitMark}
        onPrint={handlePrintReceipt}
        onEdit={handleEditProductList}
      />

      <ConfirmCancelOrderModal
        data={orderCancel}
        open={openOrderCancelModal}
        onclose={setOpenOrderCancelModal}
        onCancelConfirm={handleConfirmCancelOrder}
      />

      <OrderReferDetailModal
        open={openOrderEditModal}
        data={orderDetail}
        dataRefer={orderRefer}
        onclose={setOpenOrderEditModal}
        onCancel={handleCancelOrderRefer}
        onSubmit={handleSubmitMark}
        onPrint={handlePrintReceipt}
      />

      <ConfirmOrderCelebrationModal
        open={openConfirmOrderModal}
        data={orderDetail}
        onSubmit={onSubmitConfirm}
        onClose={setOpenConfirmOrderModal}
      />
    </Space>
  );
}
