import React, { useState } from "react";
import { Modal, Tabs } from "antd";
import AssociationList from "./AssociationList";
import AddAssociationMembers from "./AddAssociationMembers";
import baseAPI from "../../../api/baseAPI";
import { useSelector } from "react-redux";

export default function Main() {
  const user = useSelector((state) => state.token);
  const [loading, setLoading] = useState(false);
  // const da
  const handleSubmit = (data) => {
    console.log("Submit", data.length);
    let count = 0;
    setLoading(true);
    Promise.all(
      data?.map(async (item) => {
        await baseAPI
          .post(`/city_pillar_shrine/association`, item, {
            headers: {
              "x-access-token": user.token,
            },
          })
          .then((res) => {
            count++;
            console.log("count", count);
            if (count === data.length) {
              setLoading(false);
              Modal.success({
                title: "สำเร็จ",
                content: "บันทึกสำเร็จ " + count + " รายการ",
                centered: true,
              });
            }
          })
          .catch((err) => {
            // dispatch(addToken({}));
            // navigate("/login");
            Modal.warning({
              title: "คำขอล้มเหลว",
              content: "Sessions Expired",
              centered: true,
            });
            // setLoading(false);
          });
      })
    );
  };

  const items = [
    {
      key: 1,
      label: "รายชื่อสมาชิกสมาคม",
      children: <AssociationList />,
    },
    {
      key: 2,
      label: "เพิ่มรายชื่อสมาชิกสมาคม",
      children: <AddAssociationMembers onSubmit={handleSubmit} />,
    },
  ];

  const onChange = (key) => {
    console.log(key);
  };

  return (
    <div>
      <Tabs defaultActiveKey="1" items={items} onChange={onChange} />
    </div>
  );
}
