import { List } from "antd";
import React from "react";
import { Link } from "react-router-dom";

export default function CustomerMemberItem({ data, onDelete }) {
  const handleClick = () => {
    // console.log("DATA", data);
    onDelete(data);
  };

  return (
    <List.Item
      actions={[
        // <Switch
        //   onChange={handleChangeStatus}
        //   checkedChildren="มี"
        //   unCheckedChildren="ไม่มี"
        //   defaultChecked={data.active}
        // />,

        <Link key="choose" onClick={handleClick}>
          ลบ
        </Link>,
      ]}
    >
      <List.Item.Meta
        // onClick={onClickList}
        title={data?.fullname}
        description={data?.phone}
      />
    </List.Item>
  );
}
