import React from "react";
import { List } from "antd";
import DonateItem from "./DonateItem";
export default function DonateList({ data, onPrintReceipt, onClickItem }) {
  return (
    <List
      pagination={{
        onChange: (page) => {
          console.log(page);
        },
        pageSize: 10,
      }}
      itemLayout="horizontal"
      dataSource={data}
      renderItem={(item, index) => (
        <DonateItem
          data={item}
          onClickPrint={onPrintReceipt}
          onClickItem={onClickItem}
        />
      )}
    />
  );
}
