import { List } from "antd";
import React from "react";
import OrderItem from "./OrderItem";
import ToiJeeItem from "./ToiJeeItem";

export default function OrderList({ data, type }) {
  return (
    <List
      // size="small"
      pagination={{
        onChange: (page) => {
          //   console.log(page);
        },
        pageSize: 10,
      }}
      dataSource={data}
      renderItem={(item, index) =>
        item.order_status_id === 1 &&
        (type === 1 ? (
          <OrderItem data={item} index={index} />
        ) : (
          <ToiJeeItem data={item} index={index} />
        ))
      }
    />
  );
}
