import React, { useEffect, useState } from "react";
import { Button, Divider, Modal, Radio, Space, Tabs, Typography } from "antd";
import { PlusOutlined } from "@ant-design/icons";
import { useDispatch, useSelector } from "react-redux";
import baseAPI from "../../../api/baseAPI";
import OrderList from "./OrderList";
import Loading from "../../../utils/Loading";
import { useNavigate } from "react-router-dom";
import { addToken } from "../../../redux/reduxSlice";
import InstallationManage from "./InstallationManage";
import CustomerDetailModal from "../customer/CustomerDetailModal";
import FinishJobModal from "./FinishJobModal";
import FinishJobDetailModal from "./FinishJobDetailModal";
import pdfMake from "pdfmake/build/pdfmake";
import pdfFonts from "pdfmake/build/vfs_fonts";
import { InstallationDoc } from "./pdf/InstallationDoc";
import PrintWorkSheetModal from "./PrintWorkSheetModal";
import HistorySearch from "../history/HistorySearch";
import moment from "moment";
import MaintenanceList from "./report/MaintenanceList";

const { Text } = Typography;

pdfMake.vfs = pdfFonts.pdfMake.vfs;

//ต้องระบุตามชื่อของ ไฟล์ font
pdfMake.fonts = {
  THSarabunNew: {
    normal: "THSarabunNew.ttf",
    bold: "THSarabunNew Bold.ttf",
    italics: "THSarabunNew Italic.ttf",
    bolditalics: "THSarabunNew Bold Italic.ttf",
  },
  AngsanaNew: {
    normal: "AngsanaNew.ttf",
    bold: "AngsanaNew Bold.ttf",
    italics: "AngsanaNew Italic.ttf",
    bolditalics: "AngsanaNew Bold Italic.ttf",
  },
  Roboto: {
    normal: "Roboto-Regular.ttf",
    bold: "Roboto-Medium.ttf",
    italics: "Roboto-Italic.ttf",
    bolditalics: "Roboto-MediumItalic.ttf",
  },
};

export default function Main() {
  const user = useSelector((state) => state.token);
  // console.log(user);
  const dispatch = useDispatch();
  const navigate = useNavigate();

  const [openManageTeamModal, setOpenManageTeamModal] = useState(false);
  const [openFinishJobModal, setOpenFinishJobModal] = useState(false);
  const [openFinishJobDetailModal, setOpenFinishJobDetailModal] =
    useState(false);
  const [openCustomerDetailsModal, setOpenCustomerDetailsModal] =
    useState(false);
  const [openPrintWorkSheetModal, setOpenPrintWorkSheetModal] = useState(false);
  const [customerSelect, setCustomerSelect] = useState(false);
  const [orderMaintenance, setOrderMaintenance] = useState([]);
  const [team, setTeam] = useState([]);
  const [data, setData] = useState({});
  // const [radioSelected, setRadioSelected] = useState(1);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (user.role !== "admin" || user.role !== "editor") {
      fetchDataByUserId();
    }
  }, []);

  const fetchDataByUserId = async () => {
    let url = `/city_pillar_shrine/maintenance/user/${user.id}`;

    await baseAPI
      .get(url, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((res) => {
        setOrderMaintenance(res.data);
      })
      .catch((err) => {
        Modal.error({
          title: "ไม่สามารถโหลดข้อมูลได้",
          content: err.message,
          centered: true,
        });
      });
  };

  const handleClickManageJob = async (data) => {
    setData(data);
    setOpenManageTeamModal(true);
  };

  const handleSubmitManage = async (data) => {
    console.log(data);
    await baseAPI
      .put("/city_pillar_shrine/maintenance-status", data, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        Modal.success({
          title: "สำเร็จ",
          content: "จัดตารางงานติดตั้งเสร็จสิ้น",
          centered: true,
        });

        const newState = orderMaintenance.map((obj) => {
          if (obj.id === data.id) {
            return { ...obj, ...data };
          }
          return obj;
        });
        setOrderMaintenance(newState);
        setOpenManageTeamModal(false);
        // fetchData();
        setLoading(false);
      })
      .catch((error) => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
  };

  const handleSubmitFinishJob = async (data) => {
    // console.log(data);
    setOpenFinishJobModal(false);
    await baseAPI
      .put("/city_pillar_shrine/maintenance-finish", data, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        Modal.success({
          title: "สำเร็จ",
          content: "จัดตารางงานติดตั้งเสร็จสิ้น",
          centered: true,
        });

        const newState = orderMaintenance.map((obj) => {
          if (obj.id === data.id) {
            return { ...obj, ...data };
          }
          return obj;
        });
        setOrderMaintenance(newState);
        setOpenManageTeamModal(false);
        // fetchData();
        setLoading(false);
      })
      .catch((error) => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });
  };

  const handleClickFinishJob = (data) => {
    setCustomerSelect(data);
    setOpenFinishJobModal(data);
  };

  const handleClickItem = (data) => {
    setCustomerSelect(data);
    setOpenCustomerDetailsModal(true);
  };

  const handleClickFinishDetail = (data) => {
    setCustomerSelect(data);
    setOpenFinishJobDetailModal(true);
  };

  const handlePrintDoc = async (data) => {
    setCustomerSelect(data);
    setOpenPrintWorkSheetModal(true);
  };

  const handleSubmitPrint = async (data) => {
    // console.log("Mark", data);
    await baseAPI
      .put("/city_pillar_shrine/maintenance-status", data, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        const newState = orderMaintenance.map((obj) => {
          if (obj.id === data.id) {
            return { ...obj, ...data };
          }
          return obj;
        });
        setOrderMaintenance(newState);
        setOpenPrintWorkSheetModal(false);
        // fetchData();

        setLoading(false);
      })
      .catch((error) => {
        dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: "Sessions Expired",
          centered: true,
        });
        setLoading(false);
      });

    let orders = [];
    data.products.map((product, index) => {
      const data = [
        {
          text: index + 1,
          alignment: "center",
          style: "textBody",
        },
        {
          text: product.name,
          alignment: "left",
          style: "textBody",
        },
        {
          text: product.amount,
          alignment: "center",
          style: "textBody",
        },
      ];
      orders.push(data);
    });
    const result = await InstallationDoc({ data, orders });
    pdfMake.createPdf(result).open();
  };

  // const onChangeType = (event) => {
  //   setRadioSelected(event.target.value);
  // };

  if (loading) return <Loading />;

  const items = [
    user.role === "admin" && {
      key: "1",
      label: "รายการใหม่",
      children: (
        <OrderList
          status={false}
          data={orderMaintenance.filter(
            (order) => order.maintenance_status_id === 1
          )}
          onClickManageJob={handleClickManageJob}
          onClickItem={handleClickItem}
          //   onClickStore={handleClickStore}
        />
      ),
    },
    {
      key: "2",
      label: "รอติดตั้ง",
      children: (
        <OrderList
          status={true}
          data={orderMaintenance.filter(
            (order) => order.maintenance_status_id === 2
          )}
          onClickManageJob={handleClickManageJob}
          onFinishJob={handleClickFinishJob}
          onClickItem={handleClickItem}
          onDownloadWorkSheet={handlePrintDoc}

          //   onClick={handleClick}
        />
      ),
    },
    {
      key: "3",
      label: "ติดตั้งเสร็จสิ้น",
      children: (
        <OrderList
          status={true}
          data={orderMaintenance.filter(
            (order) => order.maintenance_status_id === 3
          )}
          onClickFinishJobDetail={handleClickFinishDetail}
          onClickItem={handleClickItem}
          onDownloadWorkSheet={handlePrintDoc}
        />
      ),
    },
  ];
  return (
    <Space style={{ width: "100%" }} direction="vertical">
      {(user.role === "admin" || user.role === "editor") && (
        <>
          <HistorySearch
            onSearch={setOrderMaintenance}
            searchType={"maintenance"}
          />
          <MaintenanceList data={orderMaintenance} />
        </>
      )}

      <Tabs defaultActiveKey="1" items={items} />
      <InstallationManage
        open={openManageTeamModal}
        data={data}
        onClose={setOpenManageTeamModal}
        onSubmit={handleSubmitManage}
      />
      <CustomerDetailModal
        data={customerSelect}
        open={openCustomerDetailsModal}
        onClose={setOpenCustomerDetailsModal}
      />
      <FinishJobModal
        open={openFinishJobModal}
        data={customerSelect}
        onClose={setOpenFinishJobModal}
        onSubmit={handleSubmitFinishJob}
      />
      <FinishJobDetailModal
        data={customerSelect}
        open={openFinishJobDetailModal}
        onClose={setOpenFinishJobDetailModal}
      />

      <PrintWorkSheetModal
        open={openPrintWorkSheetModal}
        data={customerSelect}
        onClose={setOpenPrintWorkSheetModal}
        onSubmit={handleSubmitPrint}
      />
    </Space>
  );
}
