import moment from "moment";
import React, { useEffect, useState } from "react";
import ReactExport from "react-export-excel";
import { Link } from "react-router-dom";

const ExcelFile = ReactExport.ExcelFile;
const ExcelSheet = ReactExport.ExcelFile.ExcelSheet;
const ExcelColumn = ReactExport.ExcelFile.ExcelColumn;

export default function OrderList({ data }) {
  const [noBooking, setNobooking] = useState([]);
  const [booking, setBooking] = useState([]);

  useEffect(() => {
    if (data.length > 0) {
      const noBooking = data.filter((item) => item.ticket_status_id === 1);
      const booking = data.filter((item) => item.ticket_status_id === 2);
      setNobooking(noBooking);
      setBooking(booking);
    }
  }, [data]);

  //   useEffect(() => {
  // console.log(dataSource);
  //   }, [dataSource]);

  // const mapData = () => {
  //   let arr = [];
  //   data.map((item) => arr.push(...item.products));
  //   setDataSource(arr);
  // };

  //   const
  return (
    <div style={{ width: "100%", justifyContent: "end", display: "flex" }}>
      <ExcelFile element={<Link>Download</Link>}>
        {/* <ExcelSheet dataSet={multiDataSet} name="Organization" /> */}
        <ExcelSheet data={noBooking} name="รายการยังไม่จอง">
          <ExcelColumn label="ประเภท" value="order_type" />
          <ExcelColumn label="สถานะ" value="order_status" />
          <ExcelColumn label="เลขที่ใบเสร็จ" value="order_number" />
          <ExcelColumn
            label="วันที่"
            value={(col) => moment(col.datetime).format("DD/MM/YY")}
          />
          <ExcelColumn
            label="กรรมการ"
            value={(col) =>
              col.user_name +
              " " +
              col.user_lastname +
              " ( " +
              col.user_nickname +
              " )"
            }
          />
          <ExcelColumn label="ร้านค้า" value="storename" />
          <ExcelColumn label="ชื่อลูกค้า" value="fullname" />
          <ExcelColumn label="โทรศัพท์" value="phone" />
          {/* <ExcelColumn
            label="ประเภทโต๊ะ"
            value={(col) =>
              col.ticket_type_id === 1
                ? "ปกติ"
                : col.ticket_type_id === 2
                ? "VIP"
                : "-"
            }
          /> */}
          <ExcelColumn
            label="หมายเลขโต๊ะ"
            value={(col) =>
              col.ticket_type_id === 1
                ? col.seat_number
                : col.ticket_type_id === 2
                ? col.seat_number_vip
                : "-"
            }
          />
        </ExcelSheet>
        <ExcelSheet data={booking} name="รายการจองแล้ว">
          <ExcelColumn label="ประเภท" value="order_type" />
          <ExcelColumn label="สถานะ" value="order_status" />
          <ExcelColumn label="เลขที่ใบเสร็จ" value="order_number" />
          <ExcelColumn
            label="วันที่"
            value={(col) => moment(col.datetime).format("DD/MM/YY")}
          />
          <ExcelColumn
            label="กรรมการ"
            value={(col) =>
              col.user_name +
              " " +
              col.user_lastname +
              " ( " +
              col.user_nickname +
              " )"
            }
          />
          <ExcelColumn label="ร้านค้า" value="storename" />
          <ExcelColumn label="ชื่อลูกค้า" value="fullname" />
          <ExcelColumn label="โทรศัพท์" value="phone" />
          {/* <ExcelColumn
            label="ประเภทโต๊ะ"
            value={(col) =>
              col.ticket_type_id === 1
                ? "ปกติ"
                : col.ticket_type_id === 2
                ? "VIP"
                : "-"
            }
          /> */}
          <ExcelColumn
            label="หมายเลขโต๊ะ"
            value={(col) =>
              col.ticket_type_id === 1
                ? col.seat_number
                : col.ticket_type_id === 2
                ? col.seat_number_vip
                : "-"
            }
          />
        </ExcelSheet>
      </ExcelFile>
    </div>
  );
}
