import React, { useState, useEffect } from "react";
import {
  Button,
  Form,
  Input,
  Card,
  Modal,
  InputNumber,
  Select,
  DatePicker,
} from "antd";

export default function AddProductModal({ open, type, onClose, onSubmit }) {
  const [data, setData] = useState({
    order_type_id: 0,
    name: "",
    price: 0,
    amount: 0,
    active: true,
  });
  const [form] = Form.useForm();
  const [eventSelect, setEventSelect] = useState(1);
  const [year, setYear] = useState();

  const handleSubmit = (value) => {
    const addProduct = {
      ...value,
      years: year,
      active: 1,
    };
    // if(value)
    // console.log("Adding", addProduct);
    onSubmit(addProduct);
  };

  const handleClose = () => {
    onClose(false);
  };

  const onFinishFailed = (errorInfo) => {
    console.log("Failed:", errorInfo);
  };

  const handleChangeInput = (e) => {
    // console.log(e);
    setData({ ...data, [e.target.name]: e.target.value });
  };

  const handleChangePrice = (e) => {
    setData({ ...data, price: e });
  };
  const handleChangeAmount = (e) => {
    setData({ ...data, amount: e });
  };

  const handleChangeEvent = (e) => {
    setEventSelect(e);
  };

  const handleDateChange = (date, dateString) => {
    setYear(dateString);
    // form.setFieldsValue({ years: dateString });
  };

  const eventList = [
    {
      value: 1,
      label: "ขายโคม/ตรุษจีน/ง่วนเซียว",
    },
    {
      value: 2,
      label: "งานสมโภชศาลเจ้าปีงเถ่ากง-ม่า",
    },
  ];

  return (
    <Modal
      title="เพิ่มรายการสินค้า"
      // width={1000}
      centered={true}
      open={open}
      onOk={handleSubmit}
      closeIcon={false}
      // onCancel={handleClose}
      footer={[
        <Button
          key="close"
          // href="https://google.com"
          // loading={loading}
          onClick={handleClose}
        >
          ยกเลิก
        </Button>,
        <Button key="submit" type="primary" onClick={form.submit}>
          บันทึก
        </Button>,
      ]}
    >
      <div style={{ padding: 16 }}>
        <Form
          form={form}
          labelCol={{
            span: 8,
          }}
          wrapperCol={{
            span: 18,
          }}
          layout="horizontal"
          onFinish={handleSubmit}
          onFinishFailed={onFinishFailed}
        >
          <Form.Item
            name="years"
            label="สินค้าประจำปี"
            // initialValue={dayjs(years)}
            rules={[
              {
                required: true,
                message: "ต้องไม่เว้นว่าง",
              },
            ]}
          >
            <DatePicker
              picker="year"
              // defaultValue={dayjs(years)}
              onChange={handleDateChange}
              style={{ width: "100%" }}
            />
          </Form.Item>
          <Form.Item
            name="event_name"
            label="ประเภทงาน"
            rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
            initialValue={eventSelect}
          >
            <Select
              onChange={handleChangeEvent}
              size="large"
              placeholder="เลือกชื่องาน"
              options={eventList}
            />
          </Form.Item>
          <Form.Item
            name="name"
            label="ชื่อรายการ/สินค้า"
            rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
          >
            <Input name="name" onChange={handleChangeInput} />
          </Form.Item>

          <Form.Item
            name="type_id"
            label="หมวดหมู่สินค้า"
            rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
          >
            <Select
              size="large"
              placeholder="เลือกหมวดหมู่สินค้า"
              options={type
                .filter((item) => eventSelect === item.event_id)
                .map((item) => ({
                  value: item.id,
                  label: item.name,
                }))}
            />
          </Form.Item>

          <Form.Item
            name="price"
            label="ราคาขาย"
            rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
          >
            <InputNumber
              size="large"
              name="price"
              style={{ width: "100%" }}
              formatter={(value) =>
                `${value}`.replace(/\B(?=(\d{3})+(?!\d))/g, ",")
              }
              onChange={handleChangePrice}
            />
          </Form.Item>
          <Form.Item
            name="amount"
            label="จำนวนสต็อก"
            rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
          >
            <InputNumber
              size="large"
              name="amount"
              style={{ width: "100%" }}
              formatter={(value) =>
                `${value}`.replace(/\B(?=(\d{3})+(?!\d))/g, ",")
              }
              onChange={handleChangeAmount}
            />
          </Form.Item>
        </Form>
      </div>
    </Modal>
  );
}
