import { Tabs, Modal, Divider, Select } from "antd";
import React, { useEffect, useState } from "react";

import baseAPI from "../../../api/baseAPI";
import { useDispatch, useSelector } from "react-redux";
import { useNavigate } from "react-router-dom";
import { addToiJeeOrder } from "../../../redux/reduxSlice";
import dayjs from "dayjs";
import moment from "moment";
import DonateDetailModal from "./DonateDetailModal";
import UserSearch from "./user/UserSearch";
import HistorySearch from "./admin/HistorySearch";
import DonateList from "./DonateList";
import DonateListExcel from "./report/DonateListExcel";

export default function ToiJeeListMain() {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const user = useSelector((state) => state.token);
  const [dataSource, setDataSource] = useState([]);
  const [dataSourceHolders, setDataSourceHolders] = useState([]);
  const [customerList, setCustomerList] = useState([]);
  const [loading, setLoading] = useState(false);
  const [dateSelect, setDateSelect] = useState("");
  const [year, setYear] = useState("");
  const [dataSelect, setDataSelect] = useState({});
  const [openDonateDetailModal, setOpenDonateDetailModal] = useState(false);

  useEffect(() => {
    const date = new Date();
    let month = date.getMonth() + 1;
    let year = date.getFullYear();
    if (month > 11) {
      setYear(year + 1);
      setDateSelect(moment().add(1, "years").format("YYYY-MM-DD"));
    } else {
      setYear(year);
      setDateSelect(moment().format("YYYY-MM-DD"));
    }
  }, []);

  // useEffect(() => {
  //   fetchAllData(year);
  // }, [year]);

  const handleAdminSearch = (data) => {
    const sortedValues = data.toSorted((a, b) => b.donate - a.donate);

    setDataSource(sortedValues);
    setDataSourceHolders(sortedValues);
    const uniqueStorename = new Set();
    const uniqueData = sortedValues.filter((item) => {
      if (uniqueStorename.has(item.customer_id)) {
        return false;
      } else {
        uniqueStorename.add(item.customer_id);
        return true;
      }
    });

    console.log("Customers", uniqueData);
    setCustomerList(uniqueData);
  };

  const handlePrintReceipt = (data) => {
    // console.log("MyOrder", data);
    // setOpenOrderDetailModal(false);
    // setOpenModalConfirm(false);
    dispatch(addToiJeeOrder(data));
    Modal.confirm({
      centered: true,
      title: "พิมพ์ใบเสร็จ",
      content: "ต้องการพิมพ์ใบเสร็จ?",
      onOk: () => {
        navigate("/toi-jee-list/receipt");
      },
    });
  };

  const handleClickItem = (data) => {
    // console.log("item", data);
    setDataSelect(data);
    setOpenDonateDetailModal(true);
  };

  const onChangeYear = (data) => {
    setDataSource(data);
  };

  const handleCancelOrder = async (data) => {
    // console.log("cancel order", data);
    setLoading(true);
    await baseAPI
      .put(`/city_pillar_shrine/toi-jee-list`, data, {
        headers: {
          "x-access-token": user.token,
        },
      })
      .then((response) => {
        Modal.success({ content: "แก้ไขข้อมูลสมาชิกสำเร็จ", centered: true });
        // fetchUser();
        const newState = dataSource.map((obj) => {
          if (obj.id === data.id) {
            return { ...obj, ...data };
          }
          return obj;
        });
        // console.log("NEW ARRAY", newState);
        setDataSource(newState);
        // setUsers(newState);
        setLoading(false);
      })
      .catch((error) => {
        // dispatch(addToken({}));
        // navigate("/login");
        Modal.warning({
          title: "คำขอล้มเหลว",
          content: error.message,
          centered: true,
        });
        setLoading(false);
      });

    setOpenDonateDetailModal(false);
  };

  const handleChangeCustomer = (e) => {
    // console.log("Customer_Id", e);
    // console.log("Holder", dataSourceHolders);
    let arrNew = dataSourceHolders.filter((item) => item.customer_id === e);
    // console.log(arrNew);
    setDataSource(arrNew);
  };

  const items = [
    {
      key: "1",
      label: "ร่วมเสี่ยงทาย",
      children: (
        <DonateList
          data={dataSource.filter(
            (order) => order.order_status_id === 1 && order.privilege === 1
          )}
          onClickItem={handleClickItem}
          onPrintReceipt={handlePrintReceipt}
          // onClickItem={handleClickCompleteItem}
          // onClickStore={handleClickStore}
        />
      ),
    },
    {
      key: "2",
      label: "ไม่ร่วมเสี่ยงทาย",
      children: (
        <DonateList
          data={dataSource.filter(
            (order) => order.order_status_id === 1 && order.privilege === 0
          )}
          onClickItem={handleClickItem}
          onPrintReceipt={handlePrintReceipt}
          // onClickItem={handleClickCompleteItem}
          // onClickStore={handleClickStore}
        />
      ),
    },
    {
      key: "3",
      label: "รายการยกเลิก",
      children: (
        <DonateList
          data={dataSource.filter((order) => order.order_status_id !== 1)}
          onClickItem={handleClickItem}
          // onPrintReceipt={handlePrintReceipt}
          // onClick={handleClickCancelItem}
        />
      ),
    },
  ];

  const filterOption = (input, option) =>
    (option?.label ?? "").toLowerCase().includes(input.toLowerCase());

  if (year) {
    return (
      <>
        {user.role === "admin" || user.role === "editor" ? (
          <div>
            <HistorySearch onSearch={handleAdminSearch} />
          </div>
        ) : (
          <div>
            <UserSearch
              onClickItem={handleClickItem}
              onYearChange={onChangeYear}
            />
          </div>
        )}
        <Divider />
        {(user.role === "editor" || user.role === "admin") && (
          <DonateListExcel data={dataSource} />
        )}

        <Select
          showSearch
          placeholder="ค้นหาจากชื่อร้าน"
          optionFilterProp="children"
          style={{ marginTop: "16px", width: "100%" }}
          onChange={handleChangeCustomer}
          // onSearch={handleChangeCustomer}
          filterOption={filterOption}
          options={customerList.map((item) => ({
            value: item.customer_id,
            label: item.customer_storename,
            // item,
          }))}
        />

        <Tabs defaultActiveKey="1" items={items} />

        <DonateDetailModal
          open={openDonateDetailModal}
          data={dataSelect}
          onclose={setOpenDonateDetailModal}
          onCancelOrder={handleCancelOrder}
          // onEdit={handelEditDonate}
          // onPrint={handlePrintReceipt}
        />

        {/* <EditDonateModal onClose/> */}
      </>
    );
  }
}
